    private bool ButtonsFor(bool playerSide) => UseControllerDisplay && (playerSide ? !LeftIsLocalOnly : LeftIsLocalHuman);
    private bool LeftIsLocalHuman =>
        (_mpActive && (_mpLocal || (_mpOnline && !FNF_MonoGame.Engine.MultiplayerSession.IsHost)))
        || (FNF_MonoGame.Engine.MultiplayerSession.Mode == FNF_MonoGame.Engine.MultiplayerSession.MpMode.Psych && !FNF_MonoGame.Engine.PsychOnline.PlaysAsBF);
    /// <summary>Online as the left side: the right side is the other player (arrows).</summary>
    private bool LeftIsLocalOnly => LeftIsLocalHuman && !(_mpActive && _mpLocal);
