    public PlayScene(PlayStateParams parameters)







    {
        Current = this; // PlayState.instance (Nene knife state machine reads health/boyfriend through it)







        _songName = parameters.TargetSong?.SongName ?? parameters.SongName;







        _currentDifficulty = parameters.TargetDifficulty; _mpParamSong = _songName;







        _weekSongs = parameters.WeekSongs;







        _weekSongIndex = parameters.WeekSongIndex;







        _weekId = parameters.WeekId;







        _weekAccumulatedScore = parameters.AccumulatedScore;

        // Psych Engine reflection support: the current PlayScene is the Lua target instance
        FNF_MonoGame.Engine.PsychEngine.MusicBeatState.TargetInstance = this;













        _practiceMode = parameters.PracticeMode;







        _botplay = parameters.BotPlayMode;







        _targetVariation = parameters.TargetVariation;







        _targetInstrumental = parameters.TargetInstrumental;







        _minimalMode = parameters.MinimalMode;







        _startTimestamp = parameters.StartTimestamp;







        _playbackRate = parameters.PlaybackRate; _practiceRate = parameters.PlaybackRate > 0f ? Math.Clamp(parameters.PlaybackRate, 0.5f, 2f) : 1f; DevPracticeEnv();







        _overrideMusic = parameters.OverrideMusic;







        _playtestResults = parameters.PlaytestResults;







        _cameraFollowPoint = parameters.CameraFollowPoint;



        _modPath = parameters.ModPath;











        if (string.IsNullOrEmpty(_modPath))

            _modPath = FNF_MonoGame.Engine.PsychEngine.PsychMods.FindModPathForSong(_songName);



        // Character Select swap only applies in Freeplay; Story Mode weeks must always







        // use the week's intended characters regardless of the saved SelectedCharacter.







        _selectedCharacterVariation = string.IsNullOrEmpty(_weekId)







            ? GetSelectedCharacterVariationId()







            : "bf";







    }















    /// <summary>







    /// Build a PlayStateParams from current state so restart/difficulty-change preserves settings.







    /// </summary>







    private PlayStateParams BuildParams()







    {
        s_w6RetryOf = _songName; s_tmRetryOf = _songName; // week 6: restarts do not replay the cutscene (Song.onSongRetry); tankmen dirs carry over (PlayScene.Tank.cs)








        return new PlayStateParams







        {







            SongName = _songName,







            TargetDifficulty = _currentDifficulty,







            WeekSongs = _weekSongs,







            WeekSongIndex = _weekSongIndex,







            WeekId = _weekId,







            AccumulatedScore = _weekAccumulatedScore,







            PracticeMode = _practiceMode,







            BotPlayMode = _botplay,







            TargetVariation = _targetVariation,







            TargetInstrumental = _targetInstrumental,







            MinimalMode = _minimalMode,







            StartTimestamp = _startTimestamp,







            PlaybackRate = _playbackRate,







            OverrideMusic = _overrideMusic,







            PlaytestResults = _playtestResults,







            CameraFollowPoint = _cameraFollowPoint,



            ModPath = _modPath



        };







    }















    















