    // Static stage props loaded from JSON (position, scale, scroll per prop)















    public class StaticStageProp















    {
        public int Seq = ++s_propSeq; // creation order; tie-break for equal zIndex (Stage.refresh is a stable sort)















        public Texture2D Texture;

        public virtual void UpdateAnimation(float dt)
        {
            if (Sheet == null || !AnimPlaying)
                return;

            if (Animations != null && Animations.TryGetValue(CurrentAnimation ?? "", out var anim) && anim.FrameRects.Count > 0)
            {
                float frameDuration = anim.FrameDuration;
                if (frameDuration <= 0) return;

                AnimTimer += dt;
                while (AnimTimer >= frameDuration)
                {
                    AnimTimer -= frameDuration;
                    CurrentFrame++;
                    if (CurrentFrame >= anim.FrameRects.Count)
                    {
                        if (anim.Loop)
                            CurrentFrame = 0;
                        else
                        {
                            CurrentFrame = anim.FrameRects.Count - 1;
                            AnimPlaying = false;
                            OnAnimationFinished?.Invoke(CurrentAnimation);
                            break;
                        }
                    }
                }

                if (CurrentFrame < 0) CurrentFrame = 0;
                if (CurrentFrame >= anim.FrameRects.Count) CurrentFrame = anim.FrameRects.Count - 1;
                SourceRect = anim.FrameRects[CurrentFrame];
                Texture = Sheet.Texture;
            }
        }















        public float X, Y;
        /// <summary>Psych Lua sprites only (null otherwise): flixel offset (set by updateHitbox) and hitbox size
        /// (null = untrimmed frame size). Visual left = x - offset + frameW/2*(1-scale) + trim*scale.</summary>
        public float? PsychOffsetX, PsychOffsetY, PsychHitW, PsychHitH;
        /// <summary>ModchartSprite.animOffsets (addOffset); playAnim applies offset.set(animOffsets[name]).</summary>
        public Dictionary<string, Vector2> PsychAnimOffsets;















        public float ScaleX, ScaleY;















        public float Alpha;















        public float ScrollX, ScrollY;















        public int ZIndex;















        public string Name;















        public string Blend;















        public Color? OverlayColor;















        public bool FlipX;







        public bool FlipY;
        // Psych Lua/HScript exact names (flixel FlxSprite): color (RGB int, via OverlayColor tint), offset.x/y (flixel offset)
        public PsychOffsetView offset => new PsychOffsetView(this);
        /// <summary>FlxObject.scrollFactor (getProperty('spr.scrollFactor.x')).</summary>
        public HxPoint scrollFactor => new HxPoint(() => ScrollX, v => ScrollX = v, () => ScrollY, v => ScrollY = v);
        public sealed class PsychOffsetView
        {
            private readonly StaticStageProp _p; public PsychOffsetView(StaticStageProp p) { _p = p; }
            public float x { get => _p.PsychOffsetX ?? 0f; set { _p.PsychOffsetX = value; } }
            public float y { get => _p.PsychOffsetY ?? 0f; set { _p.PsychOffsetY = value; } }
            public void set(float x = 0f, float y = 0f) { _p.PsychOffsetX = x; _p.PsychOffsetY = y; }
        }







        public float Angle;
        public bool Visible = true;
        public object CameraObj; // HScript FlxCamera (extra camera) the sprite renders on
        /// <summary>FlxSprite.camera / cameras from HScript: an FlxCamera created by the script, or camGame/camHUD/camOther.</summary>
        public object camera
        {
            get => CameraObj ?? (object)Camera;
            set
            {
                if (value is HxFlxCamera hc) { CameraObj = hc; Camera = "hxcam"; }
                else if (value is FNF_MonoGame.Engine.PsychEngine.PsychCamera pc) { CameraObj = null; Camera = pc == FNF_MonoGame.Engine.PsychEngine.PsychCamera.HudCam ? "hud" : pc == FNF_MonoGame.Engine.PsychEngine.PsychCamera.OtherCam ? "other" : "game"; }
                else if (value is string str) { CameraObj = null; Camera = str; }
            }
        }
        public object cameras { get => new object[] { camera }; set { var f = value is System.Collections.IList l ? (l.Count > 0 ? l[0] : null) : HxUtil.ArrayFirst(value); if (f != null) camera = f; } }
        public string Camera;

        // Animated sprite support (Sparrow/JSON spritesheet)
        public SpriteSheet Sheet;
        public Rectangle? SourceRect;
        public string CurrentAnimation;
        public int CurrentFrame;
        public float AnimTimer;
        public bool AnimPlaying = true;
        public Dictionary<string, ModchartAnimation> Animations;

        public event Action<string> OnAnimationFinished;
        public float AnimFramerate = 24f;
        public bool AnimLoop = true;
        public int[] AnimIndices;

        // Psych Engine Lua reflection uses lowercase property names.
        public float x { get => X; set => X = value; }
        public float y { get => Y; set => Y = value; }
        public float alpha { get => Alpha; set => Alpha = value; }
        public float scaleX { get => ScaleX; set => ScaleX = value; }
        public float scaleY { get => ScaleY; set => ScaleY = value; }
        public float angle { get => Angle; set => Angle = value; }
        public bool flipX { get => FlipX; set => FlipX = value; }
        public bool flipY { get => FlipY; set => FlipY = value; }
        public bool visible { get => Visible; set => Visible = value; }

        // flixel FlxSprite.width/height = hitbox (updateHitbox: frameWidth*|scale|), frameWidth/frameHeight = current frame's untrimmed size
        public float width => PsychOffsetX.HasValue ? PsychPropSize(this).W : (Texture?.Width ?? 0) * ScaleX;
        public float height => PsychOffsetX.HasValue ? PsychPropSize(this).H : (Texture?.Height ?? 0) * ScaleY;
        public int frameWidth => (int)PsychFrameInfo(this).W;
        public int frameHeight => (int)PsychFrameInfo(this).H;
        public int color { get { var c = OverlayColor ?? Color.White; return (c.R << 16) | (c.G << 8) | c.B; } set { int v = value & 0xFFFFFF; OverlayColor = v == 0xFFFFFF ? (Color?)null : new Color((v >> 16) & 0xFF, (v >> 8) & 0xFF, v & 0xFF); } } // FlxColor int (Lua/HScript)
        public float scrollX { get => ScrollX; set => ScrollX = value; }
        public float scrollY { get => ScrollY; set => ScrollY = value; }
        /// <summary>FlxSprite.scale (getProperty('spr.scale.y'), startTween(.., {['scale.x'] = ..})).</summary>
        public HxPoint scale => new HxPoint(() => ScaleX, v => ScaleX = v, () => ScaleY, v => ScaleY = v);















    }















