    // Animated stage props (P1)















    internal static int s_propSeq;
    private struct AnimatedStageProp















    {
        public int Seq; // creation order of stage-JSON props (0 = unknown); tie-break for equal zIndex















        public AnimatedSprite Sprite;















        public int ZIndex;















        public float Alpha;















        public float ScrollX, ScrollY;















        public int DanceEvery; // dance on beat interval (0 = no dance)















        public int LastDanceBeat;















        public string Name; // prop name from stage JSON (e.g., "fastCar")















        public string[] DanceAnimNames; // animation names for dance alternation (e.g., ["danceLeft","danceRight"])















        public bool DanceToggle; // alternates between dance anims















        public Color? OverlayColor;















        public SpriteSheet DarkSheet; // dark variant for nene-dark TextureSwap shader















        public bool ApplyStageMatrix;















        public Dictionary<string, string> AnimNameMap; // maps JSON animation name -> actual spritesheet key















        public Dictionary<string, bool> AnimLoops; // maps JSON animation name -> looped flag















        public bool CanPlayOtherAnims; // false while a non-interruptible animation is playing (matches original Bopper)















        public float Angle;







        public bool FlipY;







