    public void AbotReactToNoteKind(string kind)
    {
        if (_abotPupilSprite == null || string.IsNullOrEmpty(kind) || string.IsNullOrEmpty(_abotPupilAnim)) return;
        if (kind.Equals("weekend-1-lightcan", StringComparison.OrdinalIgnoreCase))
            _abotPupilSprite.PlayRangeThenPause(_abotPupilAnim, 0, 17);   // movePupilsLeft
        else if (kind.Equals("weekend-1-cockgun", StringComparison.OrdinalIgnoreCase))
            _abotPupilSprite.PlayRangeThenPause(_abotPupilAnim, 17, 30);  // movePupilsRight
    }

