    public override void Load()















    {















        // Register this scene as PlayState for Lua/HScript reflection.
        FNF_MonoGame.Engine.PsychEngine.ReflectionFunctions.RegisterClass("PlayState", this);
        FNF_MonoGame.Engine.PsychEngine.ReflectionFunctions.RegisterClass("states.PlayState", this); // Psych 1.0 class path
        FNF_MonoGame.Engine.PsychEngine.MusicBeatState.TargetInstance = this;

        // Register mod path so audio and assets can be resolved from the mod folder
        if (!string.IsNullOrEmpty(_modPath))
        {
            if (!Audio.ExtraContentRoots.Contains(_modPath))
                Audio.ExtraContentRoots.Add(_modPath);
            Assets.AddExtraRoot(_modPath);
            // PsychMods.CurrentModDirectory is the mod folder name, not a full path.
            string currentModName = GetPsychModName(_modPath) ?? "";
            PsychMods.CurrentModDirectory = currentModName;
            Console.WriteLine($"[MODS] Added mod content root: {_modPath} (current mod: {currentModName})");
        }

        // Psych Engine: assets resolve through ALL enabled mods and the global
        // mods folder, not only the song's own mod (Paths.modFolders order).
        foreach (var enabledMod in PsychMods.GetAllMods().Where(m => m.Enabled))
        {
            string modPath = PsychMods.GetModDirectory(enabledMod.Name);
            if (!string.IsNullOrEmpty(modPath))
                Assets.AddExtraRoot(modPath);
        }
        string allModsRoot = PsychPaths.Mods();
        if (!string.IsNullOrEmpty(allModsRoot) && global::FNF_MonoGame.Engine.FsCI.DirectoryExists(allModsRoot))
            Assets.AddExtraRoot(allModsRoot);

        // Enable face button note input for gameplay















        Input.GameplayMode = true;































        // Load chart with chosen difficulty (lightweight: JSON parse only)















        // Original FreeplayState: the selected character picks the song VARIATION, and the whole variation is
        // loaded (its own chart + metadata: characters, stage, note style). Bopeebo with Pico = pico-playable,
        // nene, mainStageErect. Previously only the player was swapped onto the default chart (Pico + GF on
        // the normal stage). Audio stays in the base song folder and is picked by _selectedCharacterVariation.
        string chartSong = _songName;
        if (!string.IsNullOrEmpty(_selectedCharacterVariation) && _selectedCharacterVariation != "bf"
            && !_songName.EndsWith("_" + _selectedCharacterVariation, StringComparison.OrdinalIgnoreCase)
            && (global::FNF_MonoGame.Engine.FsCI.DirectoryExists(System.IO.Path.Combine(FNF_MonoGame.Engine.AssetManager.ContentRoot, "songs", $"{_songName.Replace('-', '_')}_{_selectedCharacterVariation}", "charts"))
                || FNF_MonoGame.Engine.VSliceMods.Resolve($"songs/{_songName.Replace('-', '_')}_{_selectedCharacterVariation}/charts/meta.json") != null)) // V-Slice mod variation (QT blissful 'pico')
            chartSong = $"{_songName.Replace('-', '_')}_{_selectedCharacterVariation}";
        _chart = Chart.Load(chartSong, Assets, _currentDifficulty, _modPath); PsoOverrideChart(); // Psych Online: play the room's exact Psych chart (PlayScene.PsychOnline.cs)































        // Initialize conductor (handles timing)















        _conductor = new Conductor(_chart.BPM);































        // Set BPM changes from chart data















        if (_chart.BPMChanges.Count > 0)















            _conductor.SetBPMChanges(_chart.BPMChanges);































        // Initialize note field















        _noteField = new NoteField(_chart, _conductor) { ScrollSpeed = (float)_chart.Speed };































        // Cache paths for phased loading















        _resolvedNoteSkinPath = ResolveNoteSkinPath(_chart.NoteStyle);















        _resolvedStageFolder = ResolveStageFolder(_chart.Stage);





































        // Read preferences from save data (lightweight)















        var saveData = HighscoreManager.Data;















        _downscroll = System.Environment.GetEnvironmentVariable("FNF_DOWNSCROLL") is string __ds ? __ds == "1" : saveData.Downscroll; // dev hook FNF_DOWNSCROLL=1|0















        _middlescroll = saveData.Middlescroll; if (!string.IsNullOrEmpty(_modPath)) { if (_middlescroll) FNF_MonoGame.Engine.PsychEngine.ClientPrefs.Data.MiddleScroll = true; _middlescroll = false; } // Psych: ClientPrefs.data.middleScroll (PlayState.generateStaticArrows)















        _globalOffset = saveData.GlobalOffset;















        _flashingLightsEnabled = saveData.FlashingLights;















        _cameraZoomEnabled = saveData.CameraZoom;































        // Start phased loading















        _playLoading = true;















        _playLoadPhase = 0;















        _playLoadStatus = "Loading notes...";















    }































    /// <summary>















    /// Process one loading phase per frame for PlayScene.















    /// </summary>















    private void ProcessPlayLoadPhase()















    {















        switch (_playLoadPhase)















        {















            case 0:















                _playLoadStatus = "Loading notes...";















                _notesSheet = SpriteSheet.Load(Game, $"{_resolvedNoteSkinPath}/notes")















                           ?? SpriteSheet.Load(Game, $"{_resolvedNoteSkinPath}/arrows")















                           ?? SpriteSheet.Load(Game, "game/skins/default/notes");















                _receptorsSheet = SpriteSheet.Load(Game, $"{_resolvedNoteSkinPath}/receptors")















                               ?? SpriteSheet.Load(Game, $"{_resolvedNoteSkinPath}/arrows")















                               ?? SpriteSheet.Load(Game, "game/skins/default/receptors");















                _splashesSheet = SpriteSheet.Load(Game, $"{_resolvedNoteSkinPath}/splashes")















                              ?? SpriteSheet.Load(Game, "game/skins/default/splashes");















                _holdCoverSheet = SpriteSheet.Load(Game, $"{_resolvedNoteSkinPath}/holdCover")















                               ?? SpriteSheet.Load(Game, "game/skins/default/holdCover");















                CacheNoteFrames();















                break;















            case 1:















                _playLoadStatus = "Loading stage...";















                LoadStageTextures(_resolvedStageFolder);



        // Load Psych Engine Lua/Haxe stage sprites after base stage textures so they are not cleared.

        if (!string.IsNullOrEmpty(_modPath))

            LoadPsychStageSprites(_chart.Stage ?? "stage");















                break;















            case 2:















                _playLoadStatus = "Loading UI...";















                _healthBarBG = Assets.LoadTexture("game/ui/healthBar.png");















                _readyTex = Assets.LoadTexture($"{_resolvedNoteSkinPath}/countdown/ready.png");















                if (_readyTex == Assets.Pixel) _readyTex = Assets.LoadTexture("game/skins/default/countdown/ready.png");















                _setTex = Assets.LoadTexture($"{_resolvedNoteSkinPath}/countdown/set.png");















                if (_setTex == Assets.Pixel) _setTex = Assets.LoadTexture("game/skins/default/countdown/set.png");















                _goTex = Assets.LoadTexture($"{_resolvedNoteSkinPath}/countdown/go.png");















                if (_goTex == Assets.Pixel) _goTex = Assets.LoadTexture("game/skins/default/countdown/go.png"); NsPreload(); PsyPopPreload();















                break;















            case 3:















                _playLoadStatus = "Loading ratings...";















                _ratingSickTex = Assets.LoadTexture($"{_resolvedNoteSkinPath}/ratings/sick.png");















                if (_ratingSickTex == Assets.Pixel) _ratingSickTex = Assets.LoadTexture("game/skins/default/ratings/sick.png");















                _ratingGoodTex = Assets.LoadTexture($"{_resolvedNoteSkinPath}/ratings/good.png");















                if (_ratingGoodTex == Assets.Pixel) _ratingGoodTex = Assets.LoadTexture("game/skins/default/ratings/good.png");















                _ratingBadTex = Assets.LoadTexture($"{_resolvedNoteSkinPath}/ratings/bad.png");















                if (_ratingBadTex == Assets.Pixel) _ratingBadTex = Assets.LoadTexture("game/skins/default/ratings/bad.png");















                _ratingShitTex = Assets.LoadTexture($"{_resolvedNoteSkinPath}/ratings/shit.png");















                if (_ratingShitTex == Assets.Pixel) _ratingShitTex = Assets.LoadTexture("game/skins/default/ratings/shit.png"); VsApplyNoteStyleRatings(); // V-Slice mod note style judgements (PlayScene.VSliceNoteStyle.cs)















                for (int d = 0; d < 10; d++)















                {















                    _comboDigitTex[d] = Assets.LoadTexture($"{_resolvedNoteSkinPath}/comboNumbers/num{d}.png");















                    if (_comboDigitTex[d] == Assets.Pixel)















                        _comboDigitTex[d] = Assets.LoadTexture($"game/skins/default/comboNumbers/num{d}.png");















                }















                bool anyMissing = false;















                for (int d = 0; d < 10; d++)















                    if (_comboDigitTex[d] == Assets.Pixel) { anyMissing = true; break; }















                if (anyMissing)















                {















                    _comboStripTex = Assets.LoadTexture($"{_resolvedNoteSkinPath}/combo.png");















                    if (_comboStripTex == Assets.Pixel)















                        _comboStripTex = Assets.LoadTexture("game/skins/default/combo.png");















                    if (_comboStripTex != null && _comboStripTex != Assets.Pixel)















                    {















                        int digitW = _comboStripTex.Width / 10;















                        int digitH = _comboStripTex.Height;















                        _comboStripRects = new Rectangle[10];















                        for (int d = 0; d < 10; d++)















                            _comboStripRects[d] = new Rectangle(d * digitW, 0, digitW, digitH);















                    }















                }















                break;















            case 4:















                _playLoadStatus = "Loading characters...";















                LoadCharacters();















                break;















            case 5:















                _playLoadStatus = "Starting...";















                PreloadGameplaySounds();















                LoadDialogue();















                FinishPlayLoading();















                return;















        }















        _playLoadPhase++;















    }































    /// <summary>















    /// Called when all PlayScene phased loading is complete.















    /// </summary>















    private void FinishPlayLoading()















    {















        // Psych Engine BaseStage: create default stage and run createPost

        if (_stages.Count == 0)

            CreateDefaultStage();

        // Psych Engine: load and start all Lua scripts (scripts/, data/{song}/,
        // stages/{stage}.lua, custom_notetypes/, custom_events/) then fire onCreate
        // Psych sets songName = SONG.song and curStage = SONG.stage before scripts are created.
        FNF_MonoGame.Engine.PsychEngine.PsychGlobals.CurrentSong = !string.IsNullOrEmpty(Chart?.DisplayName) ? Chart.DisplayName : (Chart?.SongName ?? _songName ?? "");
        FNF_MonoGame.Engine.PsychEngine.PsychGlobals.CurrentStage = Chart?.Stage ?? "stage";
        FNF_MonoGame.Engine.PsychEngine.PsychGlobals.CurrentBPM = Chart != null && Chart.BPM > 0 ? Chart.BPM : 100f; // Conductor.bpm = SONG.bpm before scripts (bpm/curBpm/crochet globals)
        LoadPsychLuaScripts();
        /* onCreate is called per script at load (FunkinLua.new) */

        if (PsychNotes) PsychCountdownBegin(); /* PlayState.create 611: startCallback() = startCountdown() runs before onCreatePost */ VSliceScriptsBegin(); VsCountdownStartChecked(); /* PlayState.startCountdown -> COUNTDOWN_START (after onSongLoaded) */ DispatchCreatePost();
        // (removed duplicate Lua callback; fired once by the matching Dispatch*() above — Psych calls each callback once)

        DispatchAllEventsPushed();















        if (_dialogueActive)















            _countdownActive = false;















        else















            _countdownActive = true;















        _countdownTimer = 0;















        _countdownStep = 0;
        if (!PsychNotes) PsychCountdownBegin(); // Psych startCountdown() (PlayScene.PsychDialogue.cs); Psych mods: before onCreatePost above















        _healthLerp = HEALTH_STARTING;















        BuildPauseMenuItems();































        if (_deathCounterSong != _songName)















        {















            _deathCounter = 0;















            _deathCounterSong = _songName;















        }































        float beatDuration = (float)_conductor.Crochet;















        Console.WriteLine($"Song: {_songName}, BPM: {_chart.BPM}, Beat: {beatDuration}s, Downscroll: {_downscroll}, Middlescroll: {_middlescroll}"); PreloadBeforeSongStart(); MpOnLoaded(); // original: everything is loaded before the countdown (PlayScene.Preload.cs)















        _playLoading = false;































        // Set Discord status (matching original FNF format)















        string opponentName = _opponent?.Name ?? _chart?.OpponentCharacter ?? "dad";















        bool isStoryMode = _weekSongs != null;















        string weekName = isStoryMode ? _weekId : null;















        Game.Discord?.SetGameplayStart(_songName, _currentDifficulty, _chart?.Album, opponentName);















        Game.Discord?.UpdateGameplayPresence(_songName, _currentDifficulty, isStoryMode, weekName, _practiceMode, _botplay);















    }















    















    /// <summary>















    /// Load dialogue conversation if this song has one (M3).















    /// Dialogue JSON files are at data/dialogue/conversations/{songName}.json.















    /// </summary>















    private void LoadDialogue()















    { if (SsfOnCountdownStart()) return; if (W5HorrorInit()) return; if (DoppelInit()) return; // phillyTrainErect.hxc doppelganger intro (PlayScene.Doppelganger.cs)
 // winter horrorland intro (PlayScene.Week5.cs) // spaghetti: sserafim.hxc intro cutscene (PlayScene.Sserafim.cs)
        if (W1Init()) return; // weekend 1: darnell.hxc intro cutscene (PlayScene.W1Cutscene.cs)
        if (VideoStartInit()) return; // week 7 video cutscenes (PlayScene.VideoCutscene.cs)
        if (W6Init() || _w6SongId != null) return; // week 6: V-Slice song scripts + Conversation (PlayScene.Week6.cs)
















        string convPath = Assets.ResolvePath($"data/dialogue/conversations/{_songName}.json");















        if (convPath == null) return;















        















        try















        {















            var conv = Newtonsoft.Json.JsonConvert.DeserializeObject<ConversationJson>(global::FNF_MonoGame.Engine.FsCI.ReadAllText(convPath));















            if (conv?.Dialogue == null || conv.Dialogue.Count == 0) return;















            















            _dialogueLines = new List<DialogueLine>();















            foreach (var entry in conv.Dialogue)















            {















                string text = entry.Text != null ? string.Join(" ", entry.Text) : "";















                _dialogueLines.Add(new DialogueLine















                {















                    Speaker = entry.Speaker ?? "",















                    Text = text















                });















            }















            















            if (_dialogueLines.Count > 0)















            {















                _dialogueActive = true;















                _dialogueIndex = 0;















                _dialogueCharIndex = 0;















                _dialogueCharTimer = 0;















                _dialogueCurrentText = "";















                _dialogueSpeakerName = _dialogueLines[0].Speaker;















                _dialogueFadeAlpha = 0;















                _dialogueFadingIn = true;















            }















        }















        catch { }















    }















    















    /// <summary>















    /// Update dialogue text reveal and input handling (M3).















    /// </summary>















    private void UpdateDialogue(float dt)















    {
        if (_w6Active) { W6UpdateBlocked(dt); return; }
        if (_w1Active) { W1UpdateBlocked(dt); return; } if (_ssfCutscene) { SsfUpdateBlocked(dt); return; } if (_w5Horror) { W1UpdateBlocked(dt); return; } if (_dpActive) { DoppelUpdateBlocked(dt); return; }
        if (_vidHoldCountdown) { W1UpdateBlocked(dt); return; } // video cutscene before the countdown
        if (_vsHoldCountdown) { VsHoldUpdate(dt); return; } // V-Slice script cancelled COUNTDOWN_START (PlayScene.VSliceCutscene.cs)
        if (_psychHold) { PsychHoldUpdate(dt); return; } // Psych onStartCountdown -> Function_Stop (dialogue etc.)
















        // Fade in















        if (_dialogueFadingIn)















        {















            _dialogueFadeAlpha = Math.Min(1f, _dialogueFadeAlpha + dt * 2f);















            if (_dialogueFadeAlpha >= 1f) _dialogueFadingIn = false;















        }















        















        if (_dialogueLines == null || _dialogueIndex >= _dialogueLines.Count)















        {















            EndDialogue();















            return;















        }















        















        var line = _dialogueLines[_dialogueIndex];















        _dialogueSpeakerName = line.Speaker;















        















        // Type text character by character















        if (_dialogueCharIndex < line.Text.Length)















        {















            _dialogueCharTimer += dt;















            float charSpeed = 0.03f;















            while (_dialogueCharTimer >= charSpeed && _dialogueCharIndex < line.Text.Length)















            {















                _dialogueCharTimer -= charSpeed;















                _dialogueCharIndex++;















                _dialogueCurrentText = line.Text[.._dialogueCharIndex];















            }















        }















        















        // Advance on confirm















        if (Input.CutsceneAdvancePressed)















        {















            if (_dialogueCharIndex < line.Text.Length)















            {















                // Complete current line instantly















                _dialogueCharIndex = line.Text.Length;
                CallOnLuas("onSkipDialogue", _dialogueIndex);















                _dialogueCurrentText = line.Text;















            }















            else















            {















                // Next line















                _dialogueIndex++;
                CallOnLuas("onNextDialogue", _dialogueIndex);















                if (_dialogueIndex >= _dialogueLines.Count)















                {















                    EndDialogue();















                }















                else















                {















                    _dialogueCharIndex = 0;















                    _dialogueCharTimer = 0;















                    _dialogueCurrentText = "";















                }















            }















        }















        















        // Skip dialogue on back button















        if (Input.CutsceneBackPressed)















        {















            EndDialogue();















        }















    }















    















    private void EndDialogue()















    {















        _dialogueActive = false;















        _countdownActive = true;















        _countdownTimer = 0;















        _countdownStep = 0;
        PsychCountdownBegin(); // Psych startCountdown() (PlayScene.PsychDialogue.cs)















    }















    















    private void DrawDialogue(SpriteBatch spriteBatch)















    {
        if (_w6Active || _psychHold) return;
















        if (!_dialogueActive) return;















        















        // Dim background















        spriteBatch.Draw(Assets.Pixel,















            new Rectangle(0, 0, FNFGame.SCREEN_WIDTH, FNFGame.SCREEN_HEIGHT),















            Color.Black * 0.5f * _dialogueFadeAlpha);















        















        // Dialogue box at bottom















        int boxH = 180;















        int boxY = FNFGame.SCREEN_HEIGHT - boxH - 30;















        int boxX = 40;















        int boxW = FNFGame.SCREEN_WIDTH - 80;















        















        spriteBatch.Draw(Assets.Pixel,















            new Rectangle(boxX, boxY, boxW, boxH),















            _dialogueBoxColor * _dialogueFadeAlpha);















        















        // Border















        spriteBatch.Draw(Assets.Pixel, new Rectangle(boxX, boxY, boxW, 3), Color.White * 0.6f * _dialogueFadeAlpha);















        















        // Speaker name















        if (!string.IsNullOrEmpty(_dialogueSpeakerName))















        {















            var nameFont = Assets.GetFont(22);















            if (nameFont != null)















            {















                string displayName = _dialogueSpeakerName.Replace("-", " ").Replace("_", " ");















                displayName = System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(displayName);















                nameFont.DrawText(spriteBatch, displayName,















                    new Vector2(boxX + 20, boxY + 12), Color.Yellow * _dialogueFadeAlpha);















            }















        }















        















        // Dialogue text















        var textFont = Assets.GetFont(20);















        if (textFont != null && !string.IsNullOrEmpty(_dialogueCurrentText))















        {















            // Simple word wrap















            string wrapped = WrapText(textFont, _dialogueCurrentText, boxW - 40);















            textFont.DrawText(spriteBatch, wrapped,















                new Vector2(boxX + 20, boxY + 45), Color.White * _dialogueFadeAlpha);















        }















        















        // Continue hint















        if (_dialogueCharIndex >= (_dialogueLines?[Math.Min(_dialogueIndex, _dialogueLines.Count - 1)]?.Text?.Length ?? 0))















        {















            var hintFont = Assets.GetFont(14);















            if (hintFont != null)















            {















                hintFont.DrawText(spriteBatch, "Press ENTER to continue...",















                    new Vector2(boxX + boxW - 220, boxY + boxH - 25), Color.Gray * _dialogueFadeAlpha);















            }















        }















    }















    















    private static string WrapText(FontStashSharp.SpriteFontBase font, string text, int maxWidth)















    {















        if (string.IsNullOrEmpty(text)) return text;















        var words = text.Split(' ');















        var result = new System.Text.StringBuilder();















        string currentLine = "";















        















        foreach (var word in words)















        {















            string testLine = string.IsNullOrEmpty(currentLine) ? word : currentLine + " " + word;















            var size = font.MeasureString(testLine);















            if (size.X > maxWidth && !string.IsNullOrEmpty(currentLine))















            {















                result.AppendLine(currentLine);















                currentLine = word;















            }















            else















            {















                currentLine = testLine;















            }















        }















        if (!string.IsNullOrEmpty(currentLine))















            result.Append(currentLine);















        















        return result.ToString();















    }















    















