    private void LoadCharacters()















    {















        string playerName = _chart.PlayerCharacter ?? "bf";















        string opponentName = _chart.OpponentCharacter ?? "dad";















        string gfName = _chart.GirlfriendCharacter ?? "gf";































        // Ensure stage character slot data is available even if phased stage loading















        // couldn't populate pending arrays for this song variation.















        EnsurePendingStageCharacterData(ResolveStageFolder(_chart.Stage));































        if (_selectedCharacterVariation.Equals("pico", StringComparison.OrdinalIgnoreCase)















            && SongSupportsAudioVariation(_songName, "pico")















            && !playerName.Contains("pico", StringComparison.OrdinalIgnoreCase))















        {















            playerName = "pico-playable";















        }































        // Keep chart runtime character in sync with playable variation so voice loading















        // and other runtime systems use the same character as gameplay rendering.















        _chart.PlayerCharacter = playerName;















        















        // Map character variants to their sprite folders















        // e.g. "pico-playable" ? "pico" (same sprites, just playable flag)















        string playerSprite = ResolveCharacterSprite(playerName);















        string opponentSprite = ResolveCharacterSprite(opponentName);















        string gfSprite = ResolveCharacterSprite(gfName);















        















        // FNF character positions from original PlayState















        // Player on right, opponent on left, GF center-back on speakers















        // Scale is set by Character.LoadSprites from character JSON (default 1.0)















        // Psych Online: the bf-side player's skin character (PlayState.initPlayCharacter)
        bool __psoPrevActive = Character.PsychStageActive;
        var __psoSkinR = FNF_MonoGame.Engine.PsychOnline.SkinFor(true, playerName); string __psoModR = FNF_MonoGame.Engine.PsychEngine.PsychMods.CurrentModDirectory;
        if (__psoSkinR != null) { RegisterSkinIconMod(__psoSkinR.Value.name, __psoSkinR.Value.mod); Console.WriteLine($"[PSO] skin {__psoSkinR.Value.name} ({__psoSkinR.Value.mod}) replaces {playerName}"); playerName = __psoSkinR.Value.name; playerSprite = ResolveCharacterSprite(playerName); FNF_MonoGame.Engine.PsychEngine.PsychMods.CurrentModDirectory = __psoSkinR.Value.mod; Character.PsychStageActive = FNF_MonoGame.Engine.PsychOnline.IsPsychCharacter(__psoSkinR.Value.name, __psoSkinR.Value.mod); }
        _boyfriend = new Character(playerSprite, 800, 280);















        _boyfriend.LoadJsonData(Assets, playerName);















        _boyfriend.SetFlipForRole(true); // Player role















        _boyfriend.StepCrochet = (float)_conductor.StepCrochet;















        _boyfriend.LoadSprites(Game);
        if (__psoSkinR != null) { FNF_MonoGame.Engine.PsychEngine.PsychMods.CurrentModDirectory = __psoModR; Character.PsychStageActive = __psoPrevActive; }







        _boyfriend.PlayAnimation("idle", force: true);







        _boyfriend.CreateNormalChar(Game, Assets);















        var __psoSkinL = FNF_MonoGame.Engine.PsychOnline.SkinFor(false, opponentName); string __psoModL = FNF_MonoGame.Engine.PsychEngine.PsychMods.CurrentModDirectory;
        if (__psoSkinL != null) { RegisterSkinIconMod(__psoSkinL.Value.name, __psoSkinL.Value.mod); Console.WriteLine($"[PSO] skin {__psoSkinL.Value.name} ({__psoSkinL.Value.mod}) replaces {opponentName}"); opponentName = __psoSkinL.Value.name; opponentSprite = ResolveCharacterSprite(opponentName); FNF_MonoGame.Engine.PsychEngine.PsychMods.CurrentModDirectory = __psoSkinL.Value.mod; Character.PsychStageActive = FNF_MonoGame.Engine.PsychOnline.IsPsychCharacter(__psoSkinL.Value.name, __psoSkinL.Value.mod); }
        _opponent = new Character(opponentSprite, 80, 230);















        _opponent.LoadJsonData(Assets, opponentName);















        _opponent.SetFlipForRole(false); // Opponent role















        _opponent.StepCrochet = (float)_conductor.StepCrochet;















        _opponent.LoadSprites(Game);
        if (__psoSkinL != null) { FNF_MonoGame.Engine.PsychEngine.PsychMods.CurrentModDirectory = __psoModL; Character.PsychStageActive = __psoPrevActive; }







        _opponent.PlayAnimation("idle", force: true);







        _opponent.CreateNormalChar(Game, Assets);















        // Only create separate GF if opponent is not GF















        if (opponentName != "gf" && opponentSprite != "gf" && !GfSuppressedBySongOrStage(gfName))















        {















            // Use dedicated character classes based on GF type







            _girlfriend = gfName.ToLower() switch







            {







                "otis-speaker" => new Otis(gfSprite, 370, 80),







                "pico-speaker" => new PicoSpeaker(gfSprite, 370, 80),







                "nene" or "nene-christmas" or "nene-tankmen" or "nene-speakers" or "nene-dark" or "nene-pixel" => new Nene(gfSprite, 370, 80),







                _ => new Girlfriend(gfSprite, 370, 80)







            };















            _girlfriend.LoadJsonData(Assets, gfName);















            _girlfriend.SetFlipForRole(false); // GF is not player















            _girlfriend.StepCrochet = (float)_conductor.StepCrochet;















            _girlfriend.LoadSprites(Game);







            _girlfriend.PlayAnimation("idle", force: true);







            _girlfriend.CreateNormalChar(Game, Assets);















            // Load HaxeFlixel mod script for this character if it exists
            // (Windows-only; uses the JIT-based HaxeScriptRuntime DLL which is not available on Xbox)
#if !XBOX_UWP
            var modBridge = new HaxeFlixelModBridge();
            modBridge.LoadCharacterScript(_girlfriend, _girlfriend.OriginalName ?? gfSprite);
#endif







        }































        // Cache character icons � try multiple icon paths (original FNF: preload/images/icons/icon-{name}.png)















        _cachedPlayerSprite = ResolveCharacterSprite(playerName);















        _cachedOpponentSprite = ResolveCharacterSprite(opponentName);















        _playerIcon = LoadCharacterIcon(playerName, _cachedPlayerSprite);















        _opponentIcon = LoadCharacterIcon(opponentName, _cachedOpponentSprite);















        















        // Apply pending stage JSON character positions (saved during LoadStageTextures)



        if (_boyfriend != null) _boyfriend.StageUsesPsychPositioning = _isPsychEngineStage;

        if (_opponent != null) _opponent.StageUsesPsychPositioning = _isPsychEngineStage;

        if (_girlfriend != null) _girlfriend.StageUsesPsychPositioning = _isPsychEngineStage;















        // Original FNF (Stage.hx / BaseCharacter.hx):















        //   character.x = stagePos[0] - characterOrigin.x + globalOffsets[0]















        //   character.y = stagePos[1] - characterOrigin.y + globalOffsets[1]















        // Stage positions represent the character's FEET (bottom-center), not top-left.















        // characterOrigin = (width/2, height) for Sparrow, or composite registration point for animateatlas.















        // Note: globalOffsets (CharOffsets) are applied during Draw() for rendering; they're also















        // accounted for in GetMidpoint() for camera follow calculations.















        if (_pendingBfPos != null && _pendingBfPos.Length >= 2)
















        {
















            _boyfriend.Scale *= _pendingBfScale; _boyfriend.ApplyStagePosition(_pendingBfPos);
















        }

        if (_pendingDadPos != null && _pendingDadPos.Length >= 2)
















        {
















            _opponent.Scale *= _pendingDadScale; _opponent.ApplyStagePosition(_pendingDadPos);
















        }

        if (_pendingGfPos != null && _pendingGfPos.Length >= 2 && _girlfriend != null)















        {















            _girlfriend.Scale *= _pendingGfScale; _girlfriend.ApplyStagePosition(_pendingGfPos);

















        }





























        // Stage JSON cameraOffsets ADD to character JSON cameraOffsets (matches original Stage.hx)















        if (_pendingBfCamOffsets != null && _pendingBfCamOffsets.Length >= 2)















        {















            var charCam = _boyfriend.CameraOffsets;















            _boyfriend.CameraOffsets = new float[]















            {















                (charCam != null && charCam.Length >= 2 ? charCam[0] : 0f) + _pendingBfCamOffsets[0],















                (charCam != null && charCam.Length >= 2 ? charCam[1] : 0f) + _pendingBfCamOffsets[1]















            };















        }















        if (_pendingDadCamOffsets != null && _pendingDadCamOffsets.Length >= 2)















        {















            var charCam = _opponent.CameraOffsets;















            _opponent.CameraOffsets = new float[]















            {















                (charCam != null && charCam.Length >= 2 ? charCam[0] : 0f) + _pendingDadCamOffsets[0],















                (charCam != null && charCam.Length >= 2 ? charCam[1] : 0f) + _pendingDadCamOffsets[1]















            };















        }















        if (_pendingGfCamOffsets != null && _pendingGfCamOffsets.Length >= 2 && _girlfriend != null)















        {















            var charCam = _girlfriend.CameraOffsets;















            _girlfriend.CameraOffsets = new float[]















            {















                (charCam != null && charCam.Length >= 2 ? charCam[0] : 0f) + _pendingGfCamOffsets[0],















                (charCam != null && charCam.Length >= 2 ? charCam[1] : 0f) + _pendingGfCamOffsets[1]















            };















        }































        TryAddNeneSpeakers(gfName);















        // Original tankmanBattlefieldErect.hxc: reposition tankBricks when GF is added.







        // Also lower tankBricks zIndex behind A-Bot so the speakers sit on top of the bricks.







        if (_isTankmanErect)







        {







            for (int i = 0; i < _staticProps.Count; i++)







            {







                if (string.Equals(_staticProps[i].Name, "tankBricks", StringComparison.OrdinalIgnoreCase))







                {







                    var tb = _staticProps[i];







                    tb.X = 445f;







                    tb.Y = 774f;







                    // User fix: bricks should be behind A-Bot, not in front.







                    // A-Bot components range from abotZ-10 (eyeWhites) up to abotZ (body).







                    // Set tankBricks just below the lowest A-Bot component.







                    if (_hasAbotFallback)







                        { } // tankmanBattlefieldErect.hxc only calls setPosition(445, 774): zIndex stays 101 (JSON) = above nene + A-Bot, verified vs the running original (REPORT M.5)







                    _staticProps[i] = tb;







                    Console.WriteLine($"[STREET-DEBUG] tankBricks repositioned to (445, 774) z={tb.ZIndex} for erect stage");







                    break;







                }







            }







            // Re-sort after zIndex change so draw order is correct







            _staticProps = _staticProps.OrderBy(p => p.ZIndex).ToList();







        }















        // Initialize world-space camera to frame the stage















        if (_hasJsonStage || _isPsychEngineStage)















        {















            // Stage JSON cameraOffsets already include the directional constants















            // (e.g., mainStage dad=[150,-100]). Apply them directly � do NOT add the















            // hardcoded +150/-100 on top, or the offset is doubled.















            if (_isPhillyBlazinStage && _girlfriend != null)







            {







                // Philly Blazin: original script centers camera on girlfriend (Nene)







                var gfMid = _girlfriend.GetMidpoint();







                _camWorldX = gfMid.X + 50f;







                _camWorldY = gfMid.Y - 90f;







                _camTargetWorldX = _camWorldX;







                _camTargetWorldY = _camWorldY;







            }







            else if (_isPsychEngineStage && _girlfriend != null && PsychCameraTarget(2) is Microsoft.Xna.Framework.Vector2 psychGfCam)
            { // PlayState.create: camFollow starts on gf (camPos), snapToTarget, then moveCameraSection()
                _camWorldX = _camTargetWorldX = psychGfCam.X; _camWorldY = _camTargetWorldY = psychGfCam.Y;
            }
            else







            {







                var dadMid = _opponent.GetMidpoint();















                float camOffX = _opponent.CameraOffsets?.Length >= 2 ? _opponent.CameraOffsets[0] : 0f;















                float camOffY = _opponent.CameraOffsets?.Length >= 2 ? _opponent.CameraOffsets[1] : 0f;















                _camWorldX = dadMid.X + camOffX;















                _camWorldY = dadMid.Y + camOffY;















                _camTargetWorldX = _camWorldX;















                _camTargetWorldY = _camWorldY;







            }















        }















        // Philly Blazin: original script darkens characters to match the stormy atmosphere







        if (_isPhillyBlazinStage)







        {







            if (_boyfriend != null) _boyfriend.Tint = new Color(222, 222, 222);







            if (_opponent != null) _opponent.Tint = new Color(222, 222, 222);







            if (_girlfriend != null) _girlfriend.Tint = new Color(136, 136, 136);







        }















        // Temporary diagnostic for Weekend 1 stage positioning







        if ((_isPhillyBlazinStage || string.Equals(_chart?.Stage, "phillyStreets", StringComparison.OrdinalIgnoreCase))







            && _boyfriend != null && _opponent != null && _girlfriend != null)







        {







            try







            {







                var sb = new System.Text.StringBuilder();







                sb.AppendLine($"=== {_chart.Stage} POSITION DIAGNOSTIC ===");







                sb.AppendLine($"Camera: ({_camWorldX:0.0},{_camWorldY:0.0}) zoom={_defaultCamZoom:0.00}");







                sb.AppendLine($"BF ({_boyfriend.OriginalName}): pos=({_boyfriend.Position.X:0.0},{_boyfriend.Position.Y:0.0}) mid=({_boyfriend.GetMidpoint().X:0.0},{_boyfriend.GetMidpoint().Y:0.0}) camOff=({_boyfriend.CameraOffsets?[0] ?? 0},{_boyfriend.CameraOffsets?[1] ?? 0})");







                sb.AppendLine($"Dad ({_opponent.OriginalName}): pos=({_opponent.Position.X:0.0},{_opponent.Position.Y:0.0}) mid=({_opponent.GetMidpoint().X:0.0},{_opponent.GetMidpoint().Y:0.0}) camOff=({_opponent.CameraOffsets?[0] ?? 0},{_opponent.CameraOffsets?[1] ?? 0})");







                sb.AppendLine($"GF ({_girlfriend.OriginalName}): pos=({_girlfriend.Position.X:0.0},{_girlfriend.Position.Y:0.0}) mid=({_girlfriend.GetMidpoint().X:0.0},{_girlfriend.GetMidpoint().Y:0.0}) camOff=({_girlfriend.CameraOffsets?[0] ?? 0},{_girlfriend.CameraOffsets?[1] ?? 0})");







                sb.AppendLine($"ABot offsets: ({_abotBodyOffsetX:0.0},{_abotBodyOffsetY:0.0}) base=({(_girlfriend.Position.X + _abotBodyOffsetX):0.0},{(_girlfriend.Position.Y + _abotBodyOffsetY):0.0})");







                sb.AppendLine($"Screen: mid-BF={WorldToScreen(_boyfriend.GetMidpoint().X, _boyfriend.GetMidpoint().Y)} mid-Dad={WorldToScreen(_opponent.GetMidpoint().X, _opponent.GetMidpoint().Y)} mid-GF={WorldToScreen(_girlfriend.GetMidpoint().X, _girlfriend.GetMidpoint().Y)}");







                try { System.IO.File.AppendAllText($"d:\\godt engine custom\\{_chart.Stage}_pos_diag.txt", sb.ToString()); } catch { }







            }







            catch { }







        }















        















        // Pre-fire the first FocusCamera event so the camera starts on the correct character















        // (events don't fire during countdown, but we want proper framing from the start)















        if (_chart.Events != null)















        {















            foreach (var ev in _chart.Events)















            {















                if (ev.Name == "FocusCamera" && ev.Time <= 0.5)















                {















                    // V2 convention: 0=Boyfriend, 1=Dad, 2=Girlfriend.















                    int initFocus = ParseFocusChar(ev.Value);















                    















                    if (initFocus == 0)















                    {















                        var mid = _boyfriend.GetMidpoint();















                        float px = _boyfriend.CameraOffsets?.Length >= 2 ? _boyfriend.CameraOffsets[0] : 0f;















                        float py = _boyfriend.CameraOffsets?.Length >= 2 ? _boyfriend.CameraOffsets[1] : 0f;















                        if (_hasJsonStage)















                        {















                            _camWorldX = _camTargetWorldX = mid.X + px;















                            _camWorldY = _camTargetWorldY = mid.Y + py;















                        }















                        else















                        {















                            _camWorldX = _camTargetWorldX = mid.X - 100 + px;















                            _camWorldY = _camTargetWorldY = mid.Y - 100 + py;















                        }















                    }















                    else if (initFocus == 2 && _girlfriend != null)















                    {















                        var mid = _girlfriend.GetMidpoint();















                        float gx = _girlfriend.CameraOffsets?.Length >= 2 ? _girlfriend.CameraOffsets[0] : 0f;















                        float gy = _girlfriend.CameraOffsets?.Length >= 2 ? _girlfriend.CameraOffsets[1] : 0f;















                        _camWorldX = _camTargetWorldX = mid.X + gx;















                        _camWorldY = _camTargetWorldY = mid.Y + gy;















                    }















                    else















                    {















                        var mid = _opponent.GetMidpoint();















                        float ox = _opponent.CameraOffsets?.Length >= 2 ? _opponent.CameraOffsets[0] : 0f;















                        float oy = _opponent.CameraOffsets?.Length >= 2 ? _opponent.CameraOffsets[1] : 0f;















                        if (_hasJsonStage)















                        {















                            _camWorldX = _camTargetWorldX = mid.X + ox;















                            _camWorldY = _camTargetWorldY = mid.Y + oy;















                        }















                        else















                        {















                            _camWorldX = _camTargetWorldX = mid.X + 150 + ox;















                            _camWorldY = _camTargetWorldY = mid.Y - 100 + oy;















                        }















                    }















                    break;















                }















            }















        }















        // Post-prefire diagnostic for Weekend 1 stage positioning







        if ((_isPhillyBlazinStage || string.Equals(_chart?.Stage, "phillyStreets", StringComparison.OrdinalIgnoreCase))







            && _boyfriend != null && _opponent != null && _girlfriend != null)







        {







            try







            {







                var sb = new System.Text.StringBuilder();







                sb.AppendLine($"=== {_chart.Stage} POST-PREFIRE ===");







                sb.AppendLine($"Camera: ({_camWorldX:0.0},{_camWorldY:0.0}) zoom={_defaultCamZoom:0.00}");







                sb.AppendLine($"BF mid screen: {WorldToScreen(_boyfriend.GetMidpoint().X, _boyfriend.GetMidpoint().Y)}");







                sb.AppendLine($"Dad mid screen: {WorldToScreen(_opponent.GetMidpoint().X, _opponent.GetMidpoint().Y)}");







                sb.AppendLine($"GF mid screen: {WorldToScreen(_girlfriend.GetMidpoint().X, _girlfriend.GetMidpoint().Y)}");







                try { System.IO.File.AppendAllText($"d:\\godt engine custom\\{_chart.Stage}_pos_diag.txt", sb.ToString()); } catch { }







            }







            catch { }







        }















        















        // Hook up beat callback for dancing + camera bop + icon bounce















        _conductor.OnBeat += (beat) =>















        {















            DispatchBeatHit(beat);
            base.OnBeatHit();
            // (removed duplicate Lua callback; fired once by the matching Dispatch*() above — Psych calls each callback once)















            _boyfriend.Dance(beat);















            _opponent.Dance(beat);















            _girlfriend?.Dance(beat); SsfOnBeat(beat);
            if (Environment.GetEnvironmentVariable("FNF_BEATLOG") == "1" && beat <= 40) Console.WriteLine($"BEATLOG beat={beat} t={(int)(_conductor.SongPosition*1000)} gf={_girlfriend?.CurrentAnimation}");















            















            DanceAnimatedProps(beat); // stage props (Bopper.onBeatHit) -> PlayScene.PropDance.cs
















            















            // Sniper: 2% chance each beat to play sip animation (original tankmanBattlefieldErect.hxc)







            if (_isTankmanStage && _random.Next(50) == 0)







            {







                for (int pi = 0; pi < _animatedProps.Count; pi++)







                {







                    if (string.Equals(_animatedProps[pi].Name, "sniper", StringComparison.OrdinalIgnoreCase))







                    {







                        var sniper = _animatedProps[pi];







                        string sipAnim = sniper.AnimNameMap.TryGetValue("sip", out var mapped) ? mapped : "sip";







                        Console.WriteLine($"[STREET-DEBUG] Sniper sip triggered on beat {beat}");







                        // Original: getNamedProp('sniper').playAnimation('sip', false, true);







                        // playAnimation signature is (name, restart, ignoreOther). restart=false so it







                        // won't restart if already sipping; ignoreOther=true to switch from idle.







                        sniper.Sprite?.PlayAnimation(sipAnim, force: false, loop: false);







                        sniper.CanPlayOtherAnims = false; // block idle dance while sipping (matches original ignoreOther)







                        _animatedProps[pi] = sniper;







                        break;







                    }







                }







            }















            















            // FastCar: 10% chance each beat to zoom across (original limoRide.hxc)















            LimoBeat(); // limoRide.hxc onBeatHit -> PlayScene.Limo.cs















            















            // Spooky lightning: random flash with cooldown (original: nextBeat + random(3,8))















            // Erect variant: bgLight/stairsLight flash + character alpha toggle















            bool doLightning = false;















            bool playThunder = true;















            // Beat-4 synced lightning for "spookeez" (original: beat == 4 && song.id == "spookeez")















            string songId = _chart.SongName?.ToLower() ?? "";















            int sepIdx = songId.IndexOfAny(new[] { '_', '-' });















            if (sepIdx >= 0) songId = songId.Substring(0, sepIdx);















            if (_conductor.CurrentBeat == 4 && songId == "spookeez")















            {















                doLightning = true;















                playThunder = false;















            }















            if (!doLightning && _devStrikeBeat >= 0 && _conductor.CurrentBeat == _devStrikeBeat) { doLightning = true; } // dev hook FNF_SPOOKY_STRIKE_BEAT
            // Random lightning when cooldown expired















            if (!doLightning && _random.Next(10) == 0 && _conductor.CurrentBeat > _spkStrikeBeat + _spkStrikeOffset) // FlxG.random.bool(10) && beat > lightningStrikeBeat + lightningStrikeOffset















            {















                doLightning = true;















            }















            if (doLightning)















            {















                _spkStrikeBeat = _conductor.CurrentBeat; _spkStrikeOffset = _random.Next(8, 25); // lightningStrikeBeat = beat; offset = int(8, 24)















                if (_isSpookyErectStage)















                {















                    // Erect: flash bgLight/stairsLight, toggle character alpha















                    _spookyLightningPhase = 1;















                    _spookyLightningTimer = 0f;















                    if (_spookyBgLightIndex >= 0)















                    {















                        var p = _staticProps[_spookyBgLightIndex];















                        p.Alpha = 1f;















                        _staticProps[_spookyBgLightIndex] = p;















                    }















                    if (_spookyStairsLightIndex >= 0)















                    {















                        var p = _staticProps[_spookyStairsLightIndex];















                        p.Alpha = 1f;















                        _staticProps[_spookyStairsLightIndex] = p;















                    }















                    if (_boyfriend != null) _boyfriend.Alpha = 0f;















                    if (_opponent != null) _opponent.Alpha = 0f;















                    if (_girlfriend != null) _girlfriend.Alpha = 0f;















                    if (playThunder)















                        Audio.PlaySound("game/stages/spooky/thunder_" + (_random.Next(2) + 1));















                    if (_girlfriend != null && _girlfriend.HasJsonAnimation("scared")) _girlfriend.PlayAnimation("scared", force: true); // gf.hasAnimation(scared): nene-dark has none















                    if (_boyfriend != null && _boyfriend.HasJsonAnimation("scared") && _boyfriend.CurrentAnimation != "cheer") _boyfriend.PlayAnimation("scared", force: true); // spookyMansionErect.hxc: bf.hasAnimation(scared) && anim != cheer; pico-dark.hxc playAnimation ignores "scared"















                }















                else if (_halloweenBGPropIndex >= 0)















                {















                    // Normal spooky: white flash + halloweenBG animation















                    // (spookyMansion.hxc has no white flash: only halloweenBG.animation.play("lightning"))















                    var bgProp = _animatedProps[_halloweenBGPropIndex];















                    bgProp.Sprite?.PlayAnimation("lightning", force: true, loop: false);















                    _animatedProps[_halloweenBGPropIndex] = bgProp;















                    if (playThunder)















                        Audio.PlaySound("game/stages/spooky/thunder_" + (_random.Next(2) + 1));















                    if (_girlfriend != null && _girlfriend.HasJsonAnimation("scared")) _girlfriend.PlayAnimation("scared", force: true); // spookyMansion.hxc: gf.hasAnimation(scared)















                    if (_boyfriend != null && _boyfriend.HasJsonAnimation("scared") && _boyfriend.CurrentAnimation != "cheer") _boyfriend.PlayAnimation("scared", force: true); // spookyMansion.hxc















                }















            }















            if (_lightningBeatCooldown > 0) _lightningBeatCooldown--;















            















            PhillyTrainBeat(beat); // phillyTrain(Erect).hxc onBeatHit -> PlayScene.PhillyTrain.cs















            















            // Camera bop every CAMERA_ZOOM_RATE beats (original: every 4 beats)















            if (_cameraZoomEnabled && !PsychNotes && ShouldCameraBop(beat)) // PlayState.beatHit: cameraZoomRate / offset / 135% cap















            {















                _cameraBopMultiplier = _camBopIntensity;















                if (!s_devNoHudBop) _hudZoomAdd += _hudBopIntensity; // FNF_DEV_NOHUDBOP=1: HUD measurements at zoom 1















            }















            















            // Icon bounce on every beat















            _iconBounceScale = 1.3f; HudIconBop();















        };















        // (removed: duplicate Lua onStepHit / every-16-steps onSectionHit; DispatchStepHit fires them once like Psych)
        _conductor.OnStep += (step) => DispatchStepHit(step);















    }































    /// <summary>















    /// Set alpha for all ABot-related stage props (abotSystem, neneSpeaker*, etc.).















    /// Used by spooky Erect lightning to match gf visibility.















    /// </summary>















    private void SetAbotAlpha(float alpha)















    {















        for (int i = 0; i < _animatedProps.Count; i++)















        {















            var p = _animatedProps[i];















            if (!string.IsNullOrEmpty(p.Name) && (p.Name.StartsWith("abot", StringComparison.OrdinalIgnoreCase) || p.Name.StartsWith("neneSpeaker", StringComparison.OrdinalIgnoreCase)))















            {















                p.Alpha = alpha;















                _animatedProps[i] = p;















            }















        }















        for (int i = 0; i < _staticProps.Count; i++)















        {















            var p = _staticProps[i];















            if (!string.IsNullOrEmpty(p.Name) && (p.Name.StartsWith("abot", StringComparison.OrdinalIgnoreCase) || p.Name.StartsWith("neneSpeaker", StringComparison.OrdinalIgnoreCase)))















            {















                p.Alpha = alpha;















                _staticProps[i] = p;















            }















        }















    }































    /// <summary>















    /// Adds Nene's ABot speaker rig for Weekend 1 Blazin stage when Nene is the GF slot.















    /// <summary>















    /// Evaluates HaxeFlixel formulas from .hxc files using C# engine variables.















    /// Maps HaxeFlixel variables to C# equivalents:















    ///   this.x/this.y         -> _girlfriend.CornerPosition (includes globalOffsets)















    ///   this.globalOffsets[0/1] -> _girlfriend.CharOffsets[0/1]















    ///   this.scale.x/scale.y   -> _girlfriend.Scale















    /// Reads full expressions like: this.x + 170 - (-this.globalOffsets[0] * this.scale.x)















    /// </summary>















    private bool EvaluateHaxeAbotFormula(string characterName, out float abotX, out float abotY)















    {
#if XBOX_UWP
        abotX = 0f;
        abotY = 0f;
        return false;
#else















        abotX = 0f;















        abotY = 0f;















        if (_girlfriend == null || string.IsNullOrWhiteSpace(characterName)) return false;
        // The values below are taken verbatim from the original character scripts; scraping the .hxc
        // at runtime (from a hard-coded D:\ path, via a stub evaluator that returns 0) is not needed.
        return false;
#pragma warning disable CS0162































        string hxcPath = $"d:\\godt engine custom\\FNF_Official\\assets\\preload\\scripts\\characters\\{characterName}.hxc";















        if (!global::FNF_MonoGame.Engine.FsCI.FileExists(hxcPath))















        {















            Console.WriteLine($"[HAXE-EVAL] .hxc not found: {hxcPath}");















            return false;















        }































        try















        {















            string hxcContent = global::FNF_MonoGame.Engine.FsCI.ReadAllText(hxcPath);















            // Find ALL abot.x and abot.y assignment lines, then pick the one with globalOffsets







            // (the real formula is in onUpdate, not the simple assignment in onCreate)















            var xMatches = Regex.Matches(hxcContent, @"abot\.x\s*=\s*([^;]+);");















            var yMatches = Regex.Matches(hxcContent, @"abot\.y\s*=\s*([^;]+);");















            string xExpr = null, yExpr = null;















            foreach (Match m in xMatches)















            {















                string expr = m.Groups[1].Value.Trim();















                // Prefer the formula with globalOffsets or numeric offsets (the real one)















                if (expr.Contains("globalOffsets") || expr.Contains("170") || expr.Contains("-95") || expr.Contains("296"))















                {















                    xExpr = expr;















                    break;















                }















                // Fallback: keep the last match















                xExpr = expr;















            }















            foreach (Match m in yMatches)















            {















                string expr = m.Groups[1].Value.Trim();















                if (expr.Contains("globalOffsets") || expr.Contains("455") || expr.Contains("384") || expr.Contains("430"))















                {















                    yExpr = expr;















                    break;















                }















                yExpr = expr;















            }















            if (string.IsNullOrEmpty(xExpr) || string.IsNullOrEmpty(yExpr))















            {















                Console.WriteLine($"[HAXE-EVAL] Could not find abot.x/abot.y assignments in '{characterName}.hxc'");















                return false;















            }































            // Get the raw HaxeFlixel expressions















            Console.WriteLine($"[HAXE-EVAL] Found formulas in '{characterName}.hxc':");















            Console.WriteLine($"  abot.x = {xExpr}");















            Console.WriteLine($"  abot.y = {yExpr}");































            // Use HaxeScriptEngine to evaluate expressions with variable substitution







            // In HaxeFlixel, this.x/this.y are the character's top-left bounding box (FlxSprite.x/y),







            // which is exactly MonoGame's CornerPosition.







            var engine = new HaxeScriptEngine();















            engine.SetVariable("this.x", _girlfriend.CornerPosition.X);















            engine.SetVariable("this.y", _girlfriend.CornerPosition.Y);















            engine.SetVariable("this.globalOffsets[0]", _girlfriend.CharOffsets?.Length >= 2 ? _girlfriend.CharOffsets[0] : 0f);















            engine.SetVariable("this.globalOffsets[1]", _girlfriend.CharOffsets?.Length >= 2 ? _girlfriend.CharOffsets[1] : 0f);















            engine.SetVariable("this.scale.x", _girlfriend.Scale);















            engine.SetVariable("this.scale.y", _girlfriend.Scale);































            abotX = engine.EvaluateFloat(xExpr);















            abotY = engine.EvaluateFloat(yExpr);















            Console.WriteLine($"[HAXE-EVAL] Evaluated '{characterName}.hxc' -> abot=({abotX:0.00},{abotY:0.00})");















            return true;















        }















        catch (Exception ex)















        {















            Console.WriteLine($"[HAXE-EVAL] Exception: {ex.Message}");















            return false;















        }















#endif
    }































    /// Some stage packs omit this prop from JSON, which makes Nene float without speakers.















    /// </summary>















    private void TryAddNeneSpeakers(string gfName)















    {















        if (_girlfriend == null)















            return;































        string stageFolder = ResolveStageFolder(_chart.Stage);































        if (string.IsNullOrWhiteSpace(gfName))















            return;































        // Nene variants that have ABot (from original source: nene.hxc, nene-christmas.hxc)















        // Use OriginalName (chart character ID) since Name may be the resolved sprite folder (e.g., "gf")















        string resolvedGfName = _girlfriend.OriginalName ?? gfName ?? "";















        // Also check the actual sprite folder name (Name) for dark variant detection















        string spriteName = _girlfriend.Name ?? "";















        bool isAbotNene = resolvedGfName.Equals("nene", StringComparison.OrdinalIgnoreCase)















            || resolvedGfName.Equals("nene-christmas", StringComparison.OrdinalIgnoreCase)















            || resolvedGfName.Equals("nene-tankmen", StringComparison.OrdinalIgnoreCase)















            || resolvedGfName.Equals("nene-speakers", StringComparison.OrdinalIgnoreCase)















            || resolvedGfName.Equals("nene-dark", StringComparison.OrdinalIgnoreCase)















            || resolvedGfName.Equals("nene-pixel", StringComparison.OrdinalIgnoreCase)















            || resolvedGfName.Equals("otis-speaker", StringComparison.OrdinalIgnoreCase)















            || spriteName.Equals("nene-dark", StringComparison.OrdinalIgnoreCase);















        if (!isAbotNene)















            return;































        if (_animatedProps.Any(p => string.Equals(p.Name, "neneSpeakerRig", StringComparison.OrdinalIgnoreCase))















            || _staticProps.Any(p => string.Equals(p.Name, "neneSpeakerRig", StringComparison.OrdinalIgnoreCase)))















            return;































        bool isPixelAbot = resolvedGfName.Equals("nene-pixel", StringComparison.OrdinalIgnoreCase);















        // Use gfName (original chart character ID) for dark detection since ResolveCharacterSprite







        // strips the -dark suffix (e.g., "nene-dark" -> "nene")







        bool isDarkAbot = (gfName ?? "").Equals("nene-dark", StringComparison.OrdinalIgnoreCase)















            || resolvedGfName.Equals("nene-dark", StringComparison.OrdinalIgnoreCase)















            || spriteName.Equals("nene-dark", StringComparison.OrdinalIgnoreCase);















        float abotX, abotY;















        float offX = _girlfriend.CharOffsets?.Length >= 2 ? _girlfriend.CharOffsets[0] : 0f;















        float offY = _girlfriend.CharOffsets?.Length >= 2 ? _girlfriend.CharOffsets[1] : 0f;















        float charScale = _girlfriend.JsonData?.Scale ?? 1f;















        float baseOffX, baseOffY;















        // Try to read offsets from original HaxeFlixel .hxc source at runtime!







        // This makes C# literally read the original source code.







        bool parsed = EvaluateHaxeAbotFormula(resolvedGfName, out abotX, out abotY);







        if (!parsed)







        {







            // Fallback to hardcoded values if .hxc not found or parse failed







            float rawBaseOffX, rawBaseOffY;







            if (resolvedGfName.Equals("otis-speaker", StringComparison.OrdinalIgnoreCase))







            {







                rawBaseOffX = 170f; rawBaseOffY = 455f;







            }







            else if (resolvedGfName.Equals("nene-christmas", StringComparison.OrdinalIgnoreCase))







            {







                rawBaseOffX = -135f; rawBaseOffY = 210f;







            }







            else if (isPixelAbot)







            {







                rawBaseOffX = 296f; rawBaseOffY = 430f;







            }







            else







            {







                rawBaseOffX = -95f; rawBaseOffY = 384f;







            }







            Console.WriteLine($"[HAXE-EVAL] Fallback for '{resolvedGfName}': ({rawBaseOffX},{rawBaseOffY})");







            bool noGlobalTerm = resolvedGfName.Equals("nene-christmas", StringComparison.OrdinalIgnoreCase); // nene-christmas.hxc
            baseOffX = noGlobalTerm ? rawBaseOffX : rawBaseOffX - (-offX * charScale);







            baseOffY = noGlobalTerm ? rawBaseOffY : rawBaseOffY - (-offY * charScale);







            abotX = _girlfriend.CornerPosition.X + baseOffX;







            abotY = _girlfriend.CornerPosition.Y + baseOffY;







        }







        else







        {







            // Haxe formula evaluated successfully - compute offsets for runtime updates







            baseOffX = abotX - _girlfriend.CornerPosition.X;







            baseOffY = abotY - _girlfriend.CornerPosition.Y;







        }















        _abotBodyOffsetX = baseOffX;
        Console.WriteLine($"[ABOTOFF] set body offset ({baseOffX},{baseOffY}) gf={resolvedGfName} corner={_girlfriend?.CornerPosition} stack={Environment.StackTrace.Replace(Environment.NewLine, " | ")}");







        _abotBodyOffsetY = baseOffY;















        // (removed: a hand-tuned -250px 'Stress Pico Mix' A-Bot shift; otis-speaker.hxc has no such shift)















        int abotZ = _gfZIndex - 10;















        bool addedRig = false;































        // For nene-dark, load BOTH normal and dark abotSystem for TextureSwap shader















        string abotSystemPath = "images/characters/abot/abotSystem";















        string darkAbotSystemPath = "images/characters/abot/dark/abotSystem";































        if (isPixelAbot)















        {















            // nene-pixel uses Sparrow sprite sheets, not AnimateAtlas















            // Pixel ABot body (aBotPixelBody = the TV-screen frame body, dances with Nene)















            var pixelBodySheet = SpriteSheet.Load(Game, "images/characters/abotPixel/aBotPixelBody");















            if (pixelBodySheet != null)















            {















                var pixelBodySprite = new AnimatedSprite { Sheet = pixelBodySheet };















                pixelBodySprite.Scale = new Vector2(6f, 6f);















                string[] pixelAnims = { "danceLeft", "danceRight" };















                string firstAnim = pixelBodySheet.Animations.Keys















                    .FirstOrDefault(k => k.Equals("danceLeft", StringComparison.OrdinalIgnoreCase))















                    ?? pixelBodySheet.Animations.Keys.FirstOrDefault();















                if (!string.IsNullOrEmpty(firstAnim))















                    pixelBodySprite.PlayAnimation(firstAnim, loop: false);















                // HaxeFlixel abot.origin = (52,26) after centerOrigin + Math.round.







                // MonoGame body top-left = abot.x - 52*6, abot.y - 26*6.







                pixelBodySprite.Position = new Vector2(abotX - 260f, abotY - 130f);















                _animatedProps.Add(new AnimatedStageProp















                {















                    Sprite = pixelBodySprite,















                    ZIndex = abotZ,















                    Alpha = 1f,















                    ScrollX = 1f,















                    ScrollY = 1f,















                    DanceEvery = 1,















                    LastDanceBeat = -1,















                    Name = "neneSpeakerRig",















                    DanceAnimNames = pixelAnims,















                    DanceToggle = true















                });















                addedRig = true;















            }































            // Pixel ABot speaker (aBotPixelSpeaker, dances each beat)















            var pixelSpeakerSheet = SpriteSheet.Load(Game, "images/characters/abotPixel/aBotPixelSpeaker");















            if (pixelSpeakerSheet != null)















            {















                var pixelSpeakerSprite = new AnimatedSprite { Sheet = pixelSpeakerSheet };















                pixelSpeakerSprite.Scale = new Vector2(6f, 6f);















                string spkAnim = pixelSpeakerSheet.Animations.Keys















                    .FirstOrDefault(k => k.Equals("danceLeft", StringComparison.OrdinalIgnoreCase))















                    ?? pixelSpeakerSheet.Animations.Keys.FirstOrDefault();















                if (!string.IsNullOrEmpty(spkAnim))















                    pixelSpeakerSprite.PlayAnimation(spkAnim, loop: false);















                // HaxeFlixel abotSpeaker.origin = (64,23) after rounding.







                // MonoGame speaker top-left = (abot.x - 78) - 64*6, (abot.y + 9) - 23*6.







                pixelSpeakerSprite.Position = new Vector2(abotX - 398f, abotY - 106f);















                _animatedProps.Add(new AnimatedStageProp















                {















                    Sprite = pixelSpeakerSprite,















                    ZIndex = abotZ - 3,















                    Alpha = 1f,















                    ScrollX = 1f,















                    ScrollY = 1f,















                    DanceEvery = 1,















                    LastDanceBeat = -1,















                    Name = "neneSpeakerPixelSpeaker",















                    DanceAnimNames = new[] { spkAnim }















                });















            }































            // Pixel back















            var pixelBackTex = Assets.LoadTexture("images/characters/abotPixel/aBotPixelBack");















            if (pixelBackTex != null && pixelBackTex != Assets.Pixel)















            {















                // HaxeFlixel abotBack.origin = (37,21.5) (center of 74x43 static image).







                // MonoGame back top-left = (abot.x - 55) - 37*6.1, abot.y - 21.5*6.







                _staticProps.Add(new StaticStageProp







                {







                    Texture = pixelBackTex,







                    X = abotX - 243.7f,







                    Y = abotY - 107.5f,







                    ScaleX = 6.1f,







                    ScaleY = 6f,















                    Alpha = 1f,















                    ScrollX = 1f,















                    ScrollY = 1f,















                    ZIndex = abotZ - 2,















                    Name = "neneSpeakerPixelBack"















                });















            }































            // Pixel head (eyes)















            var pixelHeadSheet = SpriteSheet.Load(Game, "images/characters/abotPixel/abotHead");















            if (pixelHeadSheet != null)















            {















                var pixelHeadSprite = new AnimatedSprite { Sheet = pixelHeadSheet };















                pixelHeadSprite.Scale = new Vector2(6f, 6f);















                // HaxeFlixel: abotHead.x = abot.x - 325; abotHead.y = abot.y + 72;







                // abotHead.origin defaults to center of 29x40 frame = (14.5, 20).







                // MonoGame top-left = (abot.x - 325) - 87, (abot.y + 72) - 120.







                pixelHeadSprite.Position = new Vector2(abotX - 397.5f, abotY - 28f);















                string headAnim = pixelHeadSheet.Animations.Keys.FirstOrDefault();















                if (!string.IsNullOrEmpty(headAnim))















                    pixelHeadSprite.PlayAnimation(headAnim, loop: false);















                _animatedProps.Add(new AnimatedStageProp















                {















                    Sprite = pixelHeadSprite,















                    ZIndex = abotZ - 4,















                    Alpha = 1f,















                    ScrollX = 1f,















                    ScrollY = 1f,















                    DanceEvery = 0,















                    LastDanceBeat = -1,















                    Name = "neneSpeakerPixelHead"















                });















            }































            // Pixel viz bars















            var pixelVizSheet = SpriteSheet.Load(Game, "images/characters/abotPixel/aBotVizPixel");















            if (pixelVizSheet != null)















            {















                // HaxeFlixel abotViz base = (abot.x - 162, abot.y + 16) (center of viz1 8x27).







                // MonoGame viz1 top-left = base - (4*6, 13.5*6) = base - (24, 81).







                float vizPxX = abotX - 182f; // (abot.x-162) - origin(4)*(6-1)







                float vizPxY = abotY - 51.5f; // (abot.y+16) - origin(13.5)*(6-1)















                // ABotVis.hx pixel offsets: [0, 7*6, 8*6, 9*6, 10*6, 6*6, 7*6] and [0, -2*6, -1*6, 0, 0, 1*6, 2*6]















                float[] pixVizOffsetsX = { 0f, 42f, 48f, 54f, 60f, 36f, 42f };















                float[] pixVizOffsetsY = { 0f, -12f, -6f, 0f, 0f, 6f, 12f };















                for (int barIndex = 1; barIndex <= 7; barIndex++)















                {















                    string framePrefix = $"viz{barIndex}0";















                    var barFrames = pixelVizSheet.Frames.Values















                        .Where(f => f.Name.StartsWith(framePrefix, StringComparison.OrdinalIgnoreCase))















                        .OrderBy(f => { int i = f.Name.Length - 1; while (i >= 0 && char.IsDigit(f.Name[i])) i--; return int.TryParse(f.Name[(i + 1)..], out int n) ? n : 0; })















                        .ToList();















                    if (barFrames.Count == 0) continue;















                    string barAnim = $"neneVizBar{barIndex}";















                    pixelVizSheet.Animations[barAnim] = barFrames;















                    var vizSprite = new AnimatedSprite { Sheet = pixelVizSheet };















                    vizSprite.PlayAnimationFromFrame(barAnim, barFrames.Count > 5 ? 5 : barFrames.Count - 1, loop: false, loopFrame: barFrames.Count > 5 ? 5 : barFrames.Count - 1);















                    vizSprite.Scale = new Vector2(6f, 6f);















                    float ax = 0f, ay = 0f;















                    for (int i = 0; i < barIndex; i++) { ax += pixVizOffsetsX[i]; ay += pixVizOffsetsY[i]; }















                    vizSprite.Position = new Vector2(vizPxX + ax, vizPxY + ay);















                    _animatedProps.Add(new AnimatedStageProp















                    {















                        Sprite = vizSprite,















                        ZIndex = abotZ - 1,















                        Alpha = 0f,















                        ScrollX = 1f,















                        ScrollY = 1f,















                        DanceEvery = 0,















                        LastDanceBeat = -1,















                        Name = $"neneSpeakerViz{barIndex}",















                        DanceAnimNames = new[] { barAnim }















                    });















                }















            }































            // Sort props and set base positions (same finalization as non-pixel path)















            _staticProps = _staticProps.OrderBy(p => p.ZIndex).ToList();















            _animatedProps = _animatedProps.OrderBy(p => p.ZIndex).ToList();















            _hasAbotFallback = addedRig;















            _abotIsPixel = true;















            _isNenePixel = true;















            _abotBaseX = abotX;















            _abotBaseY = abotY;















            // Pixel ABot viz offset (MonoGame top-left, accounting for viz1 origin).







            _abotVizBaseOffsetX = -182f;







            _abotVizBaseOffsetY = -51.5f;















            Console.WriteLine($"[ABOT-PIXEL] final abotX={abotX}, abotY={abotY}, addedRig={addedRig}");















            return;















        }































        // Standard (non-pixel) ABot body loading:















        // loadTextureAtlas("characters/abot/abotSystem", "shared")















        var systemBodySheet = SpriteSheet.Load(















            Game,















            abotSystemPath,















            preRenderComposites: true,















            preRenderFilter: new[] { "Abot System", "Nene_assets", "default" },















            deferComposites: true,















            applyStageInstanceTransform: false,















            applyTRP: false);















        bool hasExplicitAbotSystem = systemBodySheet != null && (















            systemBodySheet.Animations.ContainsKey("Abot System")















            || systemBodySheet.RawCompositeData.ContainsKey("Abot System")















            || systemBodySheet.CompositeAnimations.ContainsKey("Abot System"));































        // If this atlas only exposes a generic/default timeline, fall back to the Nene-local















        // ABot source, which keeps the explicit "Abot System" timeline in original content.















        if (systemBodySheet != null && !hasExplicitAbotSystem)















        {















            var speakerSheet = SpriteSheet.Load(















                Game,















                "game/characters/nene/abot/speaker",















                preRenderComposites: true,















                preRenderFilter: new[] { "Abot System", "Nene_assets", "default" },















                deferComposites: true,















                applyStageInstanceTransform: false,















                applyTRP: false);































            if (speakerSheet != null)















            {















                systemBodySheet.Dispose();















                systemBodySheet = speakerSheet;















                hasExplicitAbotSystem = systemBodySheet.Animations.ContainsKey("Abot System")















                    || systemBodySheet.RawCompositeData.ContainsKey("Abot System")















                    || systemBodySheet.CompositeAnimations.ContainsKey("Abot System");















            }















        }















        // For nene-dark, also load the dark variant sheet for TextureSwap shader















        SpriteSheet darkSystemBodySheet = null;















        if (isDarkAbot)















        {















            darkSystemBodySheet = SpriteSheet.Load(















                Game,















                darkAbotSystemPath,















                preRenderComposites: true,















                preRenderFilter: new[] { "Abot System", "Nene_assets", "default" },















                deferComposites: true,















                applyStageInstanceTransform: false,















                applyTRP: false);















        }















        if (systemBodySheet != null)















        {















            Console.WriteLine($"[ABOT] bodySheet keys anim=[{string.Join(",", systemBodySheet.Animations.Keys)}] raw=[{string.Join(",", systemBodySheet.RawCompositeData.Keys)}] comp=[{string.Join(",", systemBodySheet.CompositeAnimations.Keys)}]");















            string bodyAnim = systemBodySheet.Animations.Keys















                .FirstOrDefault(k => k.Equals("Abot System", StringComparison.OrdinalIgnoreCase))















                ?? systemBodySheet.Animations.Keys















                    .FirstOrDefault(k => k.Equals("Nene_assets", StringComparison.OrdinalIgnoreCase))















                ?? systemBodySheet.RawCompositeData.Keys















                    .FirstOrDefault(k => k.Equals("Abot System", StringComparison.OrdinalIgnoreCase))















                ?? systemBodySheet.RawCompositeData.Keys















                    .FirstOrDefault(k => k.Equals("Nene_assets", StringComparison.OrdinalIgnoreCase))















                ?? systemBodySheet.Animations.Keys















                    .FirstOrDefault(k => k.Equals("default", StringComparison.OrdinalIgnoreCase))















                ?? systemBodySheet.RawCompositeData.Keys















                    .FirstOrDefault(k => k.Equals("default", StringComparison.OrdinalIgnoreCase))















                ?? systemBodySheet.Animations.Keys.FirstOrDefault()















                ?? systemBodySheet.RawCompositeData.Keys.FirstOrDefault();































            if (!string.IsNullOrEmpty(bodyAnim))















            {















                // Strict original gameplay behavior: do NOT auto-apply local editor exports.















                // External offsets can desync per-tick ABot part transforms and cause drift.















                bool appliedEditedOffsets = false;















                if (appliedEditedOffsets)















                    Console.WriteLine($"[ABOT] applied editor offsets to anim='{bodyAnim}'");































                if (systemBodySheet.RawCompositeData.TryGetValue(bodyAnim, out var rawTicks))















                {















                    // Keep AnimateAtlas part list exactly as authored for strict original behavior.















                    // Match original nene.hxc: restart ABot body from frame 1 every beat.















                    _abotRigStartFrame = 1;































                    for (int ti = 0; ti < rawTicks.Count; ti++)















                    {















                        var partNames = rawTicks[ti]















                            .Select(p => p.Frame?.Name)















                            .Where(n => !string.IsNullOrEmpty(n))















                            .Distinct()















                            .OrderBy(n => n)















                            .ToArray();















                        Console.WriteLine($"[ABOT] tick={ti}, parts={rawTicks[ti].Count}, names=[{string.Join(",", partNames)}]");















                    }































                    var rawParts = rawTicks















                        .SelectMany(t => t)















                        .Select(p => p.Frame?.Name)















                        .Where(n => !string.IsNullOrEmpty(n))















                        .Distinct()















                        .OrderBy(n => n)















                        .ToArray();















                    Console.WriteLine($"[ABOT] rawAnim='{bodyAnim}', ticks={rawTicks.Count}, distinctParts=[{string.Join(",", rawParts)}], chosenStartFrame={_abotRigStartFrame}");































                    _abotRigRuntimeOrigin = ComputeRawCompositeOrigin(rawTicks, _abotRigStartFrame);















                    _abotRigHasRuntimeOrigin = true;















                    Console.WriteLine($"[ABOT] rawOrigin=({_abotRigRuntimeOrigin.X:0.0},{_abotRigRuntimeOrigin.Y:0.0})");































                    // Diagnostic: print bounding box per tick and the min-X/min-Y contributors















                    float gMinX = float.MaxValue, gMinY = float.MaxValue, gMaxX = float.MinValue, gMaxY = float.MinValue;















                    string gMinXName = "", gMinYName = "";















                    int gMinXTick = -1, gMinYTick = -1;















                    for (int t = 0; t < rawTicks.Count; t++)















                    {















                        foreach (var (f, a, b, c, d, tx, ty) in rawTicks[t])















                        {















                            float w = f.Rotated ? f.SourceRect.Height : f.SourceRect.Width;















                            float h = f.Rotated ? f.SourceRect.Width : f.SourceRect.Height;















                            float[] xs = { tx, a * w + tx, c * h + tx, a * w + c * h + tx };















                            float[] ys = { ty, b * w + ty, d * h + ty, b * w + d * h + ty };















                            foreach (var x in xs) { if (x < gMinX) { gMinX = x; gMinXName = f.Name; gMinXTick = t; } if (x > gMaxX) gMaxX = x; }















                            foreach (var y in ys) { if (y < gMinY) { gMinY = y; gMinYName = f.Name; gMinYTick = t; } if (y > gMaxY) gMaxY = y; }















                        }















                    }















                    Console.WriteLine($"[ABOT] BBox local=({gMinX:0.0},{gMinY:0.0})-({gMaxX:0.0},{gMaxY:0.0}) size=({gMaxX-gMinX:0.0}x{gMaxY-gMinY:0.0})");















                    Console.WriteLine($"[ABOT] MinX from part={gMinXName} tick={gMinXTick}, MinY from part={gMinYName} tick={gMinYTick}");































                    // World position of each part in start frame (so we can compare with pupil/viz/eyeWhites positions)















                    if (rawTicks.Count > _abotRigStartFrame)















                    {















                        var startFrameParts = rawTicks[_abotRigStartFrame];















                        Console.WriteLine($"[ABOT] === Parts in startFrame={_abotRigStartFrame} (world coords with bodyPos=({abotX + _abotRigRuntimeOrigin.X:0.0},{abotY + _abotRigRuntimeOrigin.Y:0.0})) ===");















                        float bx = abotX + _abotRigRuntimeOrigin.X;















                        float by = abotY + _abotRigRuntimeOrigin.Y;















                        foreach (var (f, a, _, _, d, tx, ty) in startFrameParts)















                        {















                            float w = f.Rotated ? f.SourceRect.Height : f.SourceRect.Width;















                            float h = f.Rotated ? f.SourceRect.Width : f.SourceRect.Height;















                            float wx0 = bx + tx;















                            float wy0 = by + ty;















                            float wx1 = bx + a * w + tx;















                            float wy1 = by + d * h + ty;















                            Console.WriteLine($"[ABOT]   part={f.Name} a={a:0.00} d={d:0.00} world=({Math.Min(wx0,wx1):0.0},{Math.Min(wy0,wy1):0.0})-({Math.Max(wx0,wx1):0.0},{Math.Max(wy0,wy1):0.0}) size=({w:0}x{h:0})");















                        }















                        Console.WriteLine($"[ABOT] Pupil expected at world ({abotX + 50:0.0},{abotY + 238:0.0}); EyeWhites at ({abotX + 40:0.0},{abotY + 250:0.0})");















                    }































                    // Runtime-composite playback still requires an animation entry.















                    if (!systemBodySheet.Animations.ContainsKey(bodyAnim))















                    {















                        var placeholders = new List<SpriteFrame>(rawTicks.Count);















                        for (int i = 0; i < rawTicks.Count; i++)















                            placeholders.Add(new SpriteFrame { Name = $"{bodyAnim}_{i}", SourceRect = Rectangle.Empty });















                        systemBodySheet.Animations[bodyAnim] = placeholders;















                    }















                }















                else if (systemBodySheet.CompositeAnimations.TryGetValue(bodyAnim, out var compFrames) && compFrames.Count > 0)















                {















                    _abotRigStartFrame = Math.Clamp(1, 0, compFrames.Count - 1);















                    _abotRigHasRuntimeOrigin = false;















                    _abotRigRuntimeOrigin = Vector2.Zero;















                    Console.WriteLine($"[ABOT] compAnim='{bodyAnim}', frames={compFrames.Count}, chosenStartFrame={_abotRigStartFrame}");















                }































                var systemBodySprite = new AnimatedSprite { Sheet = systemBodySheet, UseTimelineAnchoring = true }; // FunkinSprite(abotSystem) draws at abot.x/y















                // Original nene.hxc: abot.anim.play("", true, false, 1) on each beat.















                // Start from frame 1 and don't loop so beat updates can re-trigger it.















                int bodyStartFrame = _abotRigStartFrame;















                if (systemBodySheet.Animations.TryGetValue(bodyAnim, out var bodyFrames) && bodyFrames.Count > 0)















                {















                    bodyStartFrame = Math.Clamp(bodyStartFrame, 0, bodyFrames.Count - 1);















                }















                else















                {















                    bodyStartFrame = 0;















                }















                systemBodySprite.PlayAnimationFromFrame(bodyAnim, bodyStartFrame, loop: _abotUseContinuousAnim, loopFrame: bodyStartFrame);















                var abotBasePos = new Vector2(abotX, abotY);















                // The Haxe formula gives abot.x/abot.y at the A-Bot's bottom-center anchor.







                // MonoGame's AnimatedSprite.Position is the top-left of the bounding box,







                // so shift up by the full height and left by half the width.







                float abotW = systemBodySprite.GetFrameWidth();







                float abotH = systemBodySprite.GetFrameHeight();







                systemBodySprite.Position = new Vector2(







                    abotBasePos.X - abotW / 2f,







                    abotBasePos.Y - abotH);















                systemBodySprite.Scale = new Vector2(1f, 1f);































                Console.WriteLine($"[ABOT] bodyAnim='{bodyAnim}', hasAbotSystem={hasExplicitAbotSystem}, runtime={systemBodySprite.IsRuntimeComposite()}, comp={systemBodySheet.CompositeAnimations.ContainsKey(bodyAnim)}, raw={systemBodySheet.RawCompositeData.ContainsKey(bodyAnim)}, pos=({systemBodySprite.Position.X:0.0},{systemBodySprite.Position.Y:0.0})");































                _animatedProps.Add(new AnimatedStageProp















                {















                    Sprite = systemBodySprite,















                    ZIndex = abotZ,















                    Alpha = 1f,















                    ScrollX = 1f,















                    ScrollY = 1f,















                    DanceEvery = 1,















                    LastDanceBeat = -1,















                    Name = "neneSpeakerRig",















                    DanceAnimNames = new[] { bodyAnim },















                    DanceToggle = false,















                    DarkSheet = darkSystemBodySheet















                });















                addedRig = true;















            }















            else















            {















                systemBodySheet.Dispose();















            }















        }































        if (!addedRig)















        {















            Console.WriteLine("Nene speaker fallback: could not create ABot rig");















            return;















        }































        var eyesSheet = SpriteSheet.Load(















            Game,















            "images/characters/abot/systemEyes",















            preRenderComposites: true,















            preRenderFilter: new[] { "default" },















            deferComposites: false,















            applyStageInstanceTransform: false);































        if (eyesSheet != null)















        {















            string eyesAnim = eyesSheet.Animations.Keys















                .FirstOrDefault(k => k.Equals("default", StringComparison.OrdinalIgnoreCase))















                ?? eyesSheet.Animations.Keys















                    .FirstOrDefault(k => k.Equals("Nene_assets(1)", StringComparison.OrdinalIgnoreCase))















                ?? eyesSheet.Animations.Keys.FirstOrDefault();































            if (!string.IsNullOrEmpty(eyesAnim))















            {















                var eyesSprite = new AnimatedSprite { Sheet = eyesSheet, UseTimelineAnchoring = true };
                _abotPupilSprite = eyesSprite; _abotPupilAnim = eyesAnim;















                // Original nene.hxc/otis-speaker.hxc: pupils start still on frame 0 and only move on
                // weekend-1-lightcan (0->17, look left) / weekend-1-cockgun (17->30, look back).
                eyesSprite.FreezeOnFrame(eyesAnim, 0);































                var pupilBasePos = new Vector2(abotX + 50f, abotY + 238f);















                eyesSprite.Position = pupilBasePos;















                eyesSprite.Scale = new Vector2(1f, 1f);































                Console.WriteLine($"[ABOT] pupilAnim='{eyesAnim}', runtime={eyesSprite.IsRuntimeComposite()}, comp={eyesSheet.CompositeAnimations.ContainsKey(eyesAnim)}, raw={eyesSheet.RawCompositeData.ContainsKey(eyesAnim)}, pos=({eyesSprite.Position.X:0.0},{eyesSprite.Position.Y:0.0})");































                _animatedProps.Add(new AnimatedStageProp















                {















                    Sprite = eyesSprite,















                    ZIndex = abotZ - 5,















                    Alpha = 1f,















                    ScrollX = 1f,















                    ScrollY = 1f,















                    DanceEvery = 0,















                    LastDanceBeat = -1,















                    Name = "neneSpeakerPupil",















                    OverlayColor = null /* nene-dark: vizAdjustColor shader (StageScripts AddCharacterScriptVisuals), not a tint */















                });















            }















            else















            {















                eyesSheet.Dispose();















            }















        }































        // Original nene.hxc uses a solid white mask behind ABot pupils.















        // Use a dedicated texture (not Assets.Pixel, which is treated as fullscreen color fill).















        // nene-dark.hxc: eyeWhites.color = 0xFF6F96CE when dark















        Color eyeWhiteColor = Color.White; // nene-dark: tinted per frame (OverlayColor) = interpolate(white, 0x6F96CE, gf.alpha)















        var eyeWhitesTexture = new Texture2D(Game.GraphicsDevice, 160, 60);















        var eyeWhitesData = new Color[160 * 60];















        System.Array.Fill(eyeWhitesData, eyeWhiteColor);















        eyeWhitesTexture.SetData(eyeWhitesData);















        _staticProps.Add(new StaticStageProp















        {















            Texture = eyeWhitesTexture,















            X = abotX + 40f,















            Y = abotY + 250f,















            ScaleX = 1f,















            ScaleY = 1f,















            Alpha = 1f,















            ScrollX = 1f,















            ScrollY = 1f,















            ZIndex = abotZ - 10,















            Name = "neneSpeakerEyeWhites"















        });































        var stereoBodyTex = Assets.LoadTexture("images/characters/abot/stereoBG")















            ?? Assets.LoadTexture("game/characters/nene/abot/stereoBG")















            ?? Assets.LoadTexture("images/characters/abot/stereoBG.png");















        Console.WriteLine($"[ABOT] stereoBG loaded={stereoBodyTex != null && stereoBodyTex != Assets.Pixel}, hasExplicit={hasExplicitAbotSystem}");















        if (stereoBodyTex != null && stereoBodyTex != Assets.Pixel)















        {















            _staticProps.Add(new StaticStageProp















            {















                Texture = stereoBodyTex,















                X = abotX + 150f,















                Y = abotY + 30f,















                ScaleX = 1f,















                ScaleY = 1f,















                Alpha = 1f,















                ScrollX = 1f,















                ScrollY = 1f,















                ZIndex = abotZ - 8,















                Name = "neneSpeakerStereoBG",















                // nene-dark.hxc: stereoBG.color = 0xFF616785















                OverlayColor = isDarkAbot ? new Color(97, 103, 133) : null















            });















            Console.WriteLine($"[ABOT] stereoBG added at ({abotX + 150f}, {abotY + 30f}), z={abotZ - 8}");















        }































        // Original ABotVis uses aBotViz with 7 bars and fixed relative offsets.















        var vizSheet = SpriteSheet.Load(Game, "images/characters/abot/aBotViz")















            ?? SpriteSheet.Load(Game, "game/characters/nene/abot/visualizer");















        if (vizSheet != null)















        {















            float vizBaseX = abotX + 207f;















            float vizBaseY = abotY + 84f;































            float[] vizOffsetsX = { 0f, 59f, 56f, 66f, 54f, 52f, 51f };















            float[] vizOffsetsY = { 0f, -8f, -3.5f, -0.4f, 0.5f, 4.7f, 7f };































            bool anyVizAdded = false;















            for (int barIndex = 1; barIndex <= 7; barIndex++)















            {















                string framePrefix = $"viz{barIndex}0";















                var barFrames = vizSheet.Frames.Values















                    .Where(f => f.Name.StartsWith(framePrefix, StringComparison.OrdinalIgnoreCase))















                    .OrderBy(f =>















                    {















                        int i = f.Name.Length - 1;















                        while (i >= 0 && char.IsDigit(f.Name[i])) i--;















                        return int.TryParse(f.Name[(i + 1)..], out int n) ? n : 0;















                    })















                    .ToList();































                if (barFrames.Count == 0)















                    continue;































                string barAnim = $"neneVizBar{barIndex}";















                vizSheet.Animations[barAnim] = barFrames;































                var vizSprite = new AnimatedSprite { Sheet = vizSheet };















                vizSprite.PlayAnimationFromFrame(barAnim, 5, loop: false, loopFrame: 5);































                float addX = 0f;















                float addY = 0f;















                for (int i = 0; i < barIndex; i++)















                {















                    addX += vizOffsetsX[i];















                    addY += vizOffsetsY[i];















                }































                vizSprite.Position = new Vector2(vizBaseX + addX, vizBaseY + addY);















                vizSprite.Scale = new Vector2(1f, 1f);































                _animatedProps.Add(new AnimatedStageProp















                {















                    Sprite = vizSprite,















                    ZIndex = abotZ - 1,















                    Alpha = 0f,















                    ScrollX = 1f,















                    ScrollY = 1f,















                    DanceEvery = 0,















                    LastDanceBeat = -1,















                    Name = $"neneSpeakerViz{barIndex}",















                    DanceAnimNames = new[] { barAnim },















                    OverlayColor = null /* nene-dark: vizAdjustColor shader (StageScripts AddCharacterScriptVisuals), not a tint */















                });















                anyVizAdded = true;















                Console.WriteLine($"[ABOT] vizBar={barIndex}, frames={barFrames.Count}, z={abotZ - 1}, pos=({vizSprite.Position.X:0.0},{vizSprite.Position.Y:0.0})");















            }































            if (!anyVizAdded)















                vizSheet.Dispose();















        }































        _staticProps = _staticProps.OrderBy(p => p.ZIndex).ToList();















        _animatedProps = _animatedProps.OrderBy(p => p.ZIndex).ToList();















        _hasAbotFallback = true;















        _abotBaseX = abotX;















        _abotBaseY = abotY;















        // Comprehensive A-Bot position verification for otis-speaker







        if (resolvedGfName.Equals("otis-speaker", StringComparison.OrdinalIgnoreCase))







        {







            var gfOriginV = _girlfriend.GetCharacterOrigin();







            float expectedX = _girlfriend.Position.X + gfOriginV.X + offX;







            float expectedY = _girlfriend.Position.Y + gfOriginV.Y + offY;







            Console.WriteLine($"[ABOT-VERIFY] === OTIS-SPEAKER A-BOT SETUP ===");







            Console.WriteLine($"[ABOT-VERIFY] GF Name: {resolvedGfName}");







            Console.WriteLine($"[ABOT-VERIFY] GF Position: ({_girlfriend.Position.X:0.00}, {_girlfriend.Position.Y:0.00})");







            Console.WriteLine($"[ABOT-VERIFY] GF Origin: ({gfOriginV.X:0.00}, {gfOriginV.Y:0.00})");







            Console.WriteLine($"[ABOT-VERIFY] GF CornerPosition: ({_girlfriend.CornerPosition.X:0.00}, {_girlfriend.CornerPosition.Y:0.00})");







            Console.WriteLine($"[ABOT-VERIFY] GF Offsets: ({offX:0.00}, {offY:0.00}) Scale: {charScale:0.00}");







            Console.WriteLine($"[ABOT-VERIFY] Calculated abotX={abotX:0.00} abotY={abotY:0.00}");







            Console.WriteLine($"[ABOT-VERIFY] Expected  abotX={expectedX:0.00} abotY={expectedY:0.00}");







            Console.WriteLine($"[ABOT-VERIFY] Diff: X={abotX - expectedX:0.00} Y={abotY - expectedY:0.00}");







            Console.WriteLine($"[ABOT-VERIFY] _abotBodyOffset: ({_abotBodyOffsetX:0.00},{_abotBodyOffsetY:0.00})");







        }







        Console.WriteLine($"Nene speaker fallback: added ABot rig at ({abotX:0.0}, {abotY:0.0}) stage='{_chart.Stage}' folder='{stageFolder}'");















    }































    private static Vector2 ComputeRawCompositeOrigin(List<List<(SpriteFrame Frame, float A, float B, float C, float D, float TX, float TY)>> tickParts, int frameIndex = -1)















    {















        float gMinX = float.MaxValue;















        float gMinY = float.MaxValue;































        // FlxAnimate/FlxSprite convention: sprite.x is the bounding-box top-left of the















        // CURRENT visible frame. Computing the min across all frames over-extends the















        // bounding box when animation frames have parts at different positions (e.g. the















        // ABot's chest alternates between two sprite variants with different local origins).















        // Use a single representative frame (defaults to frame 0 / idle) to match the















        // per-frame bounding box behavior.















        int startFrame = (frameIndex >= 0 && frameIndex < tickParts.Count) ? frameIndex : 0;















        int endFrame = startFrame + 1;































        for (int t = startFrame; t < endFrame; t++)















        {















            foreach (var (frame, a, b, c, d, tx, ty) in tickParts[t])















            {















                float w = frame.Rotated ? frame.SourceRect.Height : frame.SourceRect.Width;















                float h = frame.Rotated ? frame.SourceRect.Width : frame.SourceRect.Height;































                float x0 = tx, y0 = ty;















                float x1 = a * w + tx, y1 = b * w + ty;















                float x2 = c * h + tx, y2 = d * h + ty;















                float x3 = a * w + c * h + tx, y3 = b * w + d * h + ty;































                gMinX = Math.Min(gMinX, Math.Min(Math.Min(x0, x1), Math.Min(x2, x3)));















                gMinY = Math.Min(gMinY, Math.Min(Math.Min(y0, y1), Math.Min(y2, y3)));















            }















        }































        return (gMinX < float.MaxValue) ? new Vector2(-gMinX, -gMinY) : Vector2.Zero;















    }































    /// <summary>















    /// Pre-cache all note and receptor sprite frames to avoid string allocation















    /// and dictionary lookups every frame in the draw loop.















    /// </summary>















    private void CacheNoteFrames()















    {















        for (int i = 0; i < 4; i++)















        {















            string lane = _laneNames[i];















            















            // Note head frames















            if (_notesSheet != null)















            {















                _notesSheet.Animations.TryGetValue($"{lane} note", out var noteFrameList);















                _noteFrames[i] = noteFrameList?.Count > 0 ? noteFrameList[0] : null;















                















                _notesSheet.Animations.TryGetValue($"{lane} sustain", out var sustainList);















                _sustainFrames[i] = sustainList?.Count > 0 ? sustainList[0] : null;















                















                _notesSheet.Animations.TryGetValue($"{lane} sustain end", out var sustainEndList);















                _sustainEndFrames[i] = sustainEndList?.Count > 0 ? sustainEndList[0] : null;















            }















            















            // Receptor frames















            if (_receptorsSheet != null)















            {















                _receptorsSheet.Animations.TryGetValue($"{lane} static", out var staticList);















                _receptorStaticFrames[i] = staticList;















                















                _receptorsSheet.Animations.TryGetValue($"{lane} confirm", out var confirmList);















                _receptorConfirmFrames[i] = confirmList;















                















                _receptorsSheet.Animations.TryGetValue($"{lane} press", out var pressList);















                _receptorPressFrames[i] = pressList;















            }















        }















    }















    















    private string ResolveCharacterSprite(string charName)















    {















        // Map character names to their sprite folder names















        // Only map when the variant genuinely reuses the base character's sprites















        string resolved = charName switch















        {















            "pico-playable" => "pico",















            "bf-car" => "bf",            // Car variant uses same bf sprites















            "gf-car" => "gf",            // Car variant uses same gf sprites















            "mom-car" => "mom",           // Car variant uses same mom sprites















            "parents-christmas" => "parents_christmas", // Folder uses underscore















            "bf-pixel" => "bf_pixel",     // Folder uses underscore















            _ => charName















        };















        















        // Check if the character folder actually exists (Content or funkin.assets)















        // Try exact charName first (e.g., "bf-christmas" has its own folder)















        if (Assets.ResolveDirectory($"game/characters/{charName}") != null)















            return charName;















        if (resolved != charName && Assets.ResolveDirectory($"game/characters/{resolved}") != null)















            return resolved;















        















        // Fallback: strip variant suffixes (-dark, -christmas, -pixel, etc.) to find base character















        if (charName.Contains('-'))















        {















            string baseName = charName[..charName.LastIndexOf('-')];















            if (Assets.ResolveDirectory($"game/characters/{baseName}") != null)















                return baseName;















        }















        















        return resolved;















    }















































    /// <summary>















    /// Load character health bar icon from multiple paths (original: preload/images/icons/icon-{name}.png)















    /// </summary>















    private Texture2D LoadCharacterIcon(string charName, string resolvedSprite)
    {
        var skinIcon = SkinLoadCharacterIcon(charName); if (skinIcon != null) return skinIcon; // Psych Online skin: HealthIcon.changeIcon in the skin's mod
        var vsIcon = VSliceLoadCharacterIcon(charName); if (vsIcon != null) return vsIcon;
        var psychIcon = PsychLoadCharacterIcon(charName);
        return psychIcon ?? JsonHealthIcon(charName) ?? LoadCharacterIconBase(charName, resolvedSprite); // HealthIcon.configure(characterData.healthIcon)
    }

    private Texture2D LoadCharacterIconBase(string charName, string resolvedSprite)















    {















        // Try original FNF path: images/icons/icon-{name}.png















        var tex = Assets.LoadTexture($"images/icons/icon-{charName}.png");















        if (tex != null && tex != Assets.Pixel) return tex;















        















        // Try resolved sprite name















        if (resolvedSprite != charName)















        {















            tex = Assets.LoadTexture($"images/icons/icon-{resolvedSprite}.png");















            if (tex != null && tex != Assets.Pixel) return tex;















        }















        















        // Try character folder path















        tex = Assets.LoadTexture($"game/characters/{resolvedSprite}/icon.png");















        if (tex != null && tex != Assets.Pixel) return tex;















        















        // Try base name (strip variant suffix: "bf-car" ? "bf")















        string baseName = charName.Contains('-') ? charName.Split('-')[0] : charName;















        if (baseName != charName)















        {















            tex = Assets.LoadTexture($"images/icons/icon-{baseName}.png");















            if (tex != null && tex != Assets.Pixel) return tex;















        }















        















        // Fallback: generic face icon















        tex = Assets.LoadTexture("images/icons/icon-face.png");















        return tex ?? Assets.Pixel;















    }















    















    /// <summary>















    /// Resolve the note skin folder path from the chart's noteStyle.















    /// Maps noteStyle names to skin folders under Content/game/skins/.















    /// </summary>















    private string ResolveNoteSkinPath(string noteStyle)















    {















        if (string.IsNullOrEmpty(noteStyle) || noteStyle == "funkin")















            return "game/skins/default";















        















        // Check if a skin folder exists for this noteStyle















        string skinPath = $"game/skins/{noteStyle}";















        if (Assets.ResolveDirectory(skinPath) != null)















            return skinPath;















        















        // Map known noteStyle names to folders















        string mapped = noteStyle switch















        {















            "pixel" => "game/skins/pixel",















            "pixel-erect" => "game/skins/pixel",















            _ => "game/skins/default"















        };















        















        if (Assets.ResolveDirectory(mapped) != null)















            return mapped;















        















        return "game/skins/default";















    }















    















    /// <summary>















    /// Map chart stage names to actual stage folder names on disk.















    /// Chart metadata uses names like "mainStage", "spookyMansion", etc.















    /// </summary>















    /// <summary>

    /// Returns the mod folder name for PsychPaths.CurrentModDirectory.

    /// PsychMods expects a relative folder name under the mods root, not a full path.

    /// </summary>

    private string GetPsychModName(string modPath)

    {

        if (string.IsNullOrEmpty(modPath)) return null;

        var root = ModManager.Instance?.ModsRoot;

        if (!string.IsNullOrEmpty(root)

            && modPath.StartsWith(root, StringComparison.OrdinalIgnoreCase))

        {

            string relative = Path.GetRelativePath(root, modPath);

            int sep = relative.IndexOfAny(new[] { Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar });

            return sep > 0 ? relative.Substring(0, sep) : relative;

        }

        return Path.GetFileName(modPath.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));

    }



    /// <summary>

    /// Returns the active song mod plus all enabled mod roots in priority order.

    /// </summary>

    private List<string> GetPsychModRootPaths()

    {

        var roots = new List<string>();

        if (!string.IsNullOrEmpty(_modPath) && global::FNF_MonoGame.Engine.FsCI.DirectoryExists(_modPath))

            roots.Add(_modPath);



        foreach (var mod in PsychMods.GetAllMods().Where(m => m.Enabled && m.IsGlobal)) // Psych: only runsGlobally mods besides the current one

        {
            string modPath = PsychMods.GetModDirectory(mod.Name);
            if (!string.IsNullOrEmpty(modPath) && global::FNF_MonoGame.Engine.FsCI.DirectoryExists(modPath)
                && !roots.Contains(modPath, StringComparer.OrdinalIgnoreCase))
                roots.Add(modPath);
        }

        string modsRoot = PsychPaths.Mods();
        if (!string.IsNullOrEmpty(modsRoot) && global::FNF_MonoGame.Engine.FsCI.DirectoryExists(modsRoot)
            && !roots.Contains(modsRoot, StringComparer.OrdinalIgnoreCase))
            roots.Add(modsRoot);



        return roots;

    }



    /// <summary>

    /// Parse Psych Engine Lua/Hx stage scripts and load any background sprites as StaticStageProps.

    /// Searches across the active song mod and all enabled mods so global/shared stages load correctly.

    /// </summary>

    private void LoadPsychStageSprites(string stageName)

    {

        if (string.IsNullOrEmpty(stageName)) return; if (Environment.GetEnvironmentVariable("FNF_STAGE_PARSER") != "1") return; // the stage .lua/.hx runs in the Psych script runtime (PlayScene.PsychLua.cs) like PlayState; the old static parser created duplicate props (Majin "glitch" drawn while the script keeps it at alpha 0)



        foreach (var root in GetPsychModRootPaths())
        {
            string luaPath = Path.Combine(root, "stages", $"{stageName}.lua");
            string hxPath = Path.Combine(root, "stages", $"{stageName}.hx");

            List<PsychStageSprite> sprites = null;
            if (global::FNF_MonoGame.Engine.FsCI.FileExists(luaPath))
            {
                Console.WriteLine($"[MODS] Loading stage Lua script: {luaPath}");
                sprites = PsychStageScriptParser.ParseLua(luaPath);
            }
            else if (global::FNF_MonoGame.Engine.FsCI.FileExists(hxPath))
            {
                Console.WriteLine($"[MODS] Loading stage Haxe script: {hxPath}");
                sprites = PsychStageScriptParser.ParseHaxe(hxPath);
            }

            if (sprites == null || sprites.Count == 0)
                continue;

            // Build static stage props from parsed sprites; inFront sprites go above characters.
            int behindZ = -1000;
            int frontZ = 1000;
            foreach (var s in sprites)
            {
                if (s.Alpha < 0.01f || !s.Visible)
                    continue;

                string imagePath = $"images/{s.ImagePath}";
                string resolvedPng = Assets.ResolvePath(imagePath + ".png");
                if (resolvedPng == null)
                {
                    Console.WriteLine($"[MODS] Stage sprite image not found: {imagePath}");
                    continue;
                }

                try
                {
                    Texture2D tex = Texture2D.FromFile(Game.GraphicsDevice, global::FNF_MonoGame.Engine.FsCI.Fix(resolvedPng));
                    float scaleX = s.ScaleX;
                    float scaleY = s.ScaleY;
                    if (s.SetWidth.HasValue && s.SetHeight.HasValue)
                    {
                        scaleX = s.SetWidth.Value / (float)tex.Width;
                        scaleY = s.SetHeight.Value / (float)tex.Height;
                    }

                    int z = s.InFront ? frontZ++ : behindZ++;
                    _staticProps.Add(new StaticStageProp
                    {
                        Name = s.Tag,
                        Texture = tex,
                        X = s.X,
                        Y = s.Y,
                        ScaleX = scaleX,
                        ScaleY = scaleY,
                        Alpha = s.Alpha,
                        ScrollX = s.ScrollFactorX,
                        ScrollY = s.ScrollFactorY,
                        ZIndex = z,
                        Blend = null
                    });
                    Console.WriteLine($"[MODS] Loaded stage sprite: {s.Tag} ({s.ImagePath}) at ({s.X},{s.Y}) scale ({scaleX:0.00},{scaleY:0.00}) z={z}");
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"[MODS] Failed to load stage sprite {s.Tag}: {ex.Message}");
                }
            }

            // If we loaded any sprites from this root, stop searching.
            if (_staticProps.Count > 0)
                return;
        }

    }



    private static readonly string[] PsychBuiltInStages = { "stage", "spooky", "philly", "limo", "mall", "mallEvil", "school", "schoolEvil", "tank", "phillyStreets", "phillyBlazin" };

    private string ResolveStageFolder(string stageName)















    {















        string resolved = stageName switch















        {















            "mainStage" => "stage",















            "stage" => "stage",















            "mainStageErect" => "stage_erect",















            "stageErect" => "stage_erect",















            "stage_erect" => "stage_erect",















            "spookyMansion" => "spooky",















            "spookyMansionErect" => "spooky",















            "spooky" => "spooky",















            "phillyTrain" => "philly_train",















            "phillyTrainErect" => "philly_train_erect",















            "philly" => "philly_train",















            "philly-train" => "philly_train",















            "philly_train_erect" => "philly_train_erect",















            "limoRide" => "limo",















            "limoRideErect" => "limo_erect",















            "limo" => "limo",















            "limo_erect" => "limo_erect",















            "phillyStreets" => "philly_streets",















            "phillyStreetsErect" => "philly_streets",















            "philly_streets" => "philly_streets",















            "mallXmas" => "christmas",















            "mallXmasErect" => "christmas",















            "mallEvil" => "christmas",















            "school" => "school",















            "schoolEvil" => "school",















            "schoolErect" => "school",















            "schoolEvilErect" => "school",















            "tankmanBattlefield" => "tankman",















            "tankmanBattlefieldErect" => "tankman",















            "phillyBlazin" => "philly_blazin",















            // Asset path prefixes used in stage JSONs (e.g., "weeb/weebSky" splits to "weeb")















            "weeb" => "school",















            _ => stageName















        };















        















        // Verify the folder exists (Content or funkin.assets), fall back to "stage"















        if (Assets.ResolveDirectory($"game/stages/{resolved}") != null)















            return resolved;















        if (Assets.ResolveDirectory($"game/stages/{stageName}") != null)















            return stageName;















        















        Console.WriteLine($"Stage folder not found for '{stageName}', falling back to 'stage'");















        return "stage";















    }































    /// <summary>















    /// Build stage JSON name candidates for robust lookup across stage aliases.















    /// </summary>















    private List<string> GetStageDataNameCandidates(string stageName, string stageFolder)















    {















        var candidates = new List<string>();































        if (!string.IsNullOrWhiteSpace(stageName))















        {















            candidates.Add(stageName);















            candidates.Add(stageName.Replace('-', '_'));















            candidates.Add(stageName.Replace('_', '-'));















        }































        if (!string.IsNullOrWhiteSpace(stageFolder))















        {















            candidates.Add(stageFolder);















            candidates.Add(stageFolder.Replace('-', '_'));































            string canonical = stageFolder switch















            {















                "stage" => "mainStage",















                "stage_erect" => "mainStageErect",















                "spooky" => "spookyMansion",















                "philly_train" => "phillyTrain",















                "philly_train_erect" => "phillyTrainErect",















                "limo" => "limoRide",















                "limo_erect" => "limoRideErect",















                "philly_streets" => "phillyStreets",















                "christmas" => "mallXmas",















                "school" => "school",















                "tankman" => "tankmanBattlefield",















                _ => null















            };































            if (!string.IsNullOrWhiteSpace(canonical))















                candidates.Add(canonical);















        }































        return candidates















            .Where(c => !string.IsNullOrWhiteSpace(c))















            .Distinct(StringComparer.OrdinalIgnoreCase)















            .ToList();















    }































    /// <summary>















    /// Ensure pending stage character slot data is available for BF/DAD/GF.















    /// This is a fallback path for cases where phased stage loading did not















    /// populate pending arrays before characters are initialized.















    /// </summary>















    private void EnsurePendingStageCharacterData(string stageFolder)















    {















        _isPsychEngineStage = false; Character.PsychStageActive = false; _psychStageHideGf = false;















        StageJsonData stageJson = null;



        // Prefer mod stage data over base game stage data when playing a mod song


        PsychSetStageUI(PsychNotes && (_chart?.Stage == "school" || _chart?.Stage == "schoolEvil") ? "pixel" : "normal"); // StageData.dummy() / Psych base_game school*.json
        foreach (var root in PsychStageJsonRoots())

        {

            string psychStageName = _chart.Stage ?? "stage";

            string psychStagePath = System.IO.Path.Combine(root, "stages", $"{psychStageName}.json");


            if (global::FNF_MonoGame.Engine.FsCI.FileExists(psychStagePath))

            {

                try

                {

                    var psychStage = Newtonsoft.Json.JsonConvert.DeserializeObject<PsychStageData>(

                        global::FNF_MonoGame.Engine.FsCI.ReadAllText(psychStagePath));

                    if (psychStage != null)

                    {

                        Console.WriteLine($"[MODS] Loaded Psych Engine stage: {psychStageName}");

                        _isPsychEngineStage = true; Character.PsychStageActive = true; cameraSpeed = psychStage.CameraSpeed;

                        _defaultCamZoom = psychStage.DefaultZoom > 0 ? psychStage.DefaultZoom : 0.9f;

                        _pendingBfPos = psychStage.Boyfriend;

                        _pendingDadPos = psychStage.Opponent;

                        _pendingGfPos = psychStage.Girlfriend;

                        _pendingBfCamOffsets = psychStage.CameraBoyfriend;

                        _pendingDadCamOffsets = psychStage.CameraOpponent;

                        _pendingGfCamOffsets = psychStage.CameraGirlfriend;

                        _psychStageHideGf = psychStage.HideGirlfriend; PsychSetStageUI(!string.IsNullOrWhiteSpace(psychStage.StageUI) ? psychStage.StageUI : psychStage.IsPixelStage ? "pixel" : "normal"); if (_psyPopTex.Count > 0) PsyPopPreload(); // PlayState.create stageUI (+ re-cache popup art for it)

                        return;

                    }

                }

                catch (Exception ex)

                {

                    Console.WriteLine($"[MODS] Error loading Psych stage {psychStageName}: {ex.Message}");

                }

            }

        }















                foreach (var candidate in GetStageDataNameCandidates(_chart.Stage, stageFolder))
        {

            stageJson = null;

            // Check enabled mod roots first for V-Slice stage character data.
            if (!string.IsNullOrEmpty(_modPath))
            {
                foreach (var root in GetPsychModRootPaths())
                {
                    string modStagePath = Path.Combine(root, "data", "stages", candidate + ".json");
                    if (global::FNF_MonoGame.Engine.FsCI.FileExists(modStagePath))
                    {
                        try
                        {
                            stageJson = Newtonsoft.Json.JsonConvert.DeserializeObject<StageJsonData>(global::FNF_MonoGame.Engine.FsCI.ReadAllText(modStagePath));
                            if (stageJson != null)
                            {
                                Console.WriteLine($"[MODS] Loaded mod stage character data: {modStagePath}");
                                break;
                            }
                        }
                        catch (Exception ex)
                        {
                            Console.WriteLine($"[MODS] Failed to load mod stage JSON {modStagePath}: {ex.Message}");
                        }
                    }
                }
            }

            if (stageJson == null)
                stageJson = Assets.LoadJson<StageJsonData>($"data/stages/{candidate}");

            if (stageJson != null)
                break;

        }


































        if (stageJson?.Characters == null)















            return;































        if (stageJson.Characters.Bf?.Position != null)















            _pendingBfPos = stageJson.Characters.Bf.Position; _pendingBfScale = stageJson.Characters.Bf.Scale;















        if (stageJson.Characters.Dad?.Position != null)















            _pendingDadPos = stageJson.Characters.Dad.Position; _pendingDadScale = stageJson.Characters.Dad.Scale;















        if (stageJson.Characters.Gf?.Position != null)















            _pendingGfPos = stageJson.Characters.Gf.Position; _pendingGfScale = stageJson.Characters.Gf.Scale;































        _pendingBfCamOffsets = stageJson.Characters.Bf?.CameraOffsets;















        _pendingDadCamOffsets = stageJson.Characters.Dad?.CameraOffsets;















        _pendingGfCamOffsets = stageJson.Characters.Gf?.CameraOffsets;































        if (stageJson.Characters.Gf != null) _gfZIndex = stageJson.Characters.Gf.ZIndex;















        if (stageJson.Characters.Dad != null) _dadZIndex = stageJson.Characters.Dad.ZIndex;















        if (stageJson.Characters.Bf != null) _bfZIndex = stageJson.Characters.Bf.ZIndex;















    }















    















    /// <summary>















    /// Load stage textures from JSON data if available, otherwise fall back to resolved folder.















    /// Parses Content/data/stages/{stageName}.json for prop definitions.















    /// </summary>















    private void LoadStageTextures(string stageFolder)















    {















        // Clear any previously loaded props (prevents accumulation across songs)















        _staticProps.Clear();















        _animatedProps.Clear();















        _2hotSpawnedCans.Clear();















        _2hotCanStates.Clear();















        _2hotGunCocked = false;















        _2hotGunCockedTimer = 0f;















        _2hotPicoExplodeDeath = false;















        _hasJsonStage = false;















        _fastCarStaticIndex = -1;















        _fastCarCanDrive = false;















        _halloweenBGPropIndex = -1;















        _trainStaticIndex = -1;















        _phillyLightsIndex = -1;















        _hasAbotFallback = false;















        _abotIsPixel = false;















        _isNenePixel = false;















        _abotPixelBaseSet = false;







        _abotRuntimePosLogged = false;















        















        string basePath = $"game/stages/{stageFolder}";















        Console.WriteLine($"Loading stage: {stageFolder}");















        















        // Try loading stage JSON (original uses data/stages/{stageName}.json)















        // Use robust candidate lookup so all stage aliases still get character positions.















        StageJsonData stageJson = null;















        string loadedStageDataName = null;
        bool hasModStageScript = false;
        if (!string.IsNullOrEmpty(_modPath))
        {
            string psychStageName = _chart.Stage ?? "stage";
            foreach (var root in GetPsychModRootPaths())
            {
                // PlayState.create: only the built-in stage names (switch curStage 381-391) create stage art; any other
                // mod stage (stages/<name>.json) draws only what its scripts add -> no V-Slice fallback stage.
                if (global::FNF_MonoGame.Engine.FsCI.FileExists(Path.Combine(root, "stages", $"{psychStageName}.lua")) ||
                    global::FNF_MonoGame.Engine.FsCI.FileExists(Path.Combine(root, "stages", $"{psychStageName}.hx")) ||
                    (global::FNF_MonoGame.Engine.FsCI.FileExists(Path.Combine(root, "stages", $"{psychStageName}.json")) && System.Array.IndexOf(PsychBuiltInStages, psychStageName) < 0))
                {
                    hasModStageScript = true;
                    break;
                }
            }
        }















                foreach (var candidate in GetStageDataNameCandidates(_chart.Stage, stageFolder))
        {

            stageJson = null;

            // Check enabled mod roots first for V-Slice stage JSON.
            if (!string.IsNullOrEmpty(_modPath))
            {
                foreach (var root in GetPsychModRootPaths())
                {
                    string modStagePath = Path.Combine(root, "data", "stages", candidate + ".json");
                    if (global::FNF_MonoGame.Engine.FsCI.FileExists(modStagePath))
                    {
                        try
                        {
                            stageJson = Newtonsoft.Json.JsonConvert.DeserializeObject<StageJsonData>(global::FNF_MonoGame.Engine.FsCI.ReadAllText(modStagePath));
                            if (stageJson != null)
                            {
                                _stageJsonFilePath = modStagePath;
                                Console.WriteLine($"[MODS] Loaded mod stage JSON: {modStagePath}");
                                break;
                            }
                        }
                        catch (Exception ex)
                        {
                            Console.WriteLine($"[MODS] Failed to load mod stage JSON {modStagePath}: {ex.Message}");
                        }
                    }
                }
            }

            stageJson = LoadPsychObjectsStage() ?? stageJson; // Psych 1.0 stages/<id>.json "objects" win for Psych mod songs (StageData.addObjectsToState)
            if (stageJson == null) stageJson = LoadPsychBuiltinStageProps(); // Psych mod song on built-in 'stage' (StageWeek1)
            if (stageJson == null && !hasModStageScript)
            {
                stageJson = Assets.LoadJson<StageJsonData>($"data/stages/{candidate}");
                if (stageJson != null)
                    _stageJsonFilePath = System.IO.Path.Combine(FNF_MonoGame.Engine.AssetManager.ContentRoot, "data", "stages", candidate + ".json");
            }

            if (stageJson != null)
            {

                loadedStageDataName = candidate;

                break;

            }

        }































        if (stageJson != null)















        {















            _isPhillyBlazinStage = string.Equals(stageFolder, "philly_blazin", StringComparison.OrdinalIgnoreCase)















                || string.Equals(_chart.Stage, "phillyBlazin", StringComparison.OrdinalIgnoreCase);















            int propCount = stageJson.Props?.Count ?? 0;















            Console.WriteLine($"Loaded stage JSON for '{loadedStageDataName}' with {propCount} props");















            _hasJsonStage = true;















            _stageDirectory = stageJson.Directory;















            















            // Apply camera zoom from stage JSON (original: defaultCamZoom)















            _defaultCamZoom = stageJson.CameraZoom; _stageZoom = _defaultCamZoom; // PlayState.stageZoom















            















            var sortedProps = (stageJson.Props ?? new List<StageProp>()).OrderBy(p => p.ZIndex).ToList();















            















            foreach (var prop in sortedProps)















            {















                if (string.IsNullOrEmpty(prop.AssetPath)) continue;















                















                // Handle animated props separately







                bool isAnimated = prop.Animations != null && prop.Animations.Count > 0;







                if (isAnimated || prop.DanceEvery > 0)







                {















                    // Skip color-hex props (they have no spritesheet)















                    if (prop.AssetPath.StartsWith("#")) continue;















                    















                    string stageDir = ResolveStageFolder(_chart.Stage);















                    















                    // Stage JSON assetPaths may include a folder prefix (e.g., "limo/bgLimo").















                    // Strip the prefix if it matches the stage folder to avoid double-path.















                    // Preserves subpaths (e.g., "christmas/erect/bottomBop" -> "erect/bottomBop")















                    string propPath = prop.AssetPath;















                    if (propPath.Contains('/'))















                    {















                        string[] parts = propPath.Split('/');















                        string prefix = ResolveStageFolder(parts[0]);















                        if (prefix == stageDir)















                            propPath = string.Join('/', parts[1..]);















                        // Erect stages use "erect/" prefix � strip it















                        // Erect stages use "erect/" prefix — strip it only when the stage







                        // folder itself is an erect variant (e.g., philly_train_erect).







                        // For base stages like "tankman", assets genuinely live in erect/ subfolder.







                        else if (parts[0] == "erect" && stageDir.EndsWith("_erect"))















                            propPath = string.Join('/', parts[1..]);















                    }















                    















                    var sheet = SpriteSheet.Load(Game, $"game/stages/{stageDir}/{propPath}", preRenderComposites: true);















                    















                    // Try funkin.assets week directory (e.g., week2/images/halloween_bg)















                    if (sheet == null && !string.IsNullOrEmpty(_stageDirectory))















                        sheet = SpriteSheet.Load(Game, $"{_stageDirectory}/images/{prop.AssetPath}");















                    















                    // Try cross-stage path















                    if (sheet == null && prop.AssetPath.Contains('/'))















                    {















                        string[] parts = prop.AssetPath.Split('/');















                        string subFolder = ResolveStageFolder(parts[0]);















                        string fileName = parts[^1];















                        sheet = SpriteSheet.Load(Game, $"game/stages/{subFolder}/{fileName}");















                        if (sheet == null)















                            sheet = SpriteSheet.Load(Game, $"game/stages/{subFolder}/erect/{fileName}");















                        // "philly/erect/bgFreaks" -> try philly_train_erect/bgFreaks















                        if (sheet == null && parts.Length >= 3 && parts[1] == "erect")















                            sheet = SpriteSheet.Load(Game, $"game/stages/{subFolder}_erect/{fileName}");















                    }















                    if (sheet == null)















                        sheet = SpriteSheet.Load(Game, $"game/stages/{stageDir}/erect/{prop.AssetPath}");















                    















                    // Try shared images















                    if (sheet == null)















                        sheet = SpriteSheet.Load(Game, $"images/{prop.AssetPath}");















                    















                    if (sheet == null) continue;















                    















                    // Register frame-index sub-animations from stage JSON















                    foreach (var anim in prop.Animations)















                    {















                        string prefix = anim.Prefix ?? anim.Name ?? "";















                        string animName = anim.Name ?? prefix;















                        if (string.IsNullOrEmpty(prefix) || string.IsNullOrEmpty(animName)) continue;















                        















                        // Find the full animation by prefix















                        var fullFrames = sheet.GetAnimationFuzzy(prefix);















                        if (fullFrames == null || fullFrames.Count == 0) continue;















                        















                        if (anim.FrameIndices != null && anim.FrameIndices.Length > 0)















                        {















                            // Create sub-animation from specific frame indices















                            var subFrames = new List<SpriteFrame>();















                            foreach (int idx in anim.FrameIndices)















                            {















                                if (idx >= 0 && idx < fullFrames.Count)















                                    subFrames.Add(fullFrames[idx]);















                            }















                            if (subFrames.Count > 0)















                                sheet.Animations[animName] = subFrames;















                        }















                        else if (animName != prefix && !sheet.Animations.ContainsKey(animName))















                        {















                            // Alias: register the full animation under the animation name















                            sheet.Animations[animName] = fullFrames;















                        }















                    }















                    















                    var animSprite = new AnimatedSprite { Sheet = sheet };















                    float px = prop.Position != null && prop.Position.Length >= 1 ? prop.Position[0] : 0;















                    float py = prop.Position != null && prop.Position.Length >= 2 ? prop.Position[1] : 0;















                    bool applyStageMatrix = prop.AtlasSettings?.ApplyStageMatrix ?? false;







                    // Pre-rendered composites are in local space (stage offset stripped during







                    // CollectPartsWithTransforms). The JSON position is the desired screen position.







                    // FlxAnimate's applyStageMatrix() only applies to runtime-composited sprites







                    // where element positions include the stage offset; for pre-rendered composites







                    // it should be a no-op.















                    animSprite.Position = new Vector2(px, py);
                    // flixel-animate draw (applyStageMatrix atlas props: sniper/guy): timeline box anchoring, no per-frame bottom alignment
                    if (applyStageMatrix) animSprite.UseTimelineAnchoring = true;















                    















                    float sx = prop.Scale != null && prop.Scale.Length >= 1 ? prop.Scale[0] : 1f;















                    float sy = prop.Scale != null && prop.Scale.Length >= 2 ? prop.Scale[1] : sx;















                    animSprite.Scale = new Vector2(sx, sy);















                    if (prop.FlipX)















                        animSprite.Effects = SpriteEffects.FlipHorizontally;















                    















                    // Build animation name map: JSON logical name -> actual spritesheet key







                    var animNameMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);







                    var animLoops = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);







                    var animOffsets = new Dictionary<string, Vector2>(StringComparer.OrdinalIgnoreCase);







                    foreach (var animDef in prop.Animations)







                    {







                        string logicalName = animDef.Name;







                        string actualKey = animDef.Prefix ?? animDef.Name;







                        if (string.IsNullOrEmpty(actualKey)) continue;







                        if (string.IsNullOrEmpty(logicalName)) logicalName = actualKey;







                        bool isLooped = animDef.Looped; // default false to match original Haxe (anim.looped ?? false)







                        string resolvedKey = actualKey;







                        if (sheet.Animations.ContainsKey(actualKey))







                        {







                            resolvedKey = actualKey;







                        }







                        else







                        {







                            // Flixel addByPrefix(prefix): frames whose name starts with the prefix followed by the
                            // frame number (e.g. "car1" -> "car10000"). The XML loader groups "car10000".."car40000"
                            // under one key "car", which made every car variant flicker; build the exact animation.
                            var exactPrefix = sheet.BuildAnimationFromPrefix(actualKey);
                            if (exactPrefix != null) { resolvedKey = actualKey; animNameMap[logicalName] = resolvedKey; animLoops[resolvedKey] = isLooped; if (animDef.Offsets != null && animDef.Offsets.Length >= 2) animOffsets[logicalName] = new Vector2(animDef.Offsets[0], animDef.Offsets[1]); continue; }
                            var fuzzyFrames = sheet.GetAnimationFuzzy(actualKey);







                            if (fuzzyFrames != null && fuzzyFrames.Count > 0)







                            {







                                resolvedKey = sheet.Animations.FirstOrDefault(k => k.Value == fuzzyFrames).Key ?? actualKey;







                            }







                            else if (sheet.Animations.ContainsKey(logicalName))







                            {







                                resolvedKey = logicalName;







                            }







                        }







                        animNameMap[logicalName] = resolvedKey;







                        animLoops[resolvedKey] = isLooped;







                        if (animDef.Offsets != null && animDef.Offsets.Length >= 2)







                            animOffsets[logicalName] = new Vector2(animDef.Offsets[0], animDef.Offsets[1]);







                    }















                    // Use startingAnimation if specified, otherwise first animation







                    string startAnim = prop.StartingAnimation;















                    if (string.IsNullOrEmpty(startAnim) && prop.Animations != null && prop.Animations.Count > 0)







                        startAnim = prop.Animations[0].Name ?? prop.Animations[0].Prefix;















                    if (string.IsNullOrEmpty(startAnim))







                        startAnim = "default";















                    int frameCount = 0;







                    if (!string.IsNullOrEmpty(startAnim))















                    {















                        string resolvedAnim = animNameMap.TryGetValue(startAnim, out var mappedAnim) ? mappedAnim : startAnim;







                        var frames = sheet.GetAnimationFuzzy(resolvedAnim);















                        if (frames != null && frames.Count > 0)















                        {















                            frameCount = frames.Count;







                            string animKey = sheet.Animations.FirstOrDefault(k => k.Value == frames).Key ?? resolvedAnim;







                            string resolvedStartKey = animNameMap.TryGetValue(startAnim, out var rsk) ? rsk : startAnim;







                            bool startLooped = animLoops.TryGetValue(resolvedStartKey, out bool sl) ? sl : false;















                            animSprite.PlayAnimation(animKey, loop: startLooped);















                        }















                        if (string.Equals(prop.Name, "guy", StringComparison.OrdinalIgnoreCase) || string.Equals(prop.Name, "rando", StringComparison.OrdinalIgnoreCase) || string.Equals(prop.Name, "sniper", StringComparison.OrdinalIgnoreCase))







                        {







                            bool hasRaw = sheet.RawCompositeData.ContainsKey(resolvedAnim);







                            bool hasComp = sheet.CompositeAnimations.ContainsKey(resolvedAnim);







                            Console.WriteLine($"[STREET-DEBUG] Prop '{prop.Name}' loaded at ({px},{py}) stageOffset=({sheet.StageOffset.X:0.0},{sheet.StageOffset.Y:0.0}) applyStageMatrix={applyStageMatrix} finalWorld=({px + (applyStageMatrix ? sheet.StageOffset.X : 0):0.0},{py + (applyStageMatrix ? sheet.StageOffset.Y : 0):0.0}) startAnim={startAnim} resolved={resolvedAnim} frames={frameCount} hasRaw={hasRaw} hasComp={hasComp}");







                        }















                    }















                    















                    // Build dance animation name list for alternation















                    string[] danceAnims = null;















                    if (prop.DanceEvery > 0)







                    {







                        // Original Bopper behavior: shouldAlternate is determined by presence of 'danceLeft' animation.







                        // Only set DanceAnimNames for danceLeft/danceRight alternation.







                        // For non-alternating props (like sniper/guy), the dance is always 'idle'.







                        bool hasDanceLeft = prop.Animations.Any(a => string.Equals(a.Name, "danceLeft", StringComparison.OrdinalIgnoreCase));







                        if (hasDanceLeft)







                        {







                            string dl = animNameMap.TryGetValue("danceLeft", out var mappedDL) ? mappedDL : "danceLeft";







                            string dr = animNameMap.TryGetValue("danceRight", out var mappedDR) ? mappedDR : "danceRight";







                            danceAnims = new[] { dl, dr };
                             // school.hxc / schoolErect.hxc buildStage: freaks.idleSuffix = '-scared' when the song id is roses
                             if (string.Equals(prop.Name, "freaks", StringComparison.OrdinalIgnoreCase) && W6BaseSong(_songName) == "roses"
                                 && ((_chart?.Stage ?? "") == "school" || (_chart?.Stage ?? "") == "schoolErect"))
                                 danceAnims = new[] { animNameMap.TryGetValue("danceLeft-scared", out var sdl) ? sdl : "danceLeft-scared",
                                                      animNameMap.TryGetValue("danceRight-scared", out var sdr) ? sdr : "danceRight-scared" };







                        }







                        else







                        {







                            string idleAnim = animNameMap.TryGetValue("idle", out var mappedIdle) ? mappedIdle : (prop.Animations.FirstOrDefault()?.Name ?? "idle");







                            danceAnims = new[] { idleAnim };







                        }







                    }















                    _animatedProps.Add(new AnimatedStageProp















                    {















                        Sprite = animSprite,















                        ZIndex = (int)prop.ZIndex,















                        Alpha = Math.Clamp(prop.Alpha, 0f, 1f),















                        ScrollX = prop.Scroll != null && prop.Scroll.Length >= 1 ? prop.Scroll[0] : 1f,















                        ScrollY = prop.Scroll != null && prop.Scroll.Length >= 2 ? prop.Scroll[1] : 1f,















                        DanceEvery = (int)prop.DanceEvery,















                        LastDanceBeat = -1,















                        Name = prop.Name ?? "",















                        DanceAnimNames = danceAnims,















                        DanceToggle = false,















                        ApplyStageMatrix = applyStageMatrix,















                        AnimNameMap = animNameMap,















                        AnimLoops = animLoops,















                        CanPlayOtherAnims = true,
                        Seq = ++s_propSeq,







                        Angle = prop.Angle,







                        FlipY = prop.FlipY,







                        Color = ParseStageColor(prop.Color),







                        Blend = prop.Blend,







                        AnimOffsets = animOffsets















                    });















                    continue;















                }















                















                // Static prop – load texture with position/scale/scroll from JSON















                var tex = LoadStagePropTexture(prop.AssetPath);















                if (tex == null || tex == Assets.Pixel) continue;















                















                float spx = prop.Position != null && prop.Position.Length >= 1 ? prop.Position[0] : 0;















                float spy = prop.Position != null && prop.Position.Length >= 2 ? prop.Position[1] : 0;















                float ssx = prop.Scale != null && prop.Scale.Length >= 1 ? prop.Scale[0] : 1f;















                float ssy = prop.Scale != null && prop.Scale.Length >= 2 ? prop.Scale[1] : ssx;















                float scrX = prop.Scroll != null && prop.Scroll.Length >= 1 ? prop.Scroll[0] : 1f;















                float scrY = prop.Scroll != null && prop.Scroll.Length >= 2 ? prop.Scroll[1] : 1f;















                























                _staticProps.Add(new StaticStageProp















                {















                    Texture = tex,















                    X = spx, Y = spy,















                    ScaleX = ssx, ScaleY = ssy,















                    Alpha = Math.Clamp(prop.Alpha, 0f, 1f),















                    ScrollX = scrX, ScrollY = scrY,















                    ZIndex = (int)prop.ZIndex,















                    Name = prop.Name ?? prop.AssetPath,















                    Blend = prop.Blend,















                    OverlayColor = ParseStageColor(prop.Color),















                    FlipX = prop.FlipX,







                    FlipY = prop.FlipY,







                    Angle = prop.Angle















                });















            }















            















            // Detect fastCar static prop for scripted movement (original limoRide.hxc)















            for (int si = 0; si < _staticProps.Count; si++)















            {















                if (_staticProps[si].Name == "fastCar")















                {















                    _fastCarStaticIndex = si;















                    _fastCarCanDrive = true;















                    break;















                }















            }















            















            // Detect halloweenBG animated prop for lightning flash (original spookyMansion)















            for (int ai = 0; ai < _animatedProps.Count; ai++)















            {















                if (_animatedProps[ai].Name == "halloweenBG")















                {















                    _halloweenBGPropIndex = ai;















                    break;















                }















            }















            // Detect spooky Erect stage props (bgLight, stairsLight)















            _isSpookyErectStage = string.Equals(_chart.Stage, "spookyMansionErect", StringComparison.OrdinalIgnoreCase);















            for (int si = 0; si < _staticProps.Count; si++)















            {















                if (_staticProps[si].Name == "bgLight")















                    _spookyBgLightIndex = si;















                else if (_staticProps[si].Name == "stairsLight")















                    _spookyStairsLightIndex = si;















            }















            if (_isSpookyErectStage)















            {















                // Start with lights hidden (original: alpha = 0.0001)















                if (_spookyBgLightIndex >= 0)















                {















                    var p = _staticProps[_spookyBgLightIndex];















                    p.Alpha = 0.0001f;















                    _staticProps[_spookyBgLightIndex] = p;















                }















                if (_spookyStairsLightIndex >= 0)















                {















                    var p = _staticProps[_spookyStairsLightIndex];















                    p.Alpha = 0.0001f;















                    _staticProps[_spookyStairsLightIndex] = p;















                }















            }















            















            // Detect train static prop for scripted movement (original phillyTrain.hxc)















            for (int si = 0; si < _staticProps.Count; si++)















            {















                if (_staticProps[si].Name == "train")















                {















                    _trainStaticIndex = si;















                    _trainX = _staticProps[si].X;















                    break;















                }















            }















            















            // Detect philly window lights prop for color cycling















            for (int si = 0; si < _staticProps.Count; si++)















            {















                if (_staticProps[si].Name == "lights")















                {















                    _phillyLightsIndex = si;















                    break;















                }















            }































            // Detect Philly Blazin stage props for lightning effects















            _isPhillyBlazinStage = string.Equals(_chart.Stage, "phillyBlazin", StringComparison.OrdinalIgnoreCase);















            _phillyBlazinSkyAdditiveIndex = _staticProps.FindIndex(p => p.Name == "skyAdditive");















            _phillyBlazinForegroundMultiplyIndex = _staticProps.FindIndex(p => p.Name == "foregroundMultiply");















            _phillyBlazinAdditionalLightenIndex = _staticProps.FindIndex(p => p.Name == "additionalLighten");















            _phillyBlazinLightningIndex = _animatedProps.FindIndex(p => p.Name == "lightning");















            if (_isPhillyBlazinStage)















            {















                _phillyBlazinLightningTimer = 3.0f;















                _phillyBlazinLightningFadeTimer = 0f;















                _phillyBlazinLightningShortFadeTimer = 0f;















                if (_phillyBlazinSkyAdditiveIndex >= 0)















                {















                    var sky = _staticProps[_phillyBlazinSkyAdditiveIndex];















                    sky.Alpha = 0f;















                    _staticProps[_phillyBlazinSkyAdditiveIndex] = sky;















                }















                if (_phillyBlazinForegroundMultiplyIndex >= 0)















                {















                    var fg = _staticProps[_phillyBlazinForegroundMultiplyIndex];















                    fg.Alpha = 0f;















                    _staticProps[_phillyBlazinForegroundMultiplyIndex] = fg;















                }















                if (_phillyBlazinAdditionalLightenIndex >= 0)















                {















                    var add = _staticProps[_phillyBlazinAdditionalLightenIndex];















                    add.Alpha = 0f;















                    _staticProps[_phillyBlazinAdditionalLightenIndex] = add;















                }















                if (_phillyBlazinLightningIndex >= 0)















                {















                    var lightning = _animatedProps[_phillyBlazinLightningIndex];















                    lightning.Alpha = 0f;















                    _animatedProps[_phillyBlazinLightningIndex] = lightning;















                }















            }















            















            // Detect Tankman Battlefield stage props (original: tankmanBattlefield.hxc)















            _isTankmanErect = string.Equals(_chart.Stage, "tankmanBattlefieldErect", StringComparison.OrdinalIgnoreCase);







            _isTankmanStage = string.Equals(_chart.Stage, "tankmanBattlefield", StringComparison.OrdinalIgnoreCase)















                || _isTankmanErect;















            _tankRollingIndex = _animatedProps.FindIndex(p => p.Name == "tankRolling");















            _tankCloudsIndex = _staticProps.FindIndex(p => p.Name == "clouds2");















            if (_isTankmanStage)















            {















                if (_tankCloudsIndex >= 0)















                {















                    var clouds = _staticProps[_tankCloudsIndex];















                    // clouds2 keeps the JSON alpha 0 (tankmanBattlefield.json; no script changes it) - the visible clouds are the tiled strip















                    _staticProps[_tankCloudsIndex] = clouds;















                }















                _tankAngle = -90f + (float)_random.NextDouble() * 135f;















                _tankSpeed = 5f + (float)_random.NextDouble() * 2f;















                _tankX = 400f;















            }















            















            // Stress song: initialize TankmanSpriteGroup (running tankmen that get shot)







            // Strip variant suffixes so "stress_erect" still matches (original uses base song name)







            string lowerSong = _songName?.ToLower() ?? "";







            foreach (var sfx in new[] { "_erect", "_pico", "_bf" })







            {







                if (lowerSong.EndsWith(sfx))







                {







                    lowerSong = lowerSong[..^sfx.Length];







                    break;







                }







            }







            // Handle song names like "Stress (Pico Mix)", "stress_pico", "stress", etc.







            _isStressSong = lowerSong == "stress" || lowerSong == "stress_pico"







                || lowerSong.Contains("stress") && (lowerSong.Contains("pico") || lowerSong.Contains("mix"))







                || _songName?.Replace(" ", "").Replace("(", "").Replace(")", "").ToLower().Contains("stresspico") == true;







            // Pico mix: tankman-bloody opponent + knife/redheads/end cutscene sequence







            _isStressPico = (_songName ?? "").ToLowerInvariant() == "stress_pico" // raw id: lowerSong has "_pico" stripped above







                || lowerSong.Contains("stress") && lowerSong.Contains("pico")







                || (_opponent?.OriginalName?.Contains("tankman-bloody") ?? false);







            _stressEndCutsceneTimer = -1f;







            _stressLaughPlayed = false;







            Console.WriteLine($"[STRESS-DETECT] songName='{_songName}' lowerSong='{lowerSong}' stage='{_chart?.Stage}' isStressSong={_isStressSong} isStressPico={_isStressPico} opp='{_opponent?.OriginalName}'");







            if (_isStressSong)







            {







                _tankmanStressSheet = SpriteSheet.Load(Game, "game/stages/tankman/erect/tankman_stress", preRenderComposites: true);







                if (_tankmanStressSheet != null)







                {







                    Console.WriteLine($"[STREET-DEBUG] Loaded tankman_stress sheet: {_tankmanStressSheet.Animations.Count} anims, {_tankmanStressSheet.CompositeAnimations.Count} composite");







                    try { File.AppendAllText("tankman_debug.log", $"[{DateTime.Now:HH:mm:ss}] Loaded tankman_stress sheet: {_tankmanStressSheet.Animations.Count} anims, {_tankmanStressSheet.CompositeAnimations.Count} composite. Keys: {string.Join(", ", _tankmanStressSheet.Animations.Keys.Take(10))}\n"); } catch { }







                }







                else







                {







                    Console.WriteLine($"[STREET-DEBUG] FAILED to load tankman_stress sheet");







                    try { File.AppendAllText("tankman_debug.log", $"[{DateTime.Now:HH:mm:ss}] FAILED to load tankman_stress sheet\n"); } catch { }







                }















                InitStressTankmen();







            }















            















            // Save character positions and camera offsets from stage JSON















            // (applied after characters are loaded � stage offsets override character JSON)















            if (stageJson.Characters != null)















            {















                if (stageJson.Characters.Bf?.Position != null)















                    _pendingBfPos = stageJson.Characters.Bf.Position; _pendingBfScale = stageJson.Characters.Bf.Scale;















                if (stageJson.Characters.Dad?.Position != null)















                    _pendingDadPos = stageJson.Characters.Dad.Position; _pendingDadScale = stageJson.Characters.Dad.Scale;















                if (stageJson.Characters.Gf?.Position != null)















                    _pendingGfPos = stageJson.Characters.Gf.Position; _pendingGfScale = stageJson.Characters.Gf.Scale;















                // Stage JSON camera offsets ADD to character JSON offsets (original Stage.hx behavior)















                _pendingBfCamOffsets = stageJson.Characters.Bf?.CameraOffsets;















                _pendingDadCamOffsets = stageJson.Characters.Dad?.CameraOffsets;















                _pendingGfCamOffsets = stageJson.Characters.Gf?.CameraOffsets;















                // Save character z-indices for proper interleaved draw order















                if (stageJson.Characters.Gf != null) _gfZIndex = stageJson.Characters.Gf.ZIndex;















                if (stageJson.Characters.Dad != null) _dadZIndex = stageJson.Characters.Dad.ZIndex;















                if (stageJson.Characters.Bf != null) _bfZIndex = stageJson.Characters.Bf.ZIndex;















            }















            return;















        }















        















        // Fallback: hardcoded stage loading by folder

        // If a Psych Engine stage JSON was loaded, treat it like a JSON stage so
        // the default base-game stage backdrop/front/curtains are not drawn.
        _hasJsonStage = _isPsychEngineStage;

        // If a mod stage script exists but no JSON was found, skip the default base-game stage layout.
        if (stageJson == null && !string.IsNullOrEmpty(_modPath))
        {
            string stageName = _chart.Stage ?? "stage";
            foreach (var root in GetPsychModRootPaths())
            {
                if (global::FNF_MonoGame.Engine.FsCI.FileExists(Path.Combine(root, "stages", $"{stageName}.lua")) ||
                    global::FNF_MonoGame.Engine.FsCI.FileExists(Path.Combine(root, "stages", $"{stageName}.hx")) ||
                    (global::FNF_MonoGame.Engine.FsCI.FileExists(Path.Combine(root, "stages", $"{stageName}.json")) && System.Array.IndexOf(PsychBuiltInStages, stageName) < 0)) // script-only Psych stage
                {
                    _hasJsonStage = true;
                    Console.WriteLine($"[MODS] Mod stage script found for {stageName}; skipping base stage layout.");
                    break;
                }
            }
        }

        if (_hasJsonStage)
        {
            _stageBackdrop = null;
            _stageFront = null;
            _stageCurtains = null;
            return;
        }















        















        // For non-JSON stages, characters are in screen-space coordinates.















        // Set camera so WorldToScreen is approximately a passthrough.















        _defaultCamZoom = 1.0f;















        _camWorldX = FNFGame.SCREEN_WIDTH / 2f;















        _camWorldY = FNFGame.SCREEN_HEIGHT / 2f;















        _camTargetWorldX = _camWorldX;















        _camTargetWorldY = _camWorldY;















        















        switch (stageFolder)















        {















            case "spooky":















                _stageBackdrop = Assets.LoadTexture($"{basePath}/bg.png");















                _stageFront = null;















                _stageCurtains = null;















                break;















            case "philly_train":















            case "philly_train_erect":















                _stageBackdrop = Assets.LoadTexture($"{basePath}/sky.png");















                _stageFront = Assets.LoadTexture($"{basePath}/street.png");















                _stageCurtains = null;















                break;















            case "limo":















            case "limo_erect":















                _stageBackdrop = Assets.LoadTexture($"{basePath}/limoSunset.png");















                _stageFront = Assets.LoadTexture($"{basePath}/bgLimo.png");















                _stageCurtains = null;















                break;















            case "philly_streets":















                _stageBackdrop = Assets.LoadTexture($"{basePath}/phillyTraffic.png");















                _stageFront = null;















                _stageCurtains = null;















                break;















            case "stage_erect":















                _stageBackdrop = Assets.LoadTexture($"{basePath}/bg.png");















                _stageFront = null;















                _stageCurtains = null;















                break;















            default:















                // Default "stage" layout















                _stageBackdrop = Assets.LoadTexture($"{basePath}/backdrop.png");















                _stageFront = Assets.LoadTexture($"{basePath}/front.png");















                _stageCurtains = Assets.LoadTexture($"{basePath}/curtains.png");















                break;















        }















    }















    















    /// <summary>















    /// Try loading a stage prop texture from its assetPath.















    /// Stage JSON references assets like "stageback" which maps to game/stages/stage/stageback.png















    /// Also handles:















    ///   - Color hex codes (#RRGGBB) ? creates a 1x1 solid color texture















    ///   - Cross-stage references (e.g., "phillyStreets/phillySkyline")















    ///   - funkin.assets week directory (e.g., directory="week2" ? week2/images/{assetPath}.png)















    ///   - Erect subfolder fallbacks















    /// </summary>















    private string _stageDirectory; // Set from stage JSON "directory" field















    















    private Texture2D LoadStagePropTexture(string assetPath)















    {















        if (string.IsNullOrEmpty(assetPath)) return null;















        















        // Handle color hex codes (e.g., "#8E9191") � create a solid color texture















        if (assetPath.StartsWith("#") && (assetPath.Length == 7 || assetPath.Length == 9))















        {















            try















            {















                string hex = assetPath.TrimStart('#');















                int r = Convert.ToInt32(hex[..2], 16);















                int g = Convert.ToInt32(hex[2..4], 16);















                int b = Convert.ToInt32(hex[4..6], 16);















                var colorTex = new Texture2D(Game.GraphicsDevice, 1, 1);















                colorTex.SetData(new[] { new Color(r, g, b) });















                return colorTex;















            }















            catch { return null; }















        }















        















        string stageFolder = ResolveStageFolder(_chart.Stage);















        















        // Strip stage folder prefix from assetPath to avoid double-path















        // (e.g., "limo/limoSunset" with stageFolder "limo" -> just "limoSunset")















        // Preserves subpaths (e.g., "christmas/erect/bgWalls" -> "erect/bgWalls")















        string resolvedAsset = assetPath;















        if (assetPath.Contains('/'))















        {















            string[] parts = assetPath.Split('/');















            string prefix = ResolveStageFolder(parts[0]);















            if (prefix == stageFolder)















                resolvedAsset = string.Join('/', parts[1..]);















            // Erect stages use "erect/" prefix in asset paths (e.g., "erect/bg", "erect/crowd")















            // Strip it � the files live directly in the stage folder, not an erect/ subfolder















            // Erect stages use "erect/" prefix — strip it only when the stage







            // folder itself is an erect variant (e.g., philly_train_erect).







            // For base stages like "tankman", assets genuinely live in erect/ subfolder.







            else if (parts[0] == "erect" && stageFolder.EndsWith("_erect"))















                resolvedAsset = string.Join('/', parts[1..]);















        }















        















        // Try: game/stages/{folder}/{asset} (Content directory)















        var tex = Assets.LoadTexture($"game/stages/{stageFolder}/{resolvedAsset}.png");















        if (tex != null && tex != Assets.Pixel) return tex;















        















        // Try: {weekDir}/images/{assetPath} (funkin.assets week directory from stage JSON)















        if (!string.IsNullOrEmpty(_stageDirectory))















        {















            tex = Assets.LoadTexture($"{_stageDirectory}/images/{assetPath}.png");















            if (tex != null && tex != Assets.Pixel) return tex;















        }















        















        // If assetPath contains a subfolder (e.g., "phillyStreets/phillySkyline"),















        // resolve the subfolder name to the actual stage folder and search there















        if (assetPath.Contains('/'))















        {















            string[] parts = assetPath.Split('/');















            string subStageFolder = ResolveStageFolder(parts[0]);















            string fileName = parts[^1];
            // "philly/erect/street" on phillyTrainErect: the erect folder must win over the base stage file of the same name
            if (parts.Length >= 3 && parts[1] == "erect") { tex = Assets.LoadTexture($"game/stages/{subStageFolder}_erect/{fileName}.png"); if (tex != null && tex != Assets.Pixel) return tex; }















            















            tex = Assets.LoadTexture($"game/stages/{subStageFolder}/{fileName}.png");















            if (tex != null && tex != Assets.Pixel) return tex;















            















            tex = Assets.LoadTexture($"game/stages/{subStageFolder}/erect/{fileName}.png");















            if (tex != null && tex != Assets.Pixel) return tex;















            















            tex = Assets.LoadTexture($"game/stages/{subStageFolder}/{string.Join('/', parts[1..])}.png");















            if (tex != null && tex != Assets.Pixel) return tex;















            















            // "philly/erect/sky" -> try philly_train_erect/sky.png















            if (parts.Length >= 3 && parts[1] == "erect")















            {















                string erectFolder = subStageFolder + "_erect";















                tex = Assets.LoadTexture($"game/stages/{erectFolder}/{fileName}.png");















                if (tex != null && tex != Assets.Pixel) return tex;















            }















        }















        















        // Try: game/stages/{folder}/erect/{assetPath}















        tex = Assets.LoadTexture($"game/stages/{stageFolder}/erect/{assetPath}.png");















        if (tex != null && tex != Assets.Pixel) return tex;















        















        // Try: images/{assetPath} (shared images � stageback, stagefront, etc.)















        tex = Assets.LoadTexture($"images/{assetPath}.png");















        if (tex != null && tex != Assets.Pixel) return tex;















        















        return null;















    }































    private static Color? ParseStageColor(string colorValue)















    {















        if (string.IsNullOrWhiteSpace(colorValue))















            return null;































        if (!colorValue.StartsWith("#", StringComparison.OrdinalIgnoreCase))















            return null;































        string hex = colorValue.TrimStart('#');















        if (hex.Length != 6 && hex.Length != 8)















            return null;































        if (!int.TryParse(hex[..2], System.Globalization.NumberStyles.HexNumber, null, out int r))















            return null;















        if (!int.TryParse(hex[2..4], System.Globalization.NumberStyles.HexNumber, null, out int g))















            return null;















        if (!int.TryParse(hex[4..6], System.Globalization.NumberStyles.HexNumber, null, out int b))















            return null;































        byte a = 255;















        if (hex.Length == 8 && !byte.TryParse(hex[6..8], System.Globalization.NumberStyles.HexNumber, null, out a))















            return null;































        return new Color(r, g, b, a);















    }















    















    private void StartSong()















    {
        // (removed duplicate Lua callback; fired once by the matching Dispatch*() above — Psych calls each callback once)















        if (PsychNotes) { StartSongAudio(); DispatchStartSong(); } // PlayState.startSong: playMusic before stage.startSong/onSongStart (songLength = inst length)



        else { DispatchStartSong(); StartSongAudio(); }
        StartSongPart2();
    }
    /// <summary>Opens the song tracks; with Audio.PrepareOnly it only pre-opens the readers (loading phase).</summary>
    private void StartSongAudio()
    {
        // Determine inst path � handle variant songs (e.g. bopeebo_erect ? bopeebo/Inst-erect)















        string baseSong = _songName;















        string variant = null;















        















        string[] variantSuffixes = { "_erect", "_pico", "_bf" };















        foreach (var suffix in variantSuffixes)















        {















            if (_songName.EndsWith(suffix))















            {















                baseSong = _songName[..^suffix.Length];















                variant = suffix[1..]; // "erect", "pico", or "bf"















                break;















            }















        }































        if (string.IsNullOrEmpty(variant)















            && !string.IsNullOrWhiteSpace(_selectedCharacterVariation) && _selectedCharacterVariation != "bf" /* chart load skips "bf" too (default variation) */















            && SongSupportsAudioVariation(baseSong, _selectedCharacterVariation))















        {















            variant = _selectedCharacterVariation;















        }















        















        // Build candidate inst filenames based on song variant and selected difficulty.















        var instFileCandidates = new List<string>();















        if (!string.IsNullOrEmpty(variant))















            instFileCandidates.Add($"Inst-{variant}");































        string difficultyId = (_currentDifficulty ?? "normal").Trim().ToLowerInvariant();















        if (difficultyId == "nightmare")















        {















            instFileCandidates.Add("Inst-nightmare");















            instFileCandidates.Add("Inst-erect");















        }















        else if (difficultyId == "erect")















        {















            instFileCandidates.Add("Inst-erect");















        }































        instFileCandidates.Add("Inst");















        // FreeplayState CapsuleOptionsMenu: targetInstrumental -> Inst-<id> from the base song folder
        if (!string.IsNullOrEmpty(_targetInstrumental)) instFileCandidates.Insert(0, "Inst-" + _targetInstrumental);
        instFileCandidates = instFileCandidates















            .Distinct(StringComparer.OrdinalIgnoreCase)















            .ToList();















        















        // Try multiple audio folder names � some songs use hyphens, others underscores















        // e.g. chart folder "dad_battle" but audio in "dadbattle"















        string[] audioFolders = GetAudioFolderCandidates(baseSong);















        















        string instPath = null;















        string audioFolder = null;















        foreach (var instFile in instFileCandidates) // most specific Inst-<variation> first across ALL folders (philly_nice has only Inst, philly-nice has Inst-erect)















        {















            foreach (var folder in audioFolders)















            {















                instPath = $"songs/{folder}/{instFile}";















                if (AudioFileExists(instPath))















                {















                    audioFolder = folder;















                    break;















                }















            }































            if (audioFolder != null)















                break;















        }















        















        // Fallback � just use baseSong















        if (audioFolder == null)















        {















            audioFolder = baseSong;















            instPath = $"songs/{baseSong}/{instFileCandidates[0]}";















        }















        















        Console.WriteLine($"Starting song: {instPath}");















        Audio.PlayMusic(instPath, false);
        if (!Audio.PrepareOnly) W6SetVizSource(instPath); // pixel A-Bot visualizer reads the Inst PCM (ABotVis.initAnalyzer)















        















        // Play voice tracks if they exist















        string playerChar = _chart.PlayerCharacter ?? "bf";















        string opponentChar = _chart.OpponentCharacter ?? "dad";















        var voiceSuffixes = new List<string>();















        if (!string.IsNullOrEmpty(variant))















            voiceSuffixes.Add($"-{variant}");















        if (difficultyId == "nightmare")















        {















            voiceSuffixes.Add("-nightmare");















            voiceSuffixes.Add("-erect");















        }















        else if (difficultyId == "erect")















        {















            voiceSuffixes.Add("-erect");















        }















        voiceSuffixes.Add("");















        voiceSuffixes = voiceSuffixes















            .Distinct(StringComparer.OrdinalIgnoreCase)















            .ToList();















        















        // Build candidate voice names: full char name, then base name (strip variant suffix)















        // e.g. "bf-car" -> try "Voices-bf-car", then "Voices-bf"















        var playerVoiceNames = new List<string> { playerChar };















        if (playerChar.Contains('-'))















            playerVoiceNames.Add(playerChar.Split('-')[0]); PsychVocalsNames(playerVoiceNames, playerChar, true);















        















        var opponentVoiceNames = new List<string> { opponentChar };















        if (opponentChar.Contains('-'))















            opponentVoiceNames.Add(opponentChar.Split('-')[0]); PsychVocalsNames(opponentVoiceNames, opponentChar, false);















        















        // Player voices � try per-character first (with fallback names), then combined Voices















        foreach (var pName in playerVoiceNames)















        {















            foreach (var voiceSuffix in voiceSuffixes)















            {















                string voicePath = $"songs/{audioFolder}/Voices-{pName}{voiceSuffix}";















                Audio.PlayVoices(voicePath);















                if (Audio.HasPlayerVoice)















                    break;















            }































            if (Audio.HasPlayerVoice)















                break;















        }















        















        // If per-character player voice not found, try combined Voices file















        if (!Audio.HasPlayerVoice)















        {















            foreach (var voiceSuffix in voiceSuffixes)















            {















                string combinedPath = $"songs/{audioFolder}/Voices{voiceSuffix}";















                Audio.PlayVoices(combinedPath);















                if (Audio.HasPlayerVoice)















                    break;















            }















        }















        















        // Opponent voices � try per-character (with fallback names)















        foreach (var oName in opponentVoiceNames)















        {















            foreach (var voiceSuffix in voiceSuffixes)















            {















                string opponentVoicePath = $"songs/{audioFolder}/Voices-{oName}{voiceSuffix}";















                Audio.PlayOpponentVoices(opponentVoicePath);















                if (Audio.HasOpponentVoice)















                    break;















            }































            if (Audio.HasOpponentVoice)















                break;















        }















        















    }
    private void StartSongPart2()
    {
        // Sync conductor with audio















        _conductor.SetAudioSync(() => Audio.MusicPosition);















        _conductor.Start(); PracticeOnSongStart();















        















        _countdownActive = false;















    }















    















    /// <summary>















    /// Get candidate audio folder names for a song.















    /// Charts use underscores (dad_battle) but audio may use hyphens (dadbattle) or other forms.















    /// </summary>















    private string[] GetAudioFolderCandidates(string songName)















    {















        var candidates = new List<string> { songName };















        















        // Try replacing underscores with hyphens















        if (songName.Contains('_'))















            candidates.Add(songName.Replace('_', '-'));















        















        // Try removing underscores entirely















        if (songName.Contains('_'))















            candidates.Add(songName.Replace("_", ""));















        















        // Try replacing hyphens with underscores















        if (songName.Contains('-'))















            candidates.Add(songName.Replace('-', '_'));















        















        // Try removing hyphens entirely















        if (songName.Contains('-'))















            candidates.Add(songName.Replace("-", ""));















        















        return candidates.Distinct().ToArray();















    }















    















    /// <summary>















    /// Check if an audio file exists at the given content-relative path















    /// </summary>















    private bool AudioFileExists(string path)















    {















        if (Assets.ResolvePath(path + ".ogg") != null) return true;















        string dir = Path.GetDirectoryName(path) ?? "";















        string file = Path.GetFileName(path);















        if (Assets.ResolvePath(Path.Combine(dir, "tracks", file + ".ogg")) != null) return true;















        return false;















    }































    private bool SongSupportsAudioVariation(string songName, string variation)















    {















        if (string.IsNullOrWhiteSpace(songName) || string.IsNullOrWhiteSpace(variation))















            return false;































        string variationId = variation.Trim().ToLowerInvariant();















        if (songName.EndsWith($"_{variationId}", StringComparison.OrdinalIgnoreCase))















            return true;































        foreach (string candidate in GetAudioFolderCandidates(songName))















        {















            if (AudioFileExists($"songs/{candidate}/Inst-{variationId}"))















                return true;































            string variantSong = $"{candidate}_{variationId}";















            if (Assets.ResolvePath($"songs/{variantSong}/charts/meta.json") != null















                || Assets.ResolvePath($"songs/{variantSong}/charts/chart.json") != null)















            {















                return true;















            }















        }































        return false;















    }































    private static string GetSelectedCharacterVariationId()















    {















        string selectedCharacter = (FNF_MonoGame.Engine.MultiplayerSession.CharOverride ?? Environment.GetEnvironmentVariable("FNF_FREEPLAY_CHAR") ?? HighscoreManager.Data.SelectedCharacter)?.Trim().ToLowerInvariant(); // env = dev test override















        if (string.IsNullOrWhiteSpace(selectedCharacter))















            return "bf"; return FNF_MonoGame.Engine.PlayerRegistry.VariationFamily(selectedCharacter); // mod players (KB owns bf) -> base family















    }















    















    public override void Unload()















    {
        VideoDestroy(); // stop a playing video cutscene (VideoCutscene.destroyVideo)
        StopPauseMusicV();
        Audio.ClearPrepared();
















        // Remove mod content root

        if (!string.IsNullOrEmpty(_modPath))

        {

            Audio.ExtraContentRoots.Remove(_modPath);

            Assets.RemoveExtraRoot(_modPath);
        }

        PsychMods.CurrentModDirectory = "";

        // Stop Psych Engine Lua scripts and tweens
        ShutdownPsychLua();
        FlxVideo.DisposeAll();
        ResetModchart();



        // Restore menu navigation mode for face buttons















        Input.GameplayMode = false;















        















        Audio.StopMusic();















        Audio.StopVoices();















        















        // Dispose character composite spritesheets (GPU resources)















        _boyfriend?.Dispose();















        _opponent?.Dispose();















        _girlfriend?.Dispose();















        















        // Dispose note/receptor spritesheets (each owns a Texture2D)















        _notesSheet?.Dispose();















        _receptorsSheet?.Dispose();















        _splashesSheet?.Dispose(); PsychSoundsDispose();















        _holdCoverSheet?.Dispose();















        















        // Dispose animated stage prop sheets















        foreach (var prop in _animatedProps)















            prop.Sprite?.Sheet?.Dispose();















    }















    















		public override void Update(GameTime gameTime)
		{
			float num = (float)gameTime.ElapsedGameTime.TotalSeconds; _rawDt = num; num *= SceneTimeScale; // practice playback rate
			FlxVideo.UpdateAll();
			UpdateModchartTweens(num);
			_lastDelta = num;
			if (!_paused) StopPauseMusicV();
			CustomSubstate instance = CustomSubstate.Instance;
			if (instance != null && instance.PendingCreate) instance.Create(); // FlxState.openSubState: created at the next update
			if (instance != null && instance.PendingClose) { instance.Close(); instance = null; } // destroy after the closing callback returned (FlxState.closeSubState)
			if (instance != null && instance.IsActive)
			{
				instance.Update(num);
				if (instance.PendingClose) { instance.Close(); }
				else if (instance.PausesGame)
				{
					return;
				}
			}
			DispatchUpdate(num);
			for (int i = 0; i < _staticProps.Count; i++)
			{
				_staticProps[i].UpdateAnimation(num);
			}
			if (_playLoading)
			{
				_playLoadDotTimer += num;
				ProcessPlayLoadPhase();
				return;
			}
			MpUpdate(num); // multiplayer: network + input routing (PlayScene.Multiplayer.cs)
			if (_2hotGunCocked)
			{
				_2hotGunCockedTimer -= num;
				if (_2hotGunCockedTimer <= 0f)
				{
					_2hotGunCocked = false;
				}
			}
			_animTimer += num;
			if (_animTimer >= 1f / 24f)
			{
				_animTimer = 0f;
				_animFrame++;
				if (_animFrame > 100000)
				{
					_animFrame = 0;
				}
			}
			if (VideoUpdate(num)) return; // video cutscene (PlayScene.VideoCutscene.cs): pause menu over the video
			if (!_paused) { W6Update(num); W6StageScriptUpdate(num); }
			if (!_paused && !_psychHold && _psychDlgClock >= 0f) _psychDlgClock += num; // dev clock after the Psych dialogue
			if (!_paused) QsUpdate(num); if (!_paused) W1CutsceneUpdate(num); if (!_paused) { SsfUpdate(num); W5Update(num); EggUpdate(num); CasingUpdate(num); DoppelUpdate(num); } // sserafim.hxc timers/tweens // weekend 1 song-script cutscene timers/tweens
			if (_dialogueActive)
			{
				UpdateDialogue(num);
				return;
			}
			HandleAbotDebugInput();
			HandlePosDebugInput();
			HandlePropDebugInput();
			bool num2 = base.Input.PauseTogglePressed; // Escape / pad Pause button (Options > Controls)
			bool flag = base.Input.PauseOpenEnterPressed;
			bool flag2 = false;
			if (MpHandlePause(num2, flag)) return; // online versus: leave instead of pause
			if (StickerTransition.Active) return; // StickerSubState opened over the pause menu: PlayState/Pause frozen
			if (num2 || (!_paused && flag) || DevPauseRequested() || ConsumeFocusPause())
			{
				if (_paused)
				{
					if (false && _pauseDifficultyMode) // original: PAUSE_P always resumes
					{
						_pauseDifficultyMode = false;
						_pauseSelection = 0;
						BuildPauseMenuItems();
						base.Audio.PlaySound("scrollMenu");
					}
					else
					{
						_paused = false;
						StopPauseMusicV();
						CallOnLuas("onResume");
						base.Input.GameplayMode = true;
						bool flag3 = _weekSongs != null;
						string weekName = (flag3 ? _weekId : null);
						base.Game.Discord?.SetResumed(_songName, _currentDifficulty, flag3, weekName, _practiceMode, _botplay);
						if (!_countdownActive)
						{
							base.Audio.ResumeMusic();
							_conductor.Resume();
						}
					}
				}
				else if (!_gameOver && QsMayPause && !_vsHoldCountdown) // PlayState.pause: mayPauseGame (QT sawblade sequence); Standard pause needs isInCountdown (not while a script holds the countdown)
				{
					_paused = true;
					CallOnLuas("onPause");
					bool flag4 = _weekSongs != null;
					string weekName2 = (flag4 ? _weekId : null);
					base.Game.Discord?.SetPaused(_songName, _currentDifficulty, flag4, weekName2, _practiceMode, _botplay);
					flag2 = true;
					base.Input.GameplayMode = false;
					_pauseSelection = 0;
					_pauseScrollLerp = 0f;
					_pauseBgAlpha = 0f;
					_pauseMetadataAlpha = 0f;
					_pauseMenuAlpha = 0f;
					_pauseTimer = 0f;
					_pauseDifficultyMode = false;
					BuildPauseMenuItems();
					if (!_countdownActive)
					{
						base.Audio.PauseMusic();
						_conductor.Pause();
					}
					Console.WriteLine($"[PAUSE] open esc/start={num2} enter={flag} song={_conductor.SongPosition:0.000} countdown={_countdownActive}"); PauseOpenedV(); // PauseSubState port: Scenes/PlayScene.Pause.cs (no sound on open in the original)
				}
			}
			if (_paused)
			{
				UpdatePauseMenuV(num, flag2); // PauseSubState port: Scenes/PlayScene.Pause.cs
				return;
			}
			if (_gameOver)
			{
				UpdateGameOverV(num); // GameOverSubState port: Scenes/PlayScene.GameOver.cs
				return;
			}
			if (_countdownActive)
			{
				if (MpHoldStart()) { _boyfriend.Update(num); _opponent.Update(num); _girlfriend?.Update(num); return; } // online: wait for both players
				UpdateCountdown(num); NsCountdownUpdate(num); SetPlayerHoldFlags();
				_boyfriend.Update(num);
				_opponent.Update(num);
				_girlfriend?.Update(num);
				if (_isStressSong) { double cdc = _conductor.Crochet; _tmPosOverrideMs = Math.Min(0.0, (-5.0 * cdc + _countdownStep * cdc + _countdownTimer) * 1000.0); UpdateStressTankmen(num); _tmPosOverrideMs = null; } // TankmanSpriteGroup updates during the countdown (PlayScene.Tank.cs)
				UpdateDuringCountdown(num); // PlayState.update runs during the countdown: props animate, A-Bot anchored, HUD health lerp (PlayScene.PropDance.cs)
				// PlayState.processSongEvents: queryEvents(songPosition) finds nothing while songPosition < 0 (countdown);
				// the port's song position is 0 during the countdown, so time-0 events must wait for the song start.
				return;
			}
			if (!SongEndFrozen) _conductor.Update(num); // endSong(): music stopped -> Conductor frozen (in-game ending cutscenes)
			float stepCrochet = (float)_conductor.StepCrochet;
			_boyfriend.StepCrochet = stepCrochet;
			_opponent.StepCrochet = stepCrochet;
			if (_girlfriend != null)
			{
				_girlfriend.StepCrochet = stepCrochet;
			}
			_resyncTimer += num;
			if (_resyncTimer >= 0.5f)
			{
				_resyncTimer = 0f;
				base.Audio.ResyncVoices();
			}
			float num5 = PsychNotes && !_psychCamZooming ? 1f : MathF.Exp((PsychNotes ? -3.125f * camZoomingDecay : (_isPsychEngineStage ? -3.125f : -3.0775950f /* 60 * ln(0.95): lerp(default, zoom, 0.95^(elapsed*60)) */)) * num); // Psych: lerp(default, zoom, exp(-elapsed * 3.125 * camZoomingDecay))
			_cameraBopMultiplier = 1f + (_cameraBopMultiplier - 1f) * num5;
			_hudZoomAdd *= num5;
			float num6 = _isPsychEngineStage ? 1f - MathF.Exp(-num * 0.04f * cameraSpeed / (1f / 60f)) /* PsychCamera.updateFollowDelta, followLerp = 0.04 * cameraSpeed */ : 1f - MathF.Pow(1f - 0.04f, num * 60f); // FlxCamera.updateFollow: 1 - (1 - followLerp)^(elapsed*60), followLerp = Constants.DEFAULT_CAMERA_FOLLOW_RATE (0.04)
			if (!_camFollowTweening) _camWorldX += (_camTargetWorldX - _camWorldX) * num6; // FlxG.camera.target = null while tweening
			if (!_camFollowTweening) _camWorldY += (_camTargetWorldY - _camWorldY) * num6;
			if (!_hasJsonStage)
			{
				_cameraTargetX = _camTargetWorldX - 640f;
				_cameraTargetY = _camTargetWorldY - 360f;
			}
			_cameraX += (_cameraTargetX - _cameraX) * num6;
			_cameraY += (_cameraTargetY - _cameraY) * num6;
			float num7 = MathF.Exp(-10.397f * num);
			_iconBounceScale = 1f + (_iconBounceScale - 1f) * num7;
			_npsTimer += num;
			if (_npsTimer >= 1f)
			{
				_npsTimer -= 1f;
				_nps = _npsCounter;
				_npsCounter = 0;
			}
			if (!_countdownActive && !_paused && !_gameOver)
			{
				bool flag5 = _weekSongs != null;
				string weekName3 = (flag5 ? _weekId : null);
				base.Game.Discord?.UpdateGameplayPresence(_songName, _currentDifficulty, flag5, weekName3, _practiceMode, _botplay);
			}
			float num8 = MathF.Exp(-6.321f * num);
			PsychHudUpdate(num); if (UseVSliceHud) HudUpdate(num); else _healthLerp = _health + (_healthLerp - _health) * num8;
			for (int j = 0; j < 4; j++)
			{
				if (_noteSplashTimer[j] > 0f)
				{
					_noteSplashTimer[j] -= num;
				}
			}
			for (int k = 0; k < 4; k++)
			{
				if (_playerConfirmTimer[k] > 0f)
				{
