    private void UpdateCountdown(float delta)















    {















        float beatDuration = (float)_conductor.Crochet;















        _countdownTimer += delta;















        















        if (_countdownTimer >= beatDuration && _countdownStep <= 4)















        {















            _countdownTimer -= beatDuration;



            int num = _countdownStep switch { 0 => 3, 1 => 2, 2 => 1, 3 => 0, _ => 1 };

            var cd = _countdownStep switch { 0 => Countdown.Three, 1 => Countdown.Two, 2 => Countdown.One, 3 => Countdown.Go, _ => Countdown.Start };

            DispatchCountdownTick(cd, PsychNotes ? _countdownStep : num);
            CallOnLuas("onCountdownTick", PsychNotes ? _countdownStep : num); // PlayState.startCountdown: callOnLuas('onCountdownTick', [swagCounter]) 0..4
            // V-Slice: the Conductor runs during the countdown (songPosition from -5 beats), so beats -4..-1 make every
            // Bopper dance (Bopper.onBeatHit). Offset by -1000 (even) keeps the parity for danceEvery 2 and avoids the
            // characters' initial _lastDanceBeat (-1).
            if (_countdownStep <= 3)
            {
                int cdBeat = _countdownStep - 4 - 1000;
                _boyfriend?.Dance(cdBeat); _opponent?.Dance(cdBeat); _girlfriend?.Dance(cdBeat); DanceAnimatedProps(cdBeat); // stage props are Boppers too (A-Bot plays from frame 1, crowds bop)
            }















            















            switch (_countdownStep)















            {















                case 0:















                    if (!NsCountdownStep(0)) Audio.PlaySound("game/skins/default/countdown/3", 0.6f); // Countdown.hx: note style graphic + sound (PlayScene.NoteStylePopups.cs)















                    break;















                case 1:















                    _countdownText = "READY";















                    _countdownDisplayTimer = beatDuration;















                    if (!NsCountdownStep(1)) Audio.PlaySound("game/skins/default/countdown/2", 0.6f); // Countdown.hx: note style graphic + sound (PlayScene.NoteStylePopups.cs)















                    break;















                case 2:















                    _countdownText = "SET";















                    _countdownDisplayTimer = beatDuration;















                    if (!NsCountdownStep(2)) Audio.PlaySound("game/skins/default/countdown/1", 0.6f); // Countdown.hx: note style graphic + sound (PlayScene.NoteStylePopups.cs)















                    break;















                case 3:















                    _countdownText = "GO!";















                    _countdownDisplayTimer = beatDuration;















                    if (!NsCountdownStep(3)) Audio.PlaySound("game/skins/default/countdown/go", 0.6f); // Countdown.hx: note style graphic + sound (PlayScene.NoteStylePopups.cs)















                    break;















                case 4:















                    StartSong();















                    break;















            }















            _countdownStep++;















        }















    }















    















    /// <summary>















    /// Robustly extract the `char` index from a FocusCamera event value.















    /// Handles bare numbers (long/int/double/JValue/string) and JObjects with a "char" key.















    /// Returns 0 (opponent) if the value cannot be interpreted � but logs the unparseable shape so















    /// chart authoring issues don't silently aim the camera at the wrong character.















    /// </summary>















    private static int ParseFocusChar(object value)















    {















        if (value == null) return 0;















        switch (value)















        {















            case int i: return i;















            case long l: return (int)l;















            case short s: return s;















            case byte b: return b;















            case double d: return (int)d;















            case float f: return (int)f;















            case bool boolean: return boolean ? 1 : 0;















            case string str:















                return int.TryParse(str, out var parsed) ? parsed : 0;















            case Newtonsoft.Json.Linq.JValue jv:















                try { return jv.ToObject<int>(); }















                catch { return 0; }















            case Newtonsoft.Json.Linq.JObject jo:















                var token = jo["char"] ?? jo["c"];















                if (token != null)















                {















                    try { return token.ToObject<int>(); }















                    catch { /* fallthrough */ }















                }















                return 0;















            default:















                Console.WriteLine($"FocusCamera: unrecognized value type {value.GetType().FullName}, defaulting to opponent");















                return 0;















        }















    }































    /// <summary>















    /// Extract Psych Engine event values (value1, value2) from the event Value object.

    /// Psych events store values as string[] {value1, value2} from the chart parser.

    /// Also handles JArray and other formats for robustness.

    /// </summary>

    private static (string val1, string val2) GetPsychEventValues(object value)

    {

        if (value is string[] arr)

            return (arr.Length > 0 ? arr[0] : "", arr.Length > 1 ? arr[1] : "");

        if (value is Newtonsoft.Json.Linq.JArray jarr)

            return (jarr.Count > 0 ? jarr[0]?.ToString() ?? "" : "", jarr.Count > 1 ? jarr[1]?.ToString() ?? "" : "");

        if (value is string s)

            return (s, "");

        return ("", "");

    }



    /// <summary>

    /// Process chart events that have reached their trigger time.















    /// Supports: FocusCamera, ZoomCamera, SetCameraBop, PlayAnimation















    /// </summary>

















    private void ProcessEvents()















    {















        if (_chart.Events == null || _chart.Events.Count == 0) return;
        if (SongEndFrozen) return; // no song events after endSong()















        double songPos = _conductor.SongPosition;















        















        while (_nextEventIndex < _chart.Events.Count)















        {















            var ev = _chart.Events[_nextEventIndex];















            if (ev.Time > songPos) break;















            if (ev.Fired) { _nextEventIndex++; continue; }















            















            ev.Fired = true;
            _nextEventIndex++;
            if (PsychNotes) { ExecuteChartEvent(ev); DispatchEventCalled(ev, null, null); SsfOnSongEvent(ev.Name, ev.Value); continue; } // PlayState.triggerEvent order: built-in switch, stage eventCalled, onEvent (once)
            DispatchEventCalled(ev, null, null); // stage eventCalled + Lua onEvent (was called twice)
            var (v1, v2) = GetPsychEventValues(ev.Value);
            PsychEvents.Trigger(ev.Name, v1, v2, (float)ev.Time, this);
            SsfOnSongEvent(ev.Name, ev.Value);
            ExecuteChartEvent(ev);
            QsOnSongEvent(ev); // QT Rewired sawKB (PlayScene.QtSawblade.cs)
        }
    }

    /// <summary>Built-in event effects (chart events and Lua/HScript triggerEvent, PlayState.triggerEvent switch).</summary>
    internal void ExecuteChartEvent(GameEvent ev)
    {
        {
            switch (ev.Name)















            {















                case "FocusCamera":















                    // Value: { "char": 0=Boyfriend, 1=Dad, 2=Girlfriend } or just a bare int.















                    // Convention matches official FNF V2 FocusCameraSongEvent.hx.















                    // Be permissive about how Newtonsoft.Json surfaces numbers (long/int/double/JValue/string)















                    // because chart files in the wild use all of these forms.















                    int focusChar = CamMovementFocus(ParseFocusChar(ev.Value)); // PSO Camera Movement option
                    string charName = focusChar == 0 ? "boyfriend" : (focusChar == 1 ? "dad" : "gf");
                    if ((!PsychNotes || ev.Time <= 0.0005) && PsychCameraTarget(focusChar) is Microsoft.Xna.Framework.Vector2 psychCamPt) { _camTargetWorldX = psychCamPt.X; _camTargetWorldY = psychCamPt.Y; } // Psych songs: later moves come from sectionHit (every section)
                    if (!PsychNotes) CallOnScripts("onMoveCamera", charName); // Psych songs: moveCameraSection in sectionHit (PlayScene.BaseStage.cs)
                    W6AbotPixelFocus(focusChar); // nene-pixel.hxc onSongEvent(FocusCamera)
                    // nene.hxc onSongEvent(FocusCamera): char 0 -> movePupilsRight, char 1 -> movePupilsLeft
                    if (_girlfriend is Nene && _abotPupilSprite != null && !string.IsNullOrEmpty(_abotPupilAnim))
                    {
                        if (focusChar == 0) _abotPupilSprite.PlayRangeThenPause(_abotPupilAnim, 17, 30);
                        else if (focusChar == 1) _abotPupilSprite.PlayRangeThenPause(_abotPupilAnim, 0, 17);
                    }















                    















                    if (_isPsychEngineStage) { /* camFollow set before onMoveCamera (PlayState.moveCamera order) */ }
                    else if (focusChar == 0)















                    {















                        // Stage JSON cameraOffsets already include directional constants;















                        // only add hardcoded -100/-100 for legacy (non-JSON) stages.















                        float pcx = _boyfriend.CameraOffsets != null && _boyfriend.CameraOffsets.Length >= 2















                            ? _boyfriend.CameraOffsets[0] : 0f;















                        float pcy = _boyfriend.CameraOffsets != null && _boyfriend.CameraOffsets.Length >= 2















                            ? _boyfriend.CameraOffsets[1] : 0f;















                        var bfMid = _boyfriend.GetMidpoint();















                        if (_hasJsonStage)















                        {















                            _camTargetWorldX = bfMid.X + pcx;















                            _camTargetWorldY = bfMid.Y + pcy;















                        }















                        else















                        {















                            _camTargetWorldX = bfMid.X - 100 + pcx;















                            _camTargetWorldY = bfMid.Y - 100 + pcy;















                        }















                    }















                    else if (focusChar == 2 && _girlfriend != null)















                    {















                        // GF: no hardcoded constants in either format















                        float gcx = _girlfriend.CameraOffsets != null && _girlfriend.CameraOffsets.Length >= 2















                            ? _girlfriend.CameraOffsets[0] : 0f;















                        float gcy = _girlfriend.CameraOffsets != null && _girlfriend.CameraOffsets.Length >= 2















                            ? _girlfriend.CameraOffsets[1] : 0f;















                        var gfMid = _girlfriend.GetMidpoint();















                        _camTargetWorldX = gfMid.X + gcx;















                        _camTargetWorldY = gfMid.Y + gcy;















                    }















                    else















                    {















                        // Stage JSON cameraOffsets already include directional constants;















                        // only add hardcoded +150/-100 for legacy (non-JSON) stages.















                        float ocx = _opponent.CameraOffsets != null && _opponent.CameraOffsets.Length >= 2















                            ? _opponent.CameraOffsets[0] : 0f;















                        float ocy = _opponent.CameraOffsets != null && _opponent.CameraOffsets.Length >= 2















                            ? _opponent.CameraOffsets[1] : 0f;















                        var dadMid = _opponent.GetMidpoint();















                        if (_hasJsonStage)















                        {















                            _camTargetWorldX = dadMid.X + ocx;















                            _camTargetWorldY = dadMid.Y + ocy;















                        }















                        else















                        {















                            _camTargetWorldX = dadMid.X + 150 + ocx;















                            _camTargetWorldY = dadMid.Y - 100 + ocy;















                        }















                    }















                    ApplyFocusCameraEventExtras(ev.Value, focusChar); // FocusCameraSongEvent x/y (+ char -1 = static position) + INSTANT/eased modes (PlayScene.CamTween.cs)
                    break;















                    















                case "ZoomCamera":
                    HandleZoomCameraEvent(ev.Value); // ZoomCameraSongEvent
                    break;















                    















                case "SetCameraBop":
                    HandleSetCameraBopEvent(ev.Value); // SetCameraBopSongEvent
                    break;















                    















                case "EnableMask": // tankmanBattlefieldErect.hxc: dad rim shader useAltMask = true
                    _rimDadMaskEnabled = true;
                    break;
                case "PlayAnimation":















                    // Value: { "target": "boyfriend"/"dad"/"gf", "anim": "hey", "force": true }















                    if (ev.Value is Newtonsoft.Json.Linq.JObject animObj)















                    {















                        string target = animObj.Value<string>("target") ?? "";















                        string anim = animObj.Value<string>("anim") ?? "idle";















                        bool force = animObj.Value<bool>("force");















                        Console.WriteLine($"[STREET-DEBUG] PlayAnimation event: target={target} anim={anim} force={force} at t={ev.Time:F2}");















                        if (target == "boyfriend" || target == "bf")















                            _boyfriend.PlayAnimation(anim, force);















                        else if (target == "dad" || target == "opponent")















                            _opponent.PlayAnimation(anim, force);















                        else if (target == "gf" || target == "girlfriend")















                            _girlfriend?.PlayAnimation(anim, force);















                    }















                    break;















                case "SetHealthIcon":







                    // Value: { "char": 0=Boyfriend, 1=Dad, 2=Girlfriend, "id": "tankman-bloody" }







                    if (ev.Value is Newtonsoft.Json.Linq.JObject healthObj)







                    { ApplySetHealthIcon(healthObj);







                        int charIndex = healthObj.Value<int>("char");







                        string iconId = healthObj.Value<string>("id") ?? "";







                        Console.WriteLine($"[STREET-DEBUG] SetHealthIcon event: char={charIndex} id={iconId} at t={ev.Time:F2}");







                        // Update the opponent's bloody state when health icon changes to tankman-bloody







                        if (charIndex == 1 && iconId.Contains("tankman-bloody", StringComparison.OrdinalIgnoreCase) && _opponent != null)







                        {







                            // Original SetHealthIcon only swaps the icon. Tankman already turned bloody when redheadsAnim
                            // played (tankman-bloody.hxc); never restart his current animation here (it replayed
                            // redheadsAnim a second time). SetBloody(true) is a no-op if he is already bloody.
                            _opponent.SetBloody(true);







                        }







                    }







                    break;



                // ========================================

                // Psych Engine Events

                // ========================================



                case "Set Property":
                    {
                        // PlayState.triggerEvent 2272-2296: value1 = property path, value2 = true/false, number or string
                        var (spPath, spVal) = GetPsychEventValues(ev.Value);
                        try
                        {
                            string tv = (spVal ?? "").Trim();
                            object val;
                            if (tv == "true" || tv == "false") val = tv == "true";
                            else if (double.TryParse(spVal, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double spD)) val = spD;
                            else val = spVal ?? "";
                            var spSplit = (spPath ?? "").Split('.');
                            if (spSplit.Length > 1)
                                FNF_MonoGame.Engine.PsychEngine.LuaUtils.SetVarInArray(FNF_MonoGame.Engine.PsychEngine.LuaUtils.GetPropertyLoop(spSplit, true, false), spSplit[^1], val, false);
                            else
                                FNF_MonoGame.Engine.PsychEngine.LuaUtils.SetVarInArray(FNF_MonoGame.Engine.PsychEngine.MusicBeatState.GetTargetInstance(), spPath, val, false);
                        }
                        catch (Exception spEx) { Console.WriteLine($"ERROR (\"Set Property\" Event) - {spEx.Message}"); }
                    }
                    break;
                case "Hey!":

                    {

                        var (val1, val2) = GetPsychEventValues(ev.Value);

                        float heyDuration = 0.6f;

                        if (float.TryParse(val2, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float hd) && hd > 0) heyDuration = hd;



                        int heyTarget = 2; // both

                        switch (val1?.ToLower()?.Trim())

                        {

                            case "bf": case "boyfriend": case "0": heyTarget = 0; break;

                            case "gf": case "girlfriend": case "1": heyTarget = 1; break;

                        }



                        if (heyTarget != 0 && PsychNotes && _opponent != null && (_opponent.OriginalName ?? "").StartsWith("gf")) // Tutorial: dad IS gf
                        { _opponent.PlayAnimation("cheer", true); _opponent.PsychHeyTimer = heyDuration; }
                        else if (heyTarget != 0 && _girlfriend != null)

                            _girlfriend.PlayAnimation("cheer", true); _girlfriend.PsychHeyTimer = heyDuration;

                        if (heyTarget != 1 && _boyfriend != null)

                            _boyfriend.PlayAnimation("hey", true); _boyfriend.PsychHeyTimer = heyDuration;

                    }

                    break;



                case "Set GF Speed":

                    {

                        var (val1, _v2) = GetPsychEventValues(ev.Value);

                        if (double.TryParse(val1, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double gfSpdD) && gfSpdD >= 1)
                            _gfSpeed = (int)Math.Round(gfSpdD, MidpointRounding.AwayFromZero); // Math.round(flValue1), < 1 -> 1
                        else _gfSpeed = 1;
                        PsychApplyGfSpeed();

                    }

                    break;



                case "Add Camera Zoom":

                    {

                        var (val1, val2) = GetPsychEventValues(ev.Value);

                        float camAdd = 0.015f;

                        float hudAdd = 0.03f;

                        if (float.TryParse(val1, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float ca)) camAdd = ca;

                        if (float.TryParse(val2, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float ha)) hudAdd = ha;

                        if (_cameraZoomEnabled && _defaultCamZoom * _cameraBopMultiplier < 1.35f) { _cameraBopMultiplier += _defaultCamZoom > 0f ? camAdd / _defaultCamZoom : camAdd;

                        _hudZoomAdd += hudAdd; } // PlayState.triggerEvent Add Camera Zoom

                    }

                    break;



                case "Play Animation" when ev.Value is string[]:

                    {

                        var (val1, val2) = GetPsychEventValues(ev.Value);

                        if (!string.IsNullOrEmpty(val1))

                        {

                            Character targetChar = _opponent;

                            switch (val2?.ToLower()?.Trim())

                            {

                                case "bf": case "boyfriend": targetChar = _boyfriend; break;

                                case "gf": case "girlfriend": targetChar = _girlfriend; break;

                                default:

                                    if (int.TryParse(val2, out int charIdx))

                                    {

                                        switch (charIdx)

                                        {

                                            case 1: targetChar = _boyfriend; break;

                                            case 2: targetChar = _girlfriend; break;

                                        }

                                    }

                                    break;

                            }

                            if (PsychNotes) targetChar?.PlayAnimationLocked(val1); else targetChar?.PlayAnimation(val1, true); // char.specialAnim = true

                        }

                    }

                    break;



                case "Camera Follow Pos":

                    {

                        var (val1, val2) = GetPsychEventValues(ev.Value);

                        bool hasV1 = float.TryParse(val1, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float cfx);

                        bool hasV2 = float.TryParse(val2, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float cfy);

                        if (hasV1 || hasV2)

                        {

                            _camTargetWorldX = cfx;

                            _camTargetWorldY = cfy;

                            _isCameraOnForcedPos = true;

                        }

                        else

                        {

                            _isCameraOnForcedPos = false;

                        }

                    }

                    break;



                case "Alt Idle Animation":

                    {

                        var (val1, val2) = GetPsychEventValues(ev.Value);

                        // PlayState.triggerEvent 'Alt Idle Animation': char.idleSuffix = value2; recalculateDanceIdle()
                        Character aiChar = _opponent;
                        switch ((val1 ?? "").ToLowerInvariant().Trim())
                        {
                            case "gf": case "girlfriend": aiChar = _girlfriend; break;
                            case "boyfriend": case "bf": aiChar = _boyfriend; break;
                            default: if (int.TryParse(val1, out int aiv)) aiChar = aiv == 1 ? _boyfriend : aiv == 2 ? _girlfriend : _opponent; break;
                        }
                        if (aiChar != null) aiChar.idleSuffix = val2 ?? "";

                    }

                    break;



                case "Screen Shake":

                    {

                        var (val1, val2) = GetPsychEventValues(ev.Value);

                        PsychScreenShake(val1, val2);

                    }

                    break;



                case "Change Scroll Speed":

                    {

                        var (val1, val2) = GetPsychEventValues(ev.Value);

                        if (float.TryParse(val1, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float speedMult))

                        {

                            // PlayState: newValue = SONG.speed * scrollspeed * flValue1; flValue2 > 0 -> linear tween over flValue2 / playbackRate
                            float newSpeed = _chart.Speed * speedMult;
                            double csDur = double.TryParse(val2, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double csd) ? csd : 0;
                            if (PsychNotes && csDur > 0)
                                FNF_MonoGame.Engine.PsychEngine.LuaTweenManager.StartSetterTween("__songSpeedTween", _scrollSpeed > 0 ? _scrollSpeed : _chart.Speed, newSpeed, csDur / Math.Max(0.01f, playbackRate), "linear", v => _scrollSpeed = (float)v);
                            else
                            _scrollSpeed = newSpeed;

                            Console.WriteLine($"[PSYCH-EVENT] Change Scroll Speed: mult={speedMult} new={newSpeed}");

                        }

                    }

                    break;



                case "Change Character":

                    {

                        var (val1, val2) = GetPsychEventValues(ev.Value);

                        PsychChangeCharacter(val1, val2);

                    }

                    break;



                case "Play Sound":

                    {

                        var (val1, val2) = GetPsychEventValues(ev.Value);

                        float psVol = float.TryParse(val2, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var pv) ? pv : 1f; // Psych: flValue2 default 1
                        if (!string.IsNullOrEmpty(val1)) FNFGame.Instance?.Audio?.PlaySound(val1, psVol);

                    }

                    break;



                case "Change BPM":

                    {

                        var (val1, _v2) = GetPsychEventValues(ev.Value);

                        if (float.TryParse(val1, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out float newBpm) && newBpm > 0)

                        {

                            _conductor.ChangeBPM(newBpm);

                            Console.WriteLine($"[PSYCH-EVENT] Change BPM: {newBpm}");

                        }

                    }

                    break;











            }















        }















    }















    















    private void ProcessNoteInput()















    {















        // Apply global offset: positive offset = notes hit later, negative = earlier















        double adjustedPos = _conductor.SongPosition + (_globalOffset / 1000.0); ApplyHitWindowPrefs(); ReplayFrame(adjustedPos);















        bool ghostTapping = s_judgeOverride != null ? s_judgeOverride[5] >= 0.5f : HighscoreManager.Data.GhostTapping;















        















        // Botplay: auto-hit all player notes at exact timing















        _noteField.BotPlay = _botplay;
        if (_botplay)















        {















            for (int lane = 0; lane < 4; lane++)















            {















                for (int __bn = 0; __bn < 32; __bn++) { // hit every due note (a frame hitch can make several due at once)
                var note = _noteField.GetBotplayNote(lane, adjustedPos); if (note != null && Dev2hotSkipBotNote(note)) note = null; // dev hook FNF_SKIP_FIREGUN_AT















                if (note == null) break;















                {















                    OnNoteHit(lane, "SICK!!", 500, note, botplayHit: true);















                    _noteField.RemoveNote(note);















                    if (!Is2hotSpecialNoteKind(note.Kind) && !note.NoAnimation)







                        { if (!SsfNoteHit(lane, note.Kind)) _boyfriend.Sing(lane, note.Kind); }















                    if (note.SustainLength > 0)















                    {















                        _holdingNote[lane] = true;















                        _holdNoteEndTime[lane] = note.Time + note.SustainLength;















                        _holdNoteRef[lane] = note;
                        _holdRemainingMs[lane] = (_holdNoteEndTime[lane] - adjustedPos) * 1000.0;
                        if (DevTapHolds) _botplay = false; // dev: like flipping isBotPlayMode off right after the hit















                    }















                }















                }
                // Hold notes (ported Strumline/PlayState sustain logic, see PlayScene.Holds.cs)
                UpdatePlayerHold(lane, adjustedPos, held: !DevTapHolds, scoring: !_botplay); // hold bonus only if !isBotPlayMode















            }















            return;















        }















        















        for (int lane = 0; lane < 4; lane++)















        {















            if (Input.NoteReleased[lane]) { if (PsychNotes) PsychKeyReleased(lane); else CallOnLuas("onKeyRelease", lane); }

            if (Input.NotePressed[lane])















            {
                bool psKeyStop = false; if (PsychNotes) psKeyStop = _botplay || CallOnScripts("onKeyPressPre", lane) == FNF_MonoGame.Engine.PsychEngine.FunkinLua.Function_Stop; else CallOnLuas("onKeyPress", lane);
                if (!psKeyStop) {















                var note = _noteField.GetHittableNote(lane, ReplayPos(lane, adjustedPos));















                















                if (note != null)















                {















                    float diff = JudgeDiff(note.Time, ReplayPos(lane, adjustedPos)); // Psych ratingOffset + playbackRate (PlayScene.HitWindows.cs)















                    string rating = GetRating(diff); PopupNoteTiming(rating, (note.Time - ReplayPos(lane, adjustedPos) + PrefRatingOffsetS) * 1000.0);















                    int scoreValue = GetScoreValue(diff);















                    















                    OnNoteHit(lane, rating, scoreValue, note);















                    _noteField.RemoveNote(note);















                    if (!Is2hotSpecialNoteKind(note.Kind) && !note.NoAnimation)







                        { if (!SsfNoteHit(lane, note.Kind)) _boyfriend.Sing(lane, note.Kind); }















                    















                    // Start hold tracking if sustain note















                    if (note.SustainLength > 0)















                    {















                        _holdingNote[lane] = true;















                        _holdNoteEndTime[lane] = note.Time + note.SustainLength;















                        _holdNoteRef[lane] = note; // Keep reference to remove when done
                        _holdRemainingMs[lane] = (_holdNoteEndTime[lane] - adjustedPos) * 1000.0;















                    }















                }















                else if (!ghostTapping)















                {















                    // Ghost miss: pressed key with no note nearby















                    // Original: HEALTH_GHOST_MISS_PENALTY = -4.0% of HEALTH_MAX, score -10















                    // Skipped when ghost tapping is enabled















                    OnGhostMiss(lane);
                    if (!PsychNotes) { CallOnLuas("noteMissPress", lane); } // Psych: OnGhostMiss -> noteMissPress (PlayScene.PsychScriptApi.cs)















                }
                else if (PsychNotes) CallOnScripts("onGhostTap", lane); // keyPressed: ghostTapping on -> onGhostTap(key)















                } if (PsychNotes && !psKeyStop) CallOnScripts("onKeyPress", lane); // keyPressed end
            }















            















            // Hold notes (ported Strumline/PlayState sustain logic, see PlayScene.Holds.cs)
            UpdatePlayerHold(lane, ReplayRelPos(lane, adjustedPos), held: Input.NoteHeld[lane], scoring: true);















        }















    }















    















    private string GetRating(float timeDiff)















    {















        // PBOT1 judgement thresholds (original FNF)















        if (timeDiff <= NoteField.KILLER_WINDOW) return "SICK!!"; // killer threshold gives sick display















        if (timeDiff <= PrefSickS) return "SICK!!";















        if (timeDiff <= PrefGoodS) return "GOOD!";















        if (timeDiff <= PrefBadS) return "BAD";















        return "SHIT";















    }















    















    /// <summary>















    /// PBOT1 sigmoid scoring from original FNF.















    /// Max score = 500, offset = 54.99ms, slope = 0.080, min = 9















    /// Perfect threshold (&lt;5ms) always gives max score.















    /// </summary>















    private int GetScoreValue(float absTiming)















    {















        const float MAX_SCORE = 500f;















        const float SCORING_OFFSET = 54.99f;















        const float SCORING_SLOPE = 0.080f;















        const float MIN_SCORE = 9.0f;















        const float PERFECT_THRESHOLD = 0.005f; // 5ms















        const float MISS_THRESHOLD = 0.160f;















        const int MISS_SCORE = -100;















        















        if (absTiming > MISS_THRESHOLD) return MISS_SCORE;



        // Psych Engine: use fixed scores from Rating.hx when playing mod charts

        if (!string.IsNullOrEmpty(_modPath))

        {

            float psychMs = absTiming * 1000f;

            if (psychMs <= PrefSickS * 1000f) return 350;  // sick

            if (psychMs <= PrefGoodS * 1000f) return 200;  // good

            if (psychMs <= PrefBadS * 1000f) return 100; // bad

            return 50;                      // shit

        }











        if (absTiming < PERFECT_THRESHOLD) return (int)MAX_SCORE;















        















        float absMs = absTiming * 1000f;















        float factor = 1.0f - (1.0f / (1.0f + (float)Math.Exp(-SCORING_SLOPE * (absMs - SCORING_OFFSET))));















        return (int)(MAX_SCORE * factor + MIN_SCORE);















    }















    















    private bool Is2hotSpecialNoteKind(string noteKind)







    {







        if (string.IsNullOrEmpty(noteKind)) return false;







        return noteKind.Equals("weekend-1-cockgun", StringComparison.OrdinalIgnoreCase)







            || noteKind.Equals("weekend-1-firegun", StringComparison.OrdinalIgnoreCase)







            || noteKind.Equals("weekend-1-firegun-hip", StringComparison.OrdinalIgnoreCase)







            || noteKind.Equals("weekend-1-firegun-far", StringComparison.OrdinalIgnoreCase);







    }















    private bool Is2hotDarnellNoteKind(string noteKind)







    {







        if (string.IsNullOrEmpty(noteKind)) return false;







        return noteKind.Equals("weekend-1-lightcan", StringComparison.OrdinalIgnoreCase)







            || noteKind.Equals("weekend-1-kickcan", StringComparison.OrdinalIgnoreCase)







            || noteKind.Equals("weekend-1-kneecan", StringComparison.OrdinalIgnoreCase);







    }















    private void OnNoteHit(int lane, string rating, int scoreValue, Note note, bool botplayHit = false)















    { if (PsychHitCausesMiss(lane, note)) return; MpHookP1Hit(lane, rating, botplayHit); EngineHitsound(botplayHit); PsoHookHit(note != null ? note.Time : -1, lane, note != null ? note.SustainLength : 0, rating, scoreValue, botplayHit);















        string noteKind = note?.Kind ?? "";







        // 2hot firegun: cannot hit unless the gun was cocked first. Treat as a miss.







        if (Is2hotSpecialNoteKind(noteKind)







            && noteKind.StartsWith("weekend-1-firegun", StringComparison.OrdinalIgnoreCase)







            && !_2hotGunCocked)







        {







            OnNoteMiss(lane, noteKind, note);
            // (removed duplicate Lua callback; fired once by the matching Dispatch*() above — Psych calls each callback once)







            return;







        }















        _bzLastRating = rating; _psBotHit = botplayHit; DispatchGoodNoteHit(note); if (botplayHit) { PsychBotplayHitHealth(note); if (PsychNotes) { PsychSpawnSplash(lane, note); _combo = Math.Min(_combo + 1, 9999); PsyPopUpScore(rating, _combo); } /* Psych cpuControlled still runs popUpScore -> sick splash */ } PsychStartSustainTrack(note, true);
        // Botplay (PlayState.processNotes r.botplayHit): only the HitNoteScriptEvent + playerStrumline.hitNote(note) -
        // goodNoteHit is NOT called: no score/combo/tallies/health/vocals, no note splash and no rating/combo popups.
        if (!botplayHit) {
        // (removed duplicate Lua callback; fired once by the matching Dispatch*() above — Psych calls each callback once)



        _score += scoreValue; PsychScoreBop();
        CallOnLuas("onUpdateScore", false);















        PopupPushStack(); _lastRating = rating;















        _ratingTimer = 0.5f;















        _totalNotesHit++;















        _totalNotes++;















        _npsCounter++;















        















        // Combo break on BAD and SHIT (original Constants: JUDGEMENT_BAD_COMBO_BREAK = true, JUDGEMENT_SHIT_COMBO_BREAK = true)















        GfComboOnHit(rating, _combo + 1);   // BaseCharacter.onNoteHit GF branch (PlayScene.GfCombo.cs)
        bool isComboBreak = !PsychNotes && (rating == "BAD" || rating == "SHIT"); // Psych: hits never break the combo















        if (isComboBreak)















        {















            NsComboBreak(_combo); _combo = 0;















        }















        else















        {















            _combo++; if (PsychNotes && _combo > 9999) _combo = 9999; // Psych goodNoteHit cap















            _maxCombo = Math.Max(_maxCombo, _combo);















        }















        















        // Track tallies (matches original FNF Highscore.tallies)















        switch (rating)















        {















            case "SICK!!":















                _tallySick++;















                break;















            case "GOOD!":















                _tallyGood++;















                break;















            case "BAD":















                _tallyBad++;















                break;















            case "SHIT":















                _tallyShit++;















                break;















        }















        















        // Health bonuses

        // Psych Engine: fixed hitHealth=0.023 per note * healthGain (default 1.0)

        // Original FNF: percentage of HEALTH_MAX=2.0















        float healthChange = !string.IsNullOrEmpty(_modPath) ? (note?.HitHealth ?? 0.02f) * PsychHealthGain : rating switch















        {















            "SICK!!" => 1.5f / 100f * HEALTH_MAX,   // +1.5%















            "GOOD!" => 0.75f / 100f * HEALTH_MAX,   // +0.75%















            "BAD" => 0f,                             // +0.0%















            "SHIT" => -1.0f / 100f * HEALTH_MAX,    // -1.0%















            _ => 0f















        };















        _health = Math.Clamp(_health + healthChange, HEALTH_MIN, HEALTH_MAX);















        















        // Restore player vocals on hit (original: vocals.playerVolume = playerVocalsVolume)















        Audio.SetPlayerVoiceVolume(1.0f);















        















        // Note splash on sick hit (original: playerStrumline.playNoteSplash)















        if (rating == "SICK!!" && !(PsychNotes && note != null && note.NoteSplashDisabled)) // Psych noteSplashData.disabled















        {















            _noteSplashTimer[lane] = 0.3f; _psychSplashAlpha[lane] = PsychNotes && note != null ? note.NoteSplashAlpha : 1f; PsychSpawnSplash(lane, note);















            _noteSplashLane[lane] = lane;















        }















        















        } // !botplayHit
        // Receptor confirm flash (original: playerStrumline.playConfirm on note hit)















        _playerConfirmTimer[lane] = RECEPTOR_CONFIRM_DURATION; VsStrumHit(true, lane, note);
        if (!botplayHit) {















        















        // Rating popup physics (original PopUpStuff: y = camera.height * 0.45 - 60)















        _ratingY = FNFGame.SCREEN_HEIGHT * 0.45f - 60;















        _ratingVelY = -_random.Next(140, 176); // velocity.y -= FlxG.random.int(140, 175)















        _ratingAlpha = 1f;















        _lastComboDisplay = _combo; NsPopUpScore(_lastRating, _combo); // PopUpStuff via note style (V-Slice)
        if (PsychNotes) PsyPopUpScore(_lastRating, _combo); // Psych PlayState.popUpScore (PlayScene.PsychPopups.cs)















        















        // Combo digit physics















        _comboY = FNFGame.SCREEN_HEIGHT * 0.44f;















        _comboVelY = -_random.Next(140, 171);















        _comboAlpha = 1f;















        _comboTimer = 0;















        } // !botplayHit
        // 2hot (Too Hot): player side spraycan/gun mechanics







        if (Is2hotSpecialNoteKind(noteKind))







        {







            switch (noteKind.ToLowerInvariant())







            {







                case "weekend-1-cockgun":







                    _2hotGunCocked = true;







                    _2hotGunCockedTimer = 1.0f;







                    _boyfriend.PlayAnimationLocked("cock"); // pico-playable.hxc playAnimation('cock', true, true)







                    Audio.PlaySound("sounds/weekend1/Gun_Prep");







                    break;















                case "weekend-1-firegun":







                case "weekend-1-firegun-hip":







                case "weekend-1-firegun-far":







                    if (_2hotGunCocked)







                    {







                        _2hotGunCocked = false;







                        _boyfriend.PlayAnimationLocked("shoot");







                        ShootNext2hotCan();







                        Audio.PlaySound($"sounds/weekend1/shot{_random.Next(1, 5)}");







                    }







                    break;







            }







        }















    }















    















    private void OnNoteMiss(int lane = -1, string noteKind = "", Note note = null)















    { MpHookP1Miss(lane); PsoHookMiss(lane, note != null ? note.Time : -1);
        Input.Rumble(0.3f, 0.09f);   // Options > Controller Vibration















        if (note != null)

        {

            noteKind = note.Kind;

            DispatchNoteMiss(note);

        }

        else if (lane >= 0)

        {

            DispatchNoteMissPress(lane);

        }



        if (note != null) GfComboOnBreak(_combo); NsComboBreak(_combo); _combo = 0;















        _misses++; if (DevMissLog) Console.WriteLine($"[MISS] t={SongPositionSeconds:F3} lane={lane} kind={noteKind} type={note?.NoteType} noteT={note?.Time:F3} health={_health:F4}");















        _tallyMissed++;















        _totalNotes++;















        _score += !string.IsNullOrEmpty(_modPath) ? -10 : -100; // Psych: -10, PBOT1: -100
        CallOnLuas("onUpdateScore", true);















        // Health penalty: Psych Engine: missHealth=0.1, Original FNF: -4.0% of HEALTH_MAX















        float missDamage = !string.IsNullOrEmpty(_modPath) ? (note != null ? note.MissHealth : 0.05f) * PsychHealthLoss : (4.0f / 100f * HEALTH_MAX); // Psych noteMissCommon: note.missHealth / pressMissDamage

        _health = Math.Clamp(_health - missDamage, HEALTH_MIN, HEALTH_MAX);















        PopupPushStack(); _lastRating = "MISS";















        _ratingTimer = 0.3f;















        _ratingY = FNFGame.SCREEN_HEIGHT * 0.45f - 60;















        _ratingVelY = -_random.Next(140, 176);















        _ratingAlpha = 1f;















        _lastComboDisplay = 0;















        















        // Mute player vocals on miss (original: vocals.playerVolume = 0)















        Audio.SetPlayerVoiceVolume(0f);















        















        // Play miss animation on BF















        if (lane >= 0)







        {







            // 2hot firegun miss: Pico is hit by the exploding can (burned face animation)







            if (Is2hotSpecialNoteKind(noteKind))







            {







                switch (noteKind.ToLowerInvariant())







                {







                    case "weekend-1-cockgun":







                        // No special miss animation; just cancel the health penalty below.







                        break;







                    case "weekend-1-firegun":







                    case "weekend-1-firegun-hip":







                    case "weekend-1-firegun-far":







                        _boyfriend.PlayAnimationLocked("shootMISS");







                        Audio.PlaySound("sounds/weekend1/Pico_Bonk");







                        break;







                }







            }







            else







            {







                if (!SsfNoteMiss(lane, noteKind)) _boyfriend.Miss(lane);







            }







        }















        // 2hot (Too Hot): cancel the default miss health penalty and apply can damage instead.







        if (Is2hotSpecialNoteKind(noteKind))







        {







            // Refund the standard miss penalty we already applied.







            _health = Math.Clamp(_health + (4.0f / 100f * HEALTH_MAX), HEALTH_MIN, HEALTH_MAX);















            switch (noteKind.ToLowerInvariant())







            {







                case "weekend-1-firegun":







                case "weekend-1-firegun-hip":







                case "weekend-1-firegun-far":







                    _2hotGunCocked = false;







                    MissNext2hotCan();







                    Take2hotCanDamage();







                    break;







            }







        }















        















        // Play random miss sound (FNF has 3 miss sounds)















        int missNum = _random.Next(1, 4);















        Audio.PlaySound($"missnote{missNum}", 0.3f);















    }















    















    private SpriteSheet _2hotExplosionSheet;
    private SpriteSheet _2hotCanSheet; // cached: loaded once per song, like FunkinMemory.cacheTexture(spraycanAtlas)
    private StaticStageProp? Find2hotSpraycanPile()







    {







        for (int i = 0; i < _staticProps.Count; i++)







        {







            if (string.Equals(_staticProps[i].Name, "spraycanPile", StringComparison.OrdinalIgnoreCase))







                return _staticProps[i];







        }







        return null;







    }















    private void Spawn2hotCan()







    {







        var pile = Find2hotSpraycanPile();







        if (pile == null) return;















        var sheet = _2hotCanSheet ??= SpriteSheet.Load(Game, "images/weekend1/spraycanAtlas", preRenderComposites: true);







        if (sheet == null)







        {







            Console.WriteLine("[2HOT] Failed to load spraycanAtlas");







            return;







        }















        // SpraycanAtlasSprite = FunkinSprite.loadTextureAtlas("spraycanAtlas"): the timeline box is drawn at (x, y).
        var sprite = new AnimatedSprite { Sheet = sheet, UseTimelineAnchoring = true };







        sprite.Position = new Vector2(pile.X + 30f, pile.Y - 840f);







        sprite.Scale = new Vector2(1f, 1f);







        sprite.PlayAnimation("Can Start", loop: false);
        Console.WriteLine($"[2HOT] can spawned at song={SongPositionSeconds:F2}s pos={sprite.Position} tl={sheet.GetTimelineBounds(sprite.ResolvedAnimName)} anims=[{string.Join(",", sheet.Animations.Keys)}]");















        int canIndex = _2hotSpawnedCans.Count;







        var prop = new AnimatedStageProp







        {







            Sprite = sprite,







            ZIndex = pile.ZIndex - 1,







            Alpha = 1f,







            ScrollX = 1f,







            ScrollY = 1f,







            Name = "2hotCan"







        };







        _2hotSpawnedCans.Add(prop);







        _2hotCanStates.Add(CAN_STATE_ARCING);







        _animatedProps.Add(prop);







        _animatedProps = _animatedProps.OrderBy(p => p.ZIndex).ToList();















        int idx = canIndex;







        sprite.OnFinish = () => On2hotCanStartFinished(idx);







    }















    private void On2hotCanStartFinished(int canIndex)







    {







        if (canIndex < 0 || canIndex >= _2hotCanStates.Count) return;







        if (_2hotCanStates[canIndex] == CAN_STATE_DEAD) return;















        // SpraycanAtlasSprite.finishCanAnimation(\'Can Start\') -> playHitPico(); currentState is NOT changed (still ARCING, can still be shot)







        var sprite = _2hotSpawnedCans[canIndex].Sprite;







        if (sprite != null)







        {







            sprite.PlayAnimation("Hit Pico", loop: false);







            int idx = canIndex;







            sprite.OnFinish = () => On2hotCanHitPicoFinished(idx);







        }







    }















    private void On2hotCanHitPicoFinished(int canIndex)







    {







        if (canIndex < 0 || canIndex >= _2hotCanStates.Count) return;







        Spawn2hotCanImpactParticle(_2hotSpawnedCans[canIndex].Sprite?.Position ?? Vector2.Zero);







        Kill2hotCan(canIndex);







    }















    private void On2hotCanShotFinished(int canIndex)







    {







        if (canIndex < 0 || canIndex >= _2hotCanStates.Count) return;







        Kill2hotCan(canIndex);







    }















    private void Kill2hotCan(int canIndex)







    {







        if (canIndex < 0 || canIndex >= _2hotCanStates.Count) return;







        if (_2hotCanStates[canIndex] == CAN_STATE_DEAD) return;















        var prop = _2hotSpawnedCans[canIndex];







        _2hotCanStates[canIndex] = CAN_STATE_DEAD;







        _animatedProps.RemoveAll(p => p.Sprite == prop.Sprite);







    }















    private void ShootNext2hotCan()







    {







        for (int i = 0; i < _2hotCanStates.Count; i++)







        {







            if (_2hotCanStates[i] == CAN_STATE_ARCING)







            {







                _2hotCanStates[i] = CAN_STATE_SHOT;
                Start2hotDarken(); // 2hot.hxc shootNextCan: darkenStageProps() after 1/24 s (PlayScene.TwoHot.cs)







                var sprite = _2hotSpawnedCans[i].Sprite;







                if (sprite != null)







                {







                    sprite.PlayAnimation("Can Shot", loop: false);







                    int idx = i;







                    sprite.OnFinish = () => On2hotCanShotFinished(idx);







                }







                // TODO: darken stage props, haptic, impact particle







                return;







            }







        }







    }















    private void MissNext2hotCan()







    {







        for (int i = 0; i < _2hotCanStates.Count; i++)







        {







            if (_2hotCanStates[i] == CAN_STATE_ARCING)







            {







                _2hotCanStates[i] = CAN_STATE_IMPACTED; // 2hot.hxc missNextCan(): only the state changes; the can keeps playing Can Start -> Hit Pico







                return;







            }







        }







    }















    private void Take2hotCanDamage()







    {







        const float HEALTH_LOSS = 0.25f * 2.0f; // matches original 2hot.hxc







        _health = Math.Clamp(_health - HEALTH_LOSS, HEALTH_MIN, HEALTH_MAX);















        if (_health <= HEALTH_MIN)







        {







            _2hotPicoExplodeDeath = true;







        }







    }















    private void Spawn2hotCanImpactParticle(Vector2 position)







    {







        var sheet = _2hotExplosionSheet ??= SpriteSheet.Load(Game, "images/weekend1/spraypaintExplosionEZ"); // cached (2hot.hxc precaches)







        if (sheet == null) return;















        var sprite = new AnimatedSprite { Sheet = sheet };







        // Original offset: x + 1050, y + 150 relative to can position.







        sprite.Position = new Vector2(position.X + 1050f, position.Y + 150f);







        sprite.Scale = new Vector2(1f, 1f);







        sprite.PlayAnimation("explosion round 1 short", loop: false);















        var prop = new AnimatedStageProp







        {







            Sprite = sprite,







            ZIndex = 450, // above characters







            Alpha = 1f,







            ScrollX = 1f,







            ScrollY = 1f,







            Name = "2hotCanExplosion"







        };







        _animatedProps.Add(prop);







        _animatedProps = _animatedProps.OrderBy(p => p.ZIndex).ToList();















        sprite.OnFinish = () => _animatedProps.RemoveAll(p => p.Sprite == sprite);







    }















    















    /// <summary>















    /// Ghost miss: player pressed a key when no note was nearby.















    /// Original: ghostNoteMiss() with HEALTH_GHOST_MISS_PENALTY and -10 score.















    /// </summary>















    private void OnGhostMiss(int lane)
    { if (PsychNotes) { PsychNoteMissPress(lane); return; } OnGhostMissVSlice(lane); }
    private void OnGhostMissVSlice(int lane)















    {
        BlazinGhostMiss();















        // Original: HEALTH_GHOST_MISS_PENALTY = -4.0% of HEALTH_MAX, scoreChange = -10















        _health = Math.Clamp(_health - (4.0f / 100f * HEALTH_MAX), HEALTH_MIN, HEALTH_MAX);















        _score -= 10;
        CallOnLuas("onUpdateScore", true);















        















        // Play miss sound at lower volume (original: FlxG.random.float(0.1, 0.2))















        int missNum = _random.Next(1, 4);















        Audio.PlaySound($"missnote{missNum}", 0.15f);















        















        // Play miss animation















        if (!SsfNoteMiss(lane, null)) _boyfriend.Miss(lane);















    }















    















    public override void Draw(SpriteBatch spriteBatch)















    {















        // Loading screen















        if (_playLoading)















        {















            spriteBatch.Begin(samplerState: SamplerState.PointClamp, blendState: BlendState.NonPremultiplied);















            spriteBatch.Draw(Assets.Pixel, new Rectangle(0, 0, FNFGame.SCREEN_WIDTH, FNFGame.SCREEN_HEIGHT), new Color(10, 10, 20));















            int dots = ((int)(_playLoadDotTimer * 3f)) % 4;















            string dotStr = new string('.', dots);















            string statusText = _playLoadStatus + dotStr;















            var font = Assets.GetFont(24);















            if (font != null)















            {















                float tw = font.MeasureString("LOADING").X;















                font.DrawText(spriteBatch, "LOADING", new Vector2((FNFGame.SCREEN_WIDTH - tw) / 2, FNFGame.SCREEN_HEIGHT / 2 - 40), Color.White);















                float sw = font.MeasureString(statusText).X;















                font.DrawText(spriteBatch, statusText, new Vector2((FNFGame.SCREEN_WIDTH - sw) / 2, FNFGame.SCREEN_HEIGHT / 2 + 10), Color.Gray);















            }















            float progress = Math.Clamp((float)_playLoadPhase / 6f, 0f, 1f);















            int barW = 400, barH = 8;















            int barX = (FNFGame.SCREEN_WIDTH - barW) / 2;















            int barY = FNFGame.SCREEN_HEIGHT / 2 + 60;















            spriteBatch.Draw(Assets.Pixel, new Rectangle(barX, barY, barW, barH), new Color(40, 40, 60));















            spriteBatch.Draw(Assets.Pixel, new Rectangle(barX, barY, (int)(barW * progress), barH), new Color(100, 200, 255));















            spriteBatch.End();















            return;















        }































        // During game over, only draw the game over overlay (original: separate substate)















        if (_gameOver && _goPreDelay < 0f) { DrawGameOverV(spriteBatch); return; } // GameOverSubState (PlayScene.GameOver.cs)















        















        // === WORLD PASS: stage + characters with camera zoom ===















        float zoom = _defaultCamZoom * _cameraBopMultiplier;















        // HaxeFlixel camera: zoom scales from origin (0,0), NOT from screen center.















        // WorldToScreen computes pre-zoom positions where (0,0) = top-left of camera view.















        // The zoom matrix multiplies these positions by the zoom factor from origin.















        _worldZoomMatrix = Matrix.CreateScale(zoom, zoom, 1f) * Matrix.CreateTranslation(_bzShakeOffset.X, _bzShakeOffset.Y, 0f) * PsychGameCamMatrix;
        BeginRainWorldPass(); // phillyStreets: world -> offscreen target, composited through rain below
        if (Environment.GetEnvironmentVariable("FNF_CAMLOG") == "1" && (DateTime.Now - _dbgCamLogT).TotalSeconds >= 1)
        {
            _dbgCamLogT = DateTime.Now;
            var bb = Game.GraphicsDevice.PresentationParameters;
            Console.WriteLine($"[CAMLOG] zoom={zoom:F3} default={_defaultCamZoom:F3} bop={_cameraBopMultiplier:F3} cam=({_camWorldX:F1},{_camWorldY:F1}) target=({_camTargetWorldX:F1},{_camTargetWorldY:F1}) backbuffer={bb.BackBufferWidth}x{bb.BackBufferHeight} " +
                $"bf={_boyfriend?.Position} dad={_opponent?.Position} gf={_girlfriend?.Position}");
        }















        // Clip world rendering to screen bounds (original FNF: FlxCamera viewport clips)















        var prevScissor = Game.GraphicsDevice.ScissorRectangle;















        Game.GraphicsDevice.ScissorRectangle = new Rectangle(0, 0, FNFGame.SCREEN_WIDTH, FNFGame.SCREEN_HEIGHT);















        _worldClipRaster ??= new RasterizerState { ScissorTestEnable = true, CullMode = CullMode.None }; // flixel never culls: mirrored atlas parts (negative-determinant matrices) must draw















        _worldSampler = W6PixelWorld ? SamplerState.PointClamp : SamplerState.LinearClamp; // week 6: every prop/character isPixel (antialiasing = false)















        _worldBlendState = BlendState.NonPremultiplied;















        spriteBatch.Begin(samplerState: _worldSampler, blendState: _worldBlendState, transformMatrix: _worldZoomMatrix, rasterizerState: _worldClipRaster);















        















        // Draw stage background (offset by camera)















        { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawStage(spriteBatch); FNF_MonoGame.Engine.PerfStats.End(2, __pf); }















        















        // Z-ordered rendering: interleave props and characters by their zIndex















        // Characters: GF=_gfZIndex(100), Dad=_dadZIndex(200), BF=_bfZIndex(300)















        // Props can be at any zIndex (e.g., limoDrive=150 between GF and Dad)















        if (_hasJsonStage)















        {















            // Collect all z-index thresholds where we need to draw characters















            // Draw order: props < gfZ, GF, props < dadZ, Dad, props < bfZ, BF, remaining props















            int[] charZList = { _gfZIndex, _dadZIndex, _bfZIndex };
            int[] charOrder = BzCharDrawOrder(charZList);















            















            int lastZ = int.MinValue;















            for (int oi = 0; oi < 3; oi++)















            {















                int ci = charOrder[oi];
                int charZ = charZList[ci];















                















                if (ci == 0)







                {







                    // Original FNF: TankmanSpriteGroup.zIndex = 30. The army must render ABOVE







                    // the background props (bg z=10, sniper/guy z=20) but BEHIND the A-Bot







                    // (abotZ = gfZIndex-10 ~= 90) and the GF. Insert the army at z=30 by







                    // splitting the prop range, otherwise it paints on top of the A-Bot.







                    const int armyZ = 30;







                    { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawPropsInRange(spriteBatch, lastZ, Math.Max(lastZ, armyZ)); FNF_MonoGame.Engine.PerfStats.End(3, __pf); }







                    DrawStressTankmen(spriteBatch);







                    { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawPropsInRange(spriteBatch, Math.Max(lastZ, armyZ), charZ); FNF_MonoGame.Engine.PerfStats.End(3, __pf); }







                }







                else







                {







                    // Draw all props with zIndex >= lastZ and < charZ







                    { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawPropsInRange(spriteBatch, lastZ, charZ); FNF_MonoGame.Engine.PerfStats.End(3, __pf); }







                }















                















                // Draw the character















                switch (ci)















                {















                    case 0: // GF















                        if (_girlfriend != null)















                        {















                            var gfScreen = WorldToScreen(_girlfriend.Position.X, _girlfriend.Position.Y, _gfCharScroll.X, _gfCharScroll.Y);















                            { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawStageCharacter(spriteBatch, 2, _girlfriend, gfScreen); FNF_MonoGame.Engine.PerfStats.End(4, __pf); }















                        }















                        break;















                    case 1: // Dad















                    {















                        var oppScreen = WorldToScreen(_opponent.Position.X, _opponent.Position.Y, _dadCharScroll.X, _dadCharScroll.Y);















                        if (_mpPso) PsoDrawExtraChars(spriteBatch, false); { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawStageCharacter(spriteBatch, 1, _opponent, oppScreen); FNF_MonoGame.Engine.PerfStats.End(4, __pf); }















                        break;















                    }















                    case 2: // BF















                    {















                        var bfScreen = WorldToScreen(_boyfriend.Position.X, _boyfriend.Position.Y, _bfCharScroll.X, _bfCharScroll.Y);















                        if (_mpPso) PsoDrawExtraChars(spriteBatch, true); { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawStageCharacter(spriteBatch, 0, _boyfriend, bfScreen); FNF_MonoGame.Engine.PerfStats.End(4, __pf); } if (_mpPso) PsoDrawNameplates(spriteBatch);















                        break;















                    }















                }















                















                lastZ = charZ;















            }















            















            // Draw remaining props with zIndex >= BF's zIndex















            { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawPropsInRange(spriteBatch, lastZ, int.MaxValue); FNF_MonoGame.Engine.PerfStats.End(3, __pf); }















        }















        else















        {















            // Legacy (non-JSON) stages: simple ordering















            if (_girlfriend != null)















            {















                var gfScreen = WorldToScreen(_girlfriend.Position.X, _girlfriend.Position.Y, _gfCharScroll.X, _gfCharScroll.Y);















                { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawStageCharacter(spriteBatch, 2, _girlfriend, gfScreen); FNF_MonoGame.Engine.PerfStats.End(4, __pf); }















            }















            {















                var oppScreen = WorldToScreen(_opponent.Position.X, _opponent.Position.Y, _dadCharScroll.X, _dadCharScroll.Y);















                if (_mpPso) PsoDrawExtraChars(spriteBatch, false); { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawStageCharacter(spriteBatch, 1, _opponent, oppScreen); FNF_MonoGame.Engine.PerfStats.End(4, __pf); }















            }















            {















                var bfScreen = WorldToScreen(_boyfriend.Position.X, _boyfriend.Position.Y, _bfCharScroll.X, _bfCharScroll.Y);















                if (_mpPso) PsoDrawExtraChars(spriteBatch, true); { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawStageCharacter(spriteBatch, 0, _boyfriend, bfScreen); FNF_MonoGame.Engine.PerfStats.End(4, __pf); } if (_mpPso) PsoDrawNameplates(spriteBatch);















            }















        }















        















        // Draw stage curtains on top of characters (legacy stages only)















        if (!_hasJsonStage)















            DrawStageCurtains(spriteBatch);















        















        // Spooky lightning flash overlay (white screen flash that fades out)















        if (_lightningFlashAlpha > 0)















        {















            float flashZoom = _defaultCamZoom * _cameraBopMultiplier;















            int fillW = (int)(FNFGame.SCREEN_WIDTH / flashZoom) + 2;















            int fillH = (int)(FNFGame.SCREEN_HEIGHT / flashZoom) + 2;















            spriteBatch.Draw(Assets.Pixel,















                new Rectangle(0, 0, fillW, fillH),















                Color.White * (_lightningFlashAlpha * 0.6f));















        }































        // DEBUG: Show position info for all characters















        var fontDbg = Assets.GetFont(14);















        if (false)















        {















            void DrawCharDbg(Character ch, string label, Color color, int idx)















            {















                if (ch == null) return;















                var origin = ch.GetCharacterOrigin();















                var corner = ch.CornerPosition;















                var off = ch.CharOffsets;















                var offStr = off?.Length >= 2 ? $"[{off[0]},{off[1]}]" : "[0,0]";















                var anim = ch.CurrentAnimation ?? "null";















                















                // Crosshair at CornerPosition (actual sprite draw corner, matching HaxeFlixel this.x/y)







                var screenPos = WorldToScreen(corner.X, corner.Y);















                float x = screenPos.X + 10;















                float y = screenPos.Y - 90;















                















                bool selected = _posDebugMode && _posDebugSelected == idx;















                Color drawColor = selected ? Color.White : color;















                















                fontDbg.DrawText(spriteBatch, $"{label}{(selected ? " [SEL]" : "")}", new Vector2(x, y), drawColor);















                fontDbg.DrawText(spriteBatch, $"Pos: ({ch.Position.X:F1},{ch.Position.Y:F1})", new Vector2(x, y + 16), drawColor);















                fontDbg.DrawText(spriteBatch, $"Corner: ({corner.X:F1},{corner.Y:F1})", new Vector2(x, y + 32), drawColor);















                fontDbg.DrawText(spriteBatch, $"Origin: ({origin.X:F1},{origin.Y:F1})", new Vector2(x, y + 48), drawColor);















                fontDbg.DrawText(spriteBatch, $"Off: {offStr} Anim: {anim} F:{ch.SpriteFrameIndex}/{ch.SpriteFrameCount}", new Vector2(x, y + 64), drawColor);















                if (_posDebugMode && _posDebugNudge[idx] != Vector2.Zero)















                    fontDbg.DrawText(spriteBatch, $"Nudge: ({_posDebugNudge[idx].X:F1},{_posDebugNudge[idx].Y:F1})", new Vector2(x, y + 80), Color.Lime);















                















                // Draw crosshair at visual position















                spriteBatch.Draw(Assets.Pixel, new Rectangle((int)screenPos.X - 2, (int)screenPos.Y - 8, 4, 16), drawColor);















                spriteBatch.Draw(Assets.Pixel, new Rectangle((int)screenPos.X - 8, (int)screenPos.Y - 2, 16, 4), drawColor);















            }















            















            DrawCharDbg(_boyfriend, "BF (Pico)", Color.Cyan, 0);















            DrawCharDbg(_opponent, "DAD (Parents)", Color.Magenta, 1);















            DrawCharDbg(_girlfriend, "GF (Nene)", Color.Yellow, 2);















            















            // ABot debug info















            if (_hasAbotFallback)















            {















                var abotBase = new Vector2(







                    (_girlfriend?.Position.X ?? 0f) + _abotBodyOffsetX,







                    (_girlfriend?.Position.Y ?? 0f) + _abotBodyOffsetY);















                var abotScreen = WorldToScreen(abotBase.X, abotBase.Y);















                bool abotSel = _posDebugMode && _posDebugSelected == 3;















                Color abotColor = abotSel ? Color.White : Color.Orange;















                fontDbg.DrawText(spriteBatch, $"ABot{(abotSel ? " [SEL]" : "")}", new Vector2(abotScreen.X + 10, abotScreen.Y - 90), abotColor);















                fontDbg.DrawText(spriteBatch, $"Base: ({abotBase.X:F1},{abotBase.Y:F1})", new Vector2(abotScreen.X + 10, abotScreen.Y - 74), abotColor);















                fontDbg.DrawText(spriteBatch, $"Off: ({_abotBodyOffsetX:F1},{_abotBodyOffsetY:F1})", new Vector2(abotScreen.X + 10, abotScreen.Y - 58), abotColor);















                if (_posDebugMode && _posDebugNudge[3] != Vector2.Zero)















                    fontDbg.DrawText(spriteBatch, $"Nudge: ({_posDebugNudge[3].X:F1},{_posDebugNudge[3].Y:F1})", new Vector2(abotScreen.X + 10, abotScreen.Y - 42), Color.Lime);















                spriteBatch.Draw(Assets.Pixel, new Rectangle((int)abotScreen.X - 2, (int)abotScreen.Y - 8, 4, 16), abotColor);















                spriteBatch.Draw(Assets.Pixel, new Rectangle((int)abotScreen.X - 8, (int)abotScreen.Y - 2, 16, 4), abotColor);















            }















            















            // A-Bot condition diagnostic (always visible)







            if (false)







            {







                fontDbg.DrawText(spriteBatch, _abotDiagText, new Vector2(10, 60), Color.Orange);







            }















            if (false)







            {







                fontDbg.DrawText(spriteBatch, $"POS DEBUG: F1=off | F2=BF | F3=Dad | F4=GF | F5=ABot | Arrow=nudge | 1-5=step({_posDebugStep:F0}px) | Shift=fine | Ctrl=x5", new Vector2(10, 10), Color.Lime);







                fontDbg.DrawText(spriteBatch, "I=idle L=singLEFT D=singDOWN U=singUP R=singRIGHT S=shoot1 | F6=dump F7=reset F8=resetALL | F9=propEdit", new Vector2(10, 26), Color.Lime);







            }







            if (false)







            {







                var pp = _staticProps[_propDebugIndex];







                var pn = _propDebugNudges.TryGetValue(_propDebugIndex, out var nv) ? nv : Vector2.Zero;







                fontDbg.DrawText(spriteBatch, $"PROP DEBUG [{_propDebugIndex}/{_staticProps.Count - 1}] {pp.Name} pos=({pp.X + pn.X:F0},{pp.Y + pn.Y:F0}) nudge=({pn.X:F0},{pn.Y:F0})", new Vector2(10, 44), Color.Yellow);







                fontDbg.DrawText(spriteBatch, "F9=off | PgUp/PgDn=prop | Arrow=nudge | 1-5=step | F7=reset | Shift+F8=resetALL | F10=save", new Vector2(10, 60), Color.Yellow);







            }















        }















        spriteBatch.End();















        // Restore previous scissor rectangle after world pass















        Game.GraphicsDevice.ScissorRectangle = prevScissor;
        BlazinDrawCameraFx(spriteBatch);
        EndRainWorldPass(spriteBatch, zoom);
        W6DrawGameFilter(spriteBatch); SsfDrawGameOverlay(spriteBatch); // week 6 RetroCameraFade on camGame
        DrawPsychCamFx(spriteBatch, FNF_MonoGame.Engine.PsychEngine.PsychCamera.GameCam, true); // Psych camGame alpha/visible/flash/fade
        DrawHxExtraCameras(spriteBatch); // HScript FlxCameras added between camGame and camHUD
















        















        // === HUD PASS: note field, health bar, score (with subtle HUD zoom) ===















        float hudZoom = (1f + _hudZoomAdd) * HudUserScale; // Options: HUD Scale / Safe Area (1 by default)















        var hudMatrix = Matrix.CreateTranslation(-1280 / 2f, -720 / 2f, 0)















                      * Matrix.CreateScale(hudZoom, hudZoom, 1f)















                      * Matrix.CreateTranslation(1280 / 2f, 720 / 2f, 0) * PsychHudCamMatrix;















        var __w5Hud = W5HudBegin(); // camHUD.alpha < 1 (winter horrorland fade-in)
        if (W6HudVisible && PsychHudVisible) { BeginPsychHudLayer(); // week 6: camHUD.visible; Psych camHUD.visible/alpha
        spriteBatch.Begin(samplerState: SamplerState.LinearClamp, blendState: BlendState.NonPremultiplied, transformMatrix: hudMatrix); _hudBatchMatrix = hudMatrix; QsDrawHudBack(spriteBatch);































        // Draw note field / strumline















        _psyPopsDrawn = false; if (UsePsychHud) { PsychDrawHudMembers(spriteBatch, true); if (!_psyPopsDrawn) PsyPopsDraw(spriteBatch); DrawHUD(spriteBatch); } // Psych comboGroup is below uiGroup // Psych: uiGroup is drawn below noteGroup
        W6PixelHudBegin(spriteBatch, hudMatrix); // pixel note style: antialiasing=false (nearest), no atlas bleed
        { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawNoteField(spriteBatch); FNF_MonoGame.Engine.PerfStats.End(5, __pf); }
        W6PixelHudEnd(spriteBatch, hudMatrix);















        















        // Draw HUD















        if (!UsePsychHud) { if (PsychNotes && !_psyPopsDrawn) PsyPopsDraw(spriteBatch); DrawHUD(spriteBatch); }
        if (VsNoteStylePopups) NsPopupsDraw(spriteBatch, hudMatrix); // PopUpStuff zIndex 900: above healthBar/icons/score (800-850), below the strumlines (1000/1001)
        QsDrawHudFront(spriteBatch);















        















        // Draw note splashes on sick hits















        W6PixelHudBegin(spriteBatch, hudMatrix);
        { var __pf = FNF_MonoGame.Engine.PerfStats.Begin(); DrawNoteSplashes(spriteBatch); FNF_MonoGame.Engine.PerfStats.End(7, __pf); }
        W6PixelHudEnd(spriteBatch, hudMatrix);















        















        // Draw hold note cover glow effect (M11)















        DrawHoldNoteCovers(spriteBatch);















        















        // Draw Lua sprites on the HUD camera
        DrawHudStageProps(spriteBatch);

        // Draw Lua texts created by scripts
        DrawLuaTexts(spriteBatch);

        // Draw custom substate on top of everything
        CustomSubstate.Instance?.Draw(spriteBatch);

        DrawNoteTimingPopup(spriteBatch); DrawReplayBadge(spriteBatch); // Draw rating popup (physics now in Update)















        if (false && _ratingTimer > 0 && !VsNoteStylePopups) // legacy popup (replaced by NsPopups / PsyPops)















        {















            DrawRating(spriteBatch);















        }















        















        spriteBatch.End();
        EndPsychHudLayer(spriteBatch); DrawPsychCamFx(spriteBatch, FNF_MonoGame.Engine.PsychEngine.PsychCamera.HudCam, false);
        } // W6HudVisible
        W5HudEnd(spriteBatch, __w5Hud); DrawPsychOtherCamBars(spriteBatch); // composite the faded HUD layer (camHUD.alpha); Psych camOther bars (drawn after camHUD)















        















        // === OVERLAY PASS: countdown, pause, dialogue (no zoom) ===















        spriteBatch.Begin(samplerState: SamplerState.LinearClamp, blendState: BlendState.NonPremultiplied);















        















        // Draw countdown















        if (_countdownActive || _countdownDisplayTimer > 0)















        {















            DrawCountdown(spriteBatch);















        }















        















        W6DrawCutscene(spriteBatch); // week 6 camCutscene (conversation, cutscene sprites)
        AnimLogTick(); W1DrawCutscene(spriteBatch); VsDrawCutsceneOverlay(spriteBatch); SsfDrawCutscene(spriteBatch); DoppelDraw(spriteBatch); EggDraw(spriteBatch); // weekend 1 cutscene black bg
        VideoDraw(spriteBatch); // video cutscene (camCutscene)
        DrawOnlinePause(spriteBatch); // Draw pause overlay on top of everything















        if (_paused)















        {















            DrawPauseOverlay(spriteBatch);















        }















        















        DrawPsychDialogue(spriteBatch); // DialogueBoxPsych on camHUD
        // Dialogue overlay (M3)















        if (_dialogueActive)















        {















            DrawDialogue(spriteBatch);















        }

        if (CustomSubstate.Instance?.IsActive == true)
            CustomSubstate.Instance.Draw(spriteBatch);
















        















        spriteBatch.End();















    }















    















    private void DrawStage(SpriteBatch spriteBatch)















    {















        // JSON-loaded stage: all props (static + animated) are drawn by DrawPropsInRange















        // in z-order interleaved with characters. Nothing to do here.















        if (_hasJsonStage)















        {















            return;















        }















        















        // Legacy stage drawing (no JSON)















        if (_stageBackdrop != null && _stageBackdrop != Assets.Pixel)















        {















            // Scale to fill entire screen (cover, not contain)















            float scaleX = (float)FNFGame.SCREEN_WIDTH / _stageBackdrop.Width;















            float scaleY = (float)FNFGame.SCREEN_HEIGHT / _stageBackdrop.Height;















            float scale = Math.Max(scaleX, scaleY) * 1.05f; // Slight oversize to cover















            int width = (int)(_stageBackdrop.Width * scale);















            int height = (int)(_stageBackdrop.Height * scale);















            // Background parallax: reduced scroll factor (original: scrollFactor ~0.5 for BG)















            int x = (FNFGame.SCREEN_WIDTH - width) / 2 + (int)(_cameraX * 0.5f);















            int y = (FNFGame.SCREEN_HEIGHT - height) / 2 + (int)(_cameraY * 0.5f);















            spriteBatch.Draw(_stageBackdrop, new Rectangle(x, y, width, height), Color.White);















        }















        else















        {















            spriteBatch.Draw(Assets.Pixel, 















                new Rectangle(0, 0, FNFGame.SCREEN_WIDTH, FNFGame.SCREEN_HEIGHT), 















                new Color(40, 30, 50));















        }















        















        if (_stageFront != null && _stageFront != Assets.Pixel)















        {















            float scale = (float)FNFGame.SCREEN_WIDTH / _stageFront.Width * 1.1f;















            int width = (int)(_stageFront.Width * scale);















            int height = (int)(_stageFront.Height * scale);















            // Stage front parallax: closer to camera than backdrop















            int x = (FNFGame.SCREEN_WIDTH - width) / 2 + (int)(_cameraX * 0.8f);















            spriteBatch.Draw(_stageFront, 















                new Rectangle(x, FNFGame.SCREEN_HEIGHT - height - 10 + (int)(_cameraY * 0.8f), width, height), Color.White);















        }















    }















    















    private void DrawStageCurtains(SpriteBatch spriteBatch)















    {















        if (_stageCurtains != null && _stageCurtains != Assets.Pixel)















        {















            float scale = (float)FNFGame.SCREEN_HEIGHT / _stageCurtains.Height;















            int width = (int)(_stageCurtains.Width * scale);















            int height = (int)(_stageCurtains.Height * scale);















            // Curtains parallax: foreground layer, slight camera offset















            int x = (FNFGame.SCREEN_WIDTH - width) / 2 + (int)(_cameraX * 0.3f);















            spriteBatch.Draw(_stageCurtains, new Rectangle(x, (int)(_cameraY * 0.3f), width, height), Color.White);















        }















    }















    















    /// <summary>















    /// Draw a static stage prop at its JSON-defined position with parallax scroll.















    /// Original FNF: each prop has position, scale, and scrollFactor from stage JSON.















    /// The camera offset is multiplied by the prop's scroll factor for parallax depth.















    /// </summary>















    private void DrawStaticProp(SpriteBatch spriteBatch, StaticStageProp prop)















    { if (SsfDrawStatic(spriteBatch, prop)) return;















        if (DrawPsychCharacterProp(spriteBatch, prop)) return;
        if (prop?.Texture == null || !prop.Visible)
            return;

        if (!string.IsNullOrWhiteSpace(prop.Blend))















        {















            var blendState = GetStageBlendState(prop.Blend);















            if (blendState != null)















            {















                DrawBlazinStaticProp(spriteBatch, prop, blendState);















                return;















            }















        }































        if (_isPhillyBlazinStage && prop.Name == "skyAdditive")















        {















            BzDrawBlendProp(spriteBatch, prop);















            return;















        }































        if (_isPhillyBlazinStage && prop.Name == "foregroundMultiply")















        {















            BzDrawBlendProp(spriteBatch, prop);















            return;















        }































        if (_isPhillyBlazinStage && prop.Name == "additionalLighten")















        {















            BzDrawBlendProp(spriteBatch, prop);















            return;















        }































        // Use WorldToScreen for camera projection � zoom is applied by the SpriteBatch matrix















        Vector2 psychOrigin = Vector2.Zero; float pivX = prop.X + PsychScaleShift(prop, true), pivY = prop.Y + PsychScaleShift(prop, false);
        if (prop.PsychOffsetX.HasValue) { var pv = PsychPivot(prop); pivX = pv.X; pivY = pv.Y; psychOrigin = pv.Z; } // FlxSprite: rotate + scale about origin
        var screenPos = IsHudCamera(prop.Camera)
            ? new Vector2(pivX, pivY) // flixel: scaled about the frame centre on any camera
            : WorldToScreen(pivX, pivY, prop.ScrollX, prop.ScrollY);















        int w = (int)((prop.SourceRect?.Width ?? prop.Texture.Width) * prop.ScaleX);















        int h = (int)((prop.SourceRect?.Height ?? prop.Texture.Height) * prop.ScaleY);































        // Philly window lights: tint with cycling colors (original: curLightColor alpha blend)















        Color tint = Color.White;















        if (_phillyLightsIndex >= 0 && prop.Name == "lights")















        {















            tint = _ptLightColor; // lightWindow.color (BuildingEffectShader applied in DrawStaticProp)















        }































        if (prop.OverlayColor.HasValue)















        {















            var overlay = prop.OverlayColor.Value;















            tint = new Color(overlay.R, overlay.G, overlay.B, tint.A);















        }































        if (prop.PsychOffsetX.HasValue) tint = new Color(tint.R, tint.G, tint.B, (byte)Math.Round(Math.Clamp(prop.Alpha, 0f, 1f) * 255f)); else if (prop.Alpha < 1f) tint = new Color(tint.R, tint.G, tint.B, (byte)Math.Round(tint.A * Math.Clamp(prop.Alpha, 0f, 1f))); // NonPremultiplied batch: straight alpha (tint *= a gave alpha^2: bgLight/stairsLight fades too dark)































        bool isAbotPart = !string.IsNullOrEmpty(prop.Name) && prop.Name.StartsWith("neneSpeaker", StringComparison.OrdinalIgnoreCase);















        SpriteEffects fx = SpriteEffects.None;







        if (prop.FlipX || (_abotDebugMode && _abotDebugFlipX && isAbotPart))







            fx |= SpriteEffects.FlipHorizontally;







        if (prop.FlipY)







            fx |= SpriteEffects.FlipVertically;















        bool ptFx = PtBeginLightFx(spriteBatch, prop);
        spriteBatch.Draw(







            prop.Texture,







            new Vector2(screenPos.X, screenPos.Y),







            prop.SourceRect,







            tint,







            MathHelper.ToRadians(prop.Angle),







            psychOrigin,







            new Vector2(prop.ScaleX, prop.ScaleY),







            fx,







            0f);
        PtEndLightFx(spriteBatch, ptFx);















    }































    private void DrawBlazinStaticProp(SpriteBatch spriteBatch, StaticStageProp prop, BlendState blendState)















    {















        spriteBatch.End();















        spriteBatch.Begin(samplerState: _worldSampler, blendState: blendState, transformMatrix: _worldZoomMatrix, rasterizerState: _worldClipRaster);































        var screenPos = IsHudCamera(prop.Camera)
            ? new Vector2(prop.X + PsychScaleShift(prop, true), prop.Y + PsychScaleShift(prop, false)) // flixel: scaled about the frame centre on any camera
            : WorldToScreen(prop.X, prop.Y, prop.ScrollX, prop.ScrollY);















        Color tint = Color.White * Math.Clamp(prop.Alpha, 0f, 1f);















        if (prop.OverlayColor.HasValue)















        {















            var overlay = prop.OverlayColor.Value;















            tint = new Color(overlay.R, overlay.G, overlay.B, tint.A);















        }















        // Straight-alpha textures under BlendState.Additive (SourceAlpha, One): a premultiplied tint (White * a) would give
        // alpha^2; OpenFL ADD adds rgb * texAlpha * spriteAlpha -> keep rgb unscaled and put the sprite alpha in A only.
        if (ReferenceEquals(blendState, BlendState.Additive))
        {
            var rgb = prop.OverlayColor ?? Color.White;
            tint = new Color(rgb.R, rgb.G, rgb.B, (byte)Math.Round(Math.Clamp(prop.Alpha, 0f, 1f) * 255f));
        }
        spriteBatch.Draw(















            prop.Texture,















            new Vector2(screenPos.X, screenPos.Y),















            prop.SourceRect,















            tint,















            0f,















            Vector2.Zero,















            new Vector2(prop.ScaleX, prop.ScaleY),















            SpriteEffects.None,















            0f);































        spriteBatch.End();















        spriteBatch.Begin(samplerState: _worldSampler, blendState: _worldBlendState, transformMatrix: _worldZoomMatrix, rasterizerState: _worldClipRaster);















    }































    private BlendState GetStageBlendState(string blend)















    {















        if (string.IsNullOrWhiteSpace(blend))















            return null;































        return blend.Trim().ToLowerInvariant() switch















        {















            "add" or "additive" or "screen" => BlendState.Additive,















            "multiply" => _phillyBlazinMultiplyBlend,















            _ => null















        };















    }















    















    private void UpdateAbotVisualizer(float delta)















    {
        if (W6PixelVizUpdate()) return; // every A-Bot (nene, nene-dark, nene-christmas, nene-pixel...): ABotVis/SpectralAnalyzer port (PlayScene.Week6.cs)
















        _abotVizUpdateTimer += delta;















        if (_abotVizUpdateTimer < (1f / 30f))















            return;















        _abotVizUpdateTimer = 0f;































        if (_abotDebugMode)















        {















            for (int pi = 0; pi < _animatedProps.Count; pi++)















            {















                var dbgProp = _animatedProps[pi];















                if (!string.IsNullOrEmpty(dbgProp.Name) && dbgProp.Name.StartsWith("neneSpeakerViz", StringComparison.OrdinalIgnoreCase))















                {















                    dbgProp.Alpha = 1f;















                    _animatedProps[pi] = dbgProp;















                }















            }















            return;















        }































        // Simulate per-bar frequency analysis like original FNF's SpectralAnalyzer.















        // Original: analyzer.getLevels() returns per-band values 0-1.















        // We fake this with time-based oscillation + music level for sparse display.















        float time = (float)Audio.MusicPosition; // Current song time in seconds















        float baseLevel = Audio.MusicPlaying ? Audio.MusicVisualizerLevel : 0f;































        for (int pi = 0; pi < _animatedProps.Count; pi++)















        {















            var prop = _animatedProps[pi];















            if (string.IsNullOrEmpty(prop.Name) || !prop.Name.StartsWith("neneSpeakerViz", StringComparison.OrdinalIgnoreCase))















                continue;































            if (!int.TryParse(prop.Name["neneSpeakerViz".Length..], out int oneBasedIndex))















                continue;































            int barIndex = oneBasedIndex - 1;















            if (barIndex < 0 || barIndex >= _abotVizDisplayLevels.Length)















                continue;































            // Per-bar simulated frequency band:















            // Bar 0 = bass (low freq), Bar 6 = treble (high freq)















            // Each bar gets a different phase/frequency so they don't all move together















            float barPhase = barIndex * 1.7f + time * (3f + barIndex * 0.5f);















            float barNoise = (MathF.Sin(barPhase) + MathF.Sin(barPhase * 1.3f) * 0.5f) * 0.5f + 0.5f;































            // Bass bars (0-2) react more to music, treble bars (3-6) react less















            float barSensitivity = barIndex < 3 ? 1.0f : (barIndex < 5 ? 0.6f : 0.35f);































            // Combine base level with per-bar noise for independent bar movement















            float target = baseLevel * barNoise * barSensitivity;































            // Threshold: only show when there's actual audio (matches original sparse look)















            // Original: animFrame = round(value * 6), visible = animFrame > 0















            // Most bars are at 0 (hidden) most of the time















            float threshold = 0.40f + barIndex * 0.06f; // Much higher threshold for sparse display like original















            target = target > threshold ? (target - threshold) / (1f - threshold) : 0f;































            float current = _abotVizDisplayLevels[barIndex];















            float lerp = target > current ? 0.55f : 0.22f;















            current += (target - current) * lerp;















            _abotVizDisplayLevels[barIndex] = current;































            // Original FNF frame calculation:















            // animFrame = round(value * 6)















            // visible = animFrame > 0















            // animFrame = clamp(animFrame - 1, 0, 5)















            // animFrame = abs(animFrame - 5)  // flip: 0->5, 1->4, ... 5->0















            int animFrame = (int)MathF.Round(current * 6f);















            bool visible = animFrame > 0;































            animFrame = Math.Clamp(animFrame - 1, 0, 5);















            animFrame = Math.Abs(animFrame - 5);































            string animName = prop.DanceAnimNames?.Length > 0















                ? prop.DanceAnimNames[0]















                : prop.Sprite?.CurrentAnimation;































            if (!string.IsNullOrEmpty(animName) && prop.Sprite != null && prop.Sprite.FrameIndex != animFrame)















                prop.Sprite.PlayAnimationFromFrame(animName, animFrame, loop: false, loopFrame: animFrame);































            // Hide bar completely when frame is 0 (dark background shows through)















            prop.Alpha = visible ? 1f : 0f;















            _animatedProps[pi] = prop;















        }















    }































    private void UpdateAbotFallbackAnchors()















    {















        if (!_hasAbotFallback)















            return;































        if (_girlfriend != null)















        {















            // nene-pixel.hxc: abot.x = this.x + 296 - (-globalOffsets[0] * scale)







            // HaxeFlixel this.x = CornerPosition (includes globalOffsets).







            // A-Bot base is locked after first update. HaxeFlixel sets abot.x/y once in onCreate/onUpdate







            // and the A-Bot does NOT follow the character during animations. Lock it here.







            // FIX: Only lock after countdown ends, so gf has settled into final position.







            if (!_countdownActive && !_abotPixelBaseSet)







            {







                // HaxeFlixel this.x/this.y = CornerPosition (includes globalOffsets)







                _abotBaseX = _girlfriend.CornerPosition.X + _abotBodyOffsetX;







                _abotBaseY = _girlfriend.CornerPosition.Y + _abotBodyOffsetY;







                _abotPixelBaseSet = true;
                Console.WriteLine($"[ABOTLOCK] corner={_girlfriend.CornerPosition} bodyOff=({_abotBodyOffsetX},{_abotBodyOffsetY}) base=({_abotBaseX},{_abotBaseY})");







            }







            else if (_countdownActive)







            {







                // During countdown, keep base updated so A-Bot follows gf while she settles







                _abotBaseX = _girlfriend.CornerPosition.X + _abotBodyOffsetX;







                _abotBaseY = _girlfriend.CornerPosition.Y + _abotBodyOffsetY;







            }















        }







































        for (int pi = 0; pi < _animatedProps.Count; pi++)















        {















            var prop = _animatedProps[pi];















            if (prop.Sprite == null)















                continue;































            if (string.Equals(prop.Name, "neneSpeakerRig", StringComparison.OrdinalIgnoreCase))















            {















                if (_abotIsPixel)















                {















                    // HaxeFlixel abot.origin = (52,26) after centerOrigin + Math.round.







                    // MonoGame body top-left = abot.x - 312, abot.y - 156.







                    prop.Sprite.Position = new Vector2(_abotBaseX - 260f, _abotBaseY - 130f);















                }















                else















                {















                    var bodyBasePos = new Vector2(_abotBaseX, _abotBaseY);















                    var bodyOrigin = prop.Sprite.GetCompositeOrigin();















                    // Original: abot (FunkinSprite, flixel-animate) draws its timeline box at exactly (abot.x, abot.y).
                    Vector2 finalPos = prop.Sprite.UseTimelineAnchoring ? bodyBasePos : (bodyOrigin.HasValue ? bodyBasePos + bodyOrigin.Value : bodyBasePos);
                    prop.Sprite.Position = finalPos;
                    if (Environment.GetEnvironmentVariable("FNF_CAMLOG") == "1" && (DateTime.Now - _dbgAbotT).TotalSeconds >= 1) { _dbgAbotT = DateTime.Now; Console.WriteLine($"[ABOTDRAW] base=({_abotBaseX},{_abotBaseY}) spritePos={finalPos} gf={_girlfriend?.Position}"); }















                }















                _animatedProps[pi] = prop;















                continue;















            }































            if (string.Equals(prop.Name, "neneSpeakerPupil", StringComparison.OrdinalIgnoreCase))















            {















                prop.Sprite.Position = new Vector2(_abotBaseX + _abotPupilOffsetX, _abotBaseY + _abotPupilOffsetY);















                _animatedProps[pi] = prop;















                continue;















            }































            if (string.Equals(prop.Name, "neneSpeakerPixelHead", StringComparison.OrdinalIgnoreCase))







            {







                prop.Sprite.Position = new Vector2(_abotBaseX - 397.5f, _abotBaseY - 28f);







                _animatedProps[pi] = prop;







                continue;







            }































            if (string.Equals(prop.Name, "neneSpeakerPixelSpeaker", StringComparison.OrdinalIgnoreCase))







            {







                prop.Sprite.Position = new Vector2(_abotBaseX - 398f, _abotBaseY - 106f);







                _animatedProps[pi] = prop;







                continue;







            }































            if (prop.Name != null && prop.Name.StartsWith("neneSpeakerViz", StringComparison.OrdinalIgnoreCase))















            {















                if (int.TryParse(prop.Name["neneSpeakerViz".Length..], out int barIndex))















                {















                    // Use pixel or standard viz offsets depending on variant















                    float[] vizOffsetsX = _abotIsPixel















                        ? new[] { 0f, 42f, 48f, 54f, 60f, 36f, 42f }















                        : new[] { 0f, 59f, 56f, 66f, 54f, 52f, 51f };















                    float[] vizOffsetsY = _abotIsPixel















                        ? new[] { 0f, -12f, -6f, 0f, 0f, 6f, 12f }















                        : new[] { 0f, -8f, -3.5f, -0.4f, 0.5f, 4.7f, 7f };































                    float addX = 0f;















                    float addY = 0f;















                    for (int i = 0; i < barIndex && i < vizOffsetsX.Length; i++)















                    {















                        addX += vizOffsetsX[i];















                        addY += vizOffsetsY[i];















                    }































                    prop.Sprite.Position = new Vector2(_abotBaseX + _abotVizBaseOffsetX + addX, _abotBaseY + _abotVizBaseOffsetY + addY);















                    _animatedProps[pi] = prop;















                }















            }















        }































        for (int si = 0; si < _staticProps.Count; si++)















        {















            var prop = _staticProps[si];















            if (string.Equals(prop.Name, "neneSpeakerEyeWhites", StringComparison.OrdinalIgnoreCase))















            {















                prop.X = _abotBaseX + _abotEyesOffsetX;















                prop.Y = _abotBaseY + _abotEyesOffsetY;
                if (_girlfriend != null && (_girlfriend.OriginalName == "nene-dark" || _girlfriend.Name == "nene-dark"))
                {   // nene-dark.hxc set_alpha: eyeWhites.color = FlxColorUtil.interpolate(0xFFFFFFFF, 0xFF6F96CE, alpha)
                    float ea = Math.Clamp(_girlfriend.Alpha, 0f, 1f);
                    prop.OverlayColor = new Color((int)(255 + (111 - 255) * ea), (int)(255 + (150 - 255) * ea), (int)(255 + (206 - 255) * ea));
                }















                _staticProps[si] = prop;















            }















            else if (string.Equals(prop.Name, "neneSpeakerStereoBG", StringComparison.OrdinalIgnoreCase))















            {















                prop.X = _abotBaseX + _abotStereoOffsetX;















                prop.Y = _abotBaseY + _abotStereoOffsetY;















                _staticProps[si] = prop;















            }















            else if (string.Equals(prop.Name, "neneSpeakerPixelBack", StringComparison.OrdinalIgnoreCase))







            {







                prop.X = _abotBaseX - 243.7f;







                prop.Y = _abotBaseY - 107.5f;







                _staticProps[si] = prop;







            }















        }















    }































    /// <summary>















    /// Draw all animated and static props whose zIndex is in [minZ, maxZ).















    /// Used for proper z-interleaved rendering with characters.















    /// </summary>















    private void DrawPropsInRange(SpriteBatch spriteBatch, int minZ, int maxZ)















    {
        try { DrawPropsInRangeCore(spriteBatch, minZ, maxZ); } finally { VsDrawSpritesInRange(spriteBatch, minZ, maxZ); }
    }
    private void DrawPropsInRangeCore(SpriteBatch spriteBatch, int minZ, int maxZ)
    {
        EnsureStageScriptVisualsApplied();
        if (Environment.GetEnvironmentVariable("FNF_PROPLOG") == "1" && !_propLogged)
        {
            _propLogged = true;
            foreach (var sp in _staticProps) Console.WriteLine($"[PROP] static {sp.Name} z={sp.ZIndex} blend={sp.Blend} alpha={sp.Alpha} vis={sp.Visible} pos=({sp.X},{sp.Y}) scroll=({sp.ScrollX},{sp.ScrollY}) scale=({sp.ScaleX},{sp.ScaleY}) tex={sp.Texture?.Width}x{sp.Texture?.Height}");
            foreach (var ap in _animatedProps) Console.WriteLine($"[PROP] anim {ap.Name} z={ap.ZIndex} blend={ap.Blend} alpha={ap.Alpha}");
        }















        // Merge static and animated props by zIndex for correct layering.















        // Both lists are already sorted by zIndex from loading.















        int si = 0, ai = 0;















        while (si < _staticProps.Count || ai < _animatedProps.Count)















        {















            // Get next static prop in range (skip those outside)















            while (si < _staticProps.Count && (_staticProps[si].ZIndex < minZ || _staticProps[si].ZIndex >= maxZ))















                si++;















            // Get next animated prop in range















            while (ai < _animatedProps.Count && (_animatedProps[ai].ZIndex < minZ || _animatedProps[ai].ZIndex >= maxZ))















                ai++;















            















            bool hasStatic = si < _staticProps.Count && _staticProps[si].ZIndex >= minZ && _staticProps[si].ZIndex < maxZ;















            bool hasAnim = ai < _animatedProps.Count && _animatedProps[ai].ZIndex >= minZ && _animatedProps[ai].ZIndex < maxZ;















            















            if (!hasStatic && !hasAnim) break;















            















            if (hasStatic && (!hasAnim || _staticProps[si].ZIndex < _animatedProps[ai].ZIndex
                || (_staticProps[si].ZIndex == _animatedProps[ai].ZIndex && (_animatedProps[ai].Seq == 0 || _staticProps[si].Seq <= _animatedProps[ai].Seq)))) // equal zIndex: stage JSON order (stable sort), e.g. phillyTraffic below phillyTraffic_lightmap















            {















                var sp = _staticProps[si];







                if (_propDebugNudges.TryGetValue(si, out var spNudge))







                {







                    sp.X += spNudge.X;







                    sp.Y += spNudge.Y;







                }







                if (!IsHudCamera(sp.Camera))
                    { bool __wg = W6BeginWiggle(spriteBatch, sp.Name, sp.Texture); bool __adj = !__wg && (SsfBeginProp(spriteBatch, sp.Name) || BeginAdjust(spriteBatch, GetPropAdjust(sp.Name))); DrawStaticProp(spriteBatch, sp); EndAdjust(spriteBatch, __adj); W6EndWiggle(spriteBatch, __wg); }















                si++;















            }















            else if (hasAnim)















            {















                var prop = _animatedProps[ai];















                if (prop.Sprite != null)















                {















                    var origPos = prop.Sprite.Position;







                    var origTint = prop.Sprite.Tint;







                    var origRotation = prop.Sprite.Rotation;







                    var origEffects = prop.Sprite.Effects;















                    // FlxAnimate applyStageMatrix: shift draw pos by the atlas STI translation.







                    // Pre-rendered composites strip the stage offset, so re-add it here.







                    float worldX = origPos.X;







                    float worldY = origPos.Y;







                    if (prop.ApplyStageMatrix && prop.Sprite.Sheet != null)







                    {







                        worldX += prop.Sprite.Sheet.StageOffset.X;







                        worldY += prop.Sprite.Sheet.StageOffset.Y;
                        // FlxAnimate.getAnimateOrigin(): + library.matrix.t + timeline._bounds.min * matrix.(a,d)
                        if (prop.Sprite.UseTimelineAnchoring && prop.Sprite.Sheet.GetTimelineBounds(prop.Sprite.ResolvedAnimName) is { } __tb) { worldX += __tb.X; worldY += __tb.Y; }







                    }















                    // Apply per-animation offsets (original FNF Bopper.setAnimationOffsets)







                    string currentAnim = prop.Sprite.CurrentAnimation ?? "";







                    if (prop.AnimOffsets != null)







                    {







                        string logicalName = currentAnim;







                        if (prop.AnimNameMap != null)







                        {







                            foreach (var kvp in prop.AnimNameMap)







                            {







                                if (kvp.Value == currentAnim)







                                { logicalName = kvp.Key; break; }







                            }







                        }







                        if (prop.AnimOffsets.TryGetValue(logicalName, out var aoff))







                        {







                            worldX += aoff.X;







                            worldY += aoff.Y;







                        }







                    }















                    var screenPos = WorldToScreen(worldX, worldY, prop.ScrollX, prop.ScrollY);















                    prop.Sprite.Position = screenPos;







                    prop.Sprite.Rotation = MathHelper.ToRadians(prop.Angle);







                    if (prop.FlipY)







                        prop.Sprite.Effects |= SpriteEffects.FlipVertically;















                    float alpha = Math.Clamp(prop.Alpha, 0f, 1f);







                    Color baseTint = prop.Color.HasValue ? prop.Color.Value : origTint;







                    byte outA = (byte)Math.Clamp(baseTint.A * alpha, 0f, 255f);







                    Color tint = new Color(baseTint.R, baseTint.G, baseTint.B, outA);















                    if (prop.OverlayColor.HasValue)







                    {







                        var ov = prop.OverlayColor.Value;







                        tint = new Color(ov.R, ov.G, ov.B, outA);







                    }















                    // ABot TextureSwap for nene-dark (original: testShader.amount = gf.alpha)















                    // In original: amount=0 during lightning (normal texture), amount=1 during normal (dark texture)















                    // Use OriginalName since ResolveCharacterSprite strips -dark suffix from Name















                    bool doTextureSwap = prop.DarkSheet != null && _girlfriend != null















                        && (_girlfriend.OriginalName == "nene-dark" || _girlfriend.Name == "nene-dark");















                    if (doTextureSwap)















                    {















                        // Original shader: amount = gf.alpha







                        // amount=0 during lightning (show NORMAL), amount=1 during normal (show DARK)















                        float amount = Math.Clamp(_girlfriend.Alpha, 0f, 1f);















                        var origSheet = prop.Sprite.Sheet;















                        if (amount < 1f)















                        {















                            // Draw NORMAL texture at (1 - amount) opacity during lightning/fade















                            prop.Sprite.Sheet = origSheet;















                            byte normalA = tint.A; // TextureSwap: mix(normal, dark, amount) keeps tex.a -> normal opaque below, dark at amount on top















                            prop.Sprite.Tint = new Color(tint.R, tint.G, tint.B, normalA);















                            { bool __rim = W6BeginPropRim(spriteBatch, prop.Name, prop.Sprite); bool __adj = !__rim && (SsfBeginProp(spriteBatch, prop.Name) || BeginAdjustOrRain(spriteBatch, prop.Name, prop.Sprite, GetPropAdjust(prop.Name))); prop.Sprite.Draw(spriteBatch); EndAdjust(spriteBatch, __adj); W6EndPropRim(spriteBatch, prop.Sprite, __rim); }















                        }















                        if (amount > 0f)















                        {















                            // Draw DARK texture at amount opacity during normal/fade















                            prop.Sprite.Sheet = prop.DarkSheet;















                            byte darkA = (byte)Math.Clamp(tint.A * amount, 0f, 255f);















                            prop.Sprite.Tint = new Color(tint.R, tint.G, tint.B, darkA);















                            { bool __rim = W6BeginPropRim(spriteBatch, prop.Name, prop.Sprite); bool __adj = !__rim && (SsfBeginProp(spriteBatch, prop.Name) || BeginAdjustOrRain(spriteBatch, prop.Name, prop.Sprite, GetPropAdjust(prop.Name))); prop.Sprite.Draw(spriteBatch); EndAdjust(spriteBatch, __adj); W6EndPropRim(spriteBatch, prop.Sprite, __rim); }















                        }















                        prop.Sprite.Sheet = origSheet;















                    }















                    else















                    {















                        prop.Sprite.Tint = tint;















                        { var __pbs = AnimPropBlendBegin(spriteBatch, prop.Blend); bool __rim = W6BeginPropRim(spriteBatch, prop.Name, prop.Sprite); bool __adj = !__rim && (SsfBeginProp(spriteBatch, prop.Name) || BeginAdjustOrRain(spriteBatch, prop.Name, prop.Sprite, GetPropAdjust(prop.Name))); prop.Sprite.Draw(spriteBatch); EndAdjust(spriteBatch, __adj); W6EndPropRim(spriteBatch, prop.Sprite, __rim); AnimPropBlendEnd(spriteBatch, __pbs); }















                    }















                    prop.Sprite.Position = origPos;







                    prop.Sprite.Tint = origTint;







                    prop.Sprite.Rotation = origRotation;







                    prop.Sprite.Effects = origEffects;







                }















                ai++;















            }















        }















    }































    private void HandleAbotDebugInput()















    {















        bool toggleDebug = Input.IsPressed(Keys.F8)















            || Input.IsPressed(Keys.F6)















            || Input.IsPressed(Keys.OemTilde)















            || Input.IsGamePadPressed(Buttons.RightStick);































        if (toggleDebug)















        {















            _abotDebugMode = !_abotDebugMode;















            Console.WriteLine($"[ABOT-DEBUG] mode={(_abotDebugMode ? "ON" : "OFF")}");















        }































        if (!_abotDebugMode)















            return;































        if (Input.IsPressed(Keys.Tab) || Input.IsPressed(Keys.PageDown))















        {















            _abotDebugSelection = (_abotDebugSelection + 1) % 7;















            LogAbotDebugState("selection");















        }































        if (Input.IsPressed(Keys.PageUp))















        {















            _abotDebugSelection = (_abotDebugSelection - 1 + 7) % 7;















            LogAbotDebugState("selection");















        }































        if (Input.IsPressed(Keys.OemPlus) || Input.IsPressed(Keys.Add))















        {















            _abotDebugStep = _abotDebugStep == 1 ? 5 : (_abotDebugStep == 5 ? 10 : 1);















            LogAbotDebugState("step");















        }































        if (Input.IsPressed(Keys.F7))















        {















            _abotDebugFreezeAnim = !_abotDebugFreezeAnim;















            LogAbotDebugState(_abotDebugFreezeAnim ? "anim-freeze" : "anim-live");















        }































        if (Input.IsPressed(Keys.H))















        {















            _abotDebugFlipX = !_abotDebugFlipX;















            LogAbotDebugState(_abotDebugFlipX ? "flipX-on" : "flipX-off");















        }































        if (Input.IsPressed(Keys.OemComma))















        {















            _abotDebugFrame = Math.Max(0, _abotDebugFrame - 1);















            _abotRigStartFrame = _abotDebugFrame;















            LogAbotDebugState("frame-");















        }















        if (Input.IsPressed(Keys.OemPeriod))















        {















            _abotDebugFrame += 1;















            _abotRigStartFrame = _abotDebugFrame;















            LogAbotDebugState("frame+");















        }































        float dx = 0f, dy = 0f;















        if (Input.IsPressed(Keys.NumPad4) || Input.IsPressed(Keys.Left)) dx -= _abotDebugStep;















        if (Input.IsPressed(Keys.NumPad6) || Input.IsPressed(Keys.Right)) dx += _abotDebugStep;















        if (Input.IsPressed(Keys.NumPad8) || Input.IsPressed(Keys.Up)) dy -= _abotDebugStep;















        if (Input.IsPressed(Keys.NumPad2) || Input.IsPressed(Keys.Down)) dy += _abotDebugStep;































        if (dx != 0f || dy != 0f)















        {















            ApplyAbotDebugDelta(dx, dy);















            LogAbotDebugState("move");















        }















    }































    private void ApplyAbotDebugDelta(float dx, float dy)















    {















        switch (_abotDebugSelection)















        {















            case 0: _abotBodyOffsetX += dx; _abotBodyOffsetY += dy; break;















            case 1: _abotEyesOffsetX += dx; _abotEyesOffsetY += dy; break;















            case 2: _abotPupilOffsetX += dx; _abotPupilOffsetY += dy; break;















            case 3: _abotVizBaseOffsetX += dx; _abotVizBaseOffsetY += dy; break;















            case 4: _abotStereoOffsetX += dx; _abotStereoOffsetY += dy; break;















            case 5:















                ABOT_MONITOR_CLIP_X += dx;















                ABOT_MONITOR_CLIP_Y += dy;















                break;















            case 6:















                ABOT_MONITOR_CLIP_W = Math.Max(10f, ABOT_MONITOR_CLIP_W + dx);















                ABOT_MONITOR_CLIP_H = Math.Max(10f, ABOT_MONITOR_CLIP_H + dy);















                break;















        }















    }































    private void LogAbotDebugState(string reason)















    {















        Console.WriteLine($"[ABOT-DEBUG] {reason} sel={_abotDebugSelection} step={_abotDebugStep} freeze={_abotDebugFreezeAnim} flipX={_abotDebugFlipX} frame={_abotDebugFrame} start={_abotRigStartFrame} body=({_abotBodyOffsetX:0.##},{_abotBodyOffsetY:0.##}) eyes=({_abotEyesOffsetX:0.##},{_abotEyesOffsetY:0.##}) pupil=({_abotPupilOffsetX:0.##},{_abotPupilOffsetY:0.##}) viz=({_abotVizBaseOffsetX:0.##},{_abotVizBaseOffsetY:0.##}) stereo=({_abotStereoOffsetX:0.##},{_abotStereoOffsetY:0.##}) clip=({ABOT_MONITOR_CLIP_X:0.##},{ABOT_MONITOR_CLIP_Y:0.##},{ABOT_MONITOR_CLIP_W:0.##},{ABOT_MONITOR_CLIP_H:0.##})");















    }































    private float _posDebugStep = 1f;















    private Vector2 _posDebugOriginalBf, _posDebugOriginalDad, _posDebugOriginalGf;















    private bool _posDebugOrigSaved = false;































    private void HandlePosDebugInput()















    {















        var kb = Keyboard.GetState();















        bool shiftHeld = kb.IsKeyDown(Keys.LeftShift) || kb.IsKeyDown(Keys.RightShift);















        bool ctrlHeld = kb.IsKeyDown(Keys.LeftControl) || kb.IsKeyDown(Keys.RightControl);































        // F11 = dump full positioning diagnostic to file







        if (Input.IsPressed(Keys.F11))







        {







            var diag = new System.Text.StringBuilder();







            diag.AppendLine($"=== POSITION DIAGNOSTIC ({DateTime.Now:HH:mm:ss}) ===");







            diag.AppendLine($"Song: {_songName} | Stage: {_chart?.Stage}");







            diag.AppendLine();







            void DumpChar(string label, Character ch, float[] stagePos)







            {







                if (ch == null) { diag.AppendLine($"{label}: NULL"); return; }







                var origin = ch.GetCharacterOrigin();







                float[] off = ch.CharOffsets;







                float offX = off?.Length >= 2 ? off[0] : 0f;







                float offY = off?.Length >= 2 ? off[1] : 0f;







                int fw = ch._sprite?.GetFrameWidth() ?? 0;







                int fh = ch._sprite?.GetFrameHeight() ?? 0;







                var compOrig = ch._sprite?.GetCurrentCompOrigin() ?? Vector2.Zero;







                diag.AppendLine($"--- {label} ({ch.OriginalName ?? ch.Name}) ---");







                diag.AppendLine($"  StagePos: ({stagePos?[0] ?? 0}, {stagePos?[1] ?? 0})");







                diag.AppendLine($"  CharOrigin (w/2,h): ({origin.X:0.0}, {origin.Y:0.0})");







                diag.AppendLine($"  FrameSize: {fw}x{fh} | Scale: {ch.Scale}");







                diag.AppendLine($"  CharOffsets (globalOff): ({offX}, {offY})");







                diag.AppendLine($"  Position (final): ({ch.Position.X:0.0}, {ch.Position.Y:0.0})");







                diag.AppendLine($"  CompBaseOrigin: ({compOrig.X:0.0}, {compOrig.Y:0.0})");







                diag.AppendLine($"  CurrentAnim: {ch.CurrentAnimation}");







                // Expected original FNF: char.x = stagePos - origin + globalOff







                float expX = (stagePos?[0] ?? 0) - origin.X + offX;







                float expY = (stagePos?[1] ?? 0) - origin.Y + offY;







                diag.AppendLine($"  Expected (stagePos-origin+off): ({expX:0.0}, {expY:0.0})");







                diag.AppendLine($"  MATCH: {(Math.Abs(ch.Position.X - expX) < 1 && Math.Abs(ch.Position.Y - expY) < 1 ? "YES" : "NO")}");







                diag.AppendLine();







            }







            DumpChar("BF", _boyfriend, _pendingBfPos);







            DumpChar("DAD", _opponent, _pendingDadPos);







            DumpChar("GF", _girlfriend, _pendingGfPos);







            string path = @"d:\godt engine custom\position_diagnostic.txt";







            try { System.IO.File.WriteAllText(path, diag.ToString()); } catch { }







            Console.WriteLine($"[DIAG] Position diagnostic written to: {path}");







        }















        // F1 toggles position debug mode















        if (Input.IsPressed(Keys.F1))















        {















            _posDebugMode = !_posDebugMode;







            if (false) _propDebugMode = false; // only one debug mode at a time







            Console.WriteLine($"[POS-DEBUG] mode={(_posDebugMode ? "ON" : "OFF")}");















            if (_posDebugMode && !_posDebugOrigSaved)















            {















                _posDebugOriginalBf = _boyfriend?.Position ?? Vector2.Zero;















                _posDebugOriginalDad = _opponent?.Position ?? Vector2.Zero;















                _posDebugOriginalGf = _girlfriend?.Position ?? Vector2.Zero;















                _posDebugOriginalAbotOffX = _abotBodyOffsetX;















                _posDebugOriginalAbotOffY = _abotBodyOffsetY;















                _posDebugOrigSaved = true;















            }















        }































        if (!_posDebugMode)















            return;































        // F2/F3/F4/F5 select BF/Dad/GF/ABot















        if (Input.IsPressed(Keys.F2)) { _posDebugSelected = 0; Console.WriteLine("[POS-DEBUG] Selected: BF (Pico)"); }















        if (Input.IsPressed(Keys.F3)) { _posDebugSelected = 1; Console.WriteLine("[POS-DEBUG] Selected: Dad (Parents)"); }















        if (Input.IsPressed(Keys.F4)) { _posDebugSelected = 2; Console.WriteLine("[POS-DEBUG] Selected: GF (Nene)"); }















        if (Input.IsPressed(Keys.F5)) { _posDebugSelected = 3; Console.WriteLine("[POS-DEBUG] Selected: ABot"); }































        // Number keys set step size















        if (Input.IsPressed(Keys.D1)) { _posDebugStep = 1f; Console.WriteLine("[POS-DEBUG] Step=1px"); }















        if (Input.IsPressed(Keys.D2)) { _posDebugStep = 5f; Console.WriteLine("[POS-DEBUG] Step=5px"); }















        if (Input.IsPressed(Keys.D3)) { _posDebugStep = 10f; Console.WriteLine("[POS-DEBUG] Step=10px"); }















        if (Input.IsPressed(Keys.D4)) { _posDebugStep = 50f; Console.WriteLine("[POS-DEBUG] Step=50px"); }















        if (Input.IsPressed(Keys.D5)) { _posDebugStep = 100f; Console.WriteLine("[POS-DEBUG] Step=100px"); }































        // Arrow keys nudge selected entity















        float step = _posDebugStep;















        if (shiftHeld) step = 1f;















        if (ctrlHeld) step *= 5f;















        float dx = 0f, dy = 0f;















        if (Input.IsPressed(Keys.Left)) dx -= step;















        if (Input.IsPressed(Keys.Right)) dx += step;















        if (Input.IsPressed(Keys.Up)) dy -= step;















        if (Input.IsPressed(Keys.Down)) dy += step;















        if (dx != 0f || dy != 0f)















        {















            _posDebugNudge[_posDebugSelected] += new Vector2(dx, dy);















            if (_posDebugSelected == 3)















            {















                // ABot: nudge the body offsets















                _abotBodyOffsetX += dx;















                _abotBodyOffsetY += dy;















                Console.WriteLine($"[POS-DEBUG] ABot nudge=({_posDebugNudge[3].X:F1},{_posDebugNudge[3].Y:F1}) offsets=({_abotBodyOffsetX:F1},{_abotBodyOffsetY:F1})");















            }















            else















            {















                var ch = _posDebugSelected == 0 ? _boyfriend : (_posDebugSelected == 1 ? _opponent : _girlfriend);















                if (ch != null)















                {















                    ch.Position += new Vector2(dx, dy);















                    string name = _posDebugSelected == 0 ? "BF" : (_posDebugSelected == 1 ? "Dad" : "GF");















                    Console.WriteLine($"[POS-DEBUG] {name} nudge=({_posDebugNudge[_posDebugSelected].X:F1},{_posDebugNudge[_posDebugSelected].Y:F1}) pos=({ch.Position.X:F1},{ch.Position.Y:F1}) corner=({ch.CornerPosition.X:F1},{ch.CornerPosition.Y:F1})");















                }















            }















        }































        // F6 = print all current positions (copy-paste ready)















        if (Input.IsPressed(Keys.F6))















        {















            var abotPos = new Vector2(







                (_girlfriend?.Position.X ?? 0f) + _abotBodyOffsetX,







                (_girlfriend?.Position.Y ?? 0f) + _abotBodyOffsetY);















            Console.WriteLine("========== COPY THESE VALUES ==========");















            Console.WriteLine($"BF  Position: ({_boyfriend?.Position.X:F1},{_boyfriend?.Position.Y:F1})  Corner: ({_boyfriend?.CornerPosition.X:F1},{_boyfriend?.CornerPosition.Y:F1})");















            Console.WriteLine($"Dad Position: ({_opponent?.Position.X:F1},{_opponent?.Position.Y:F1})  Corner: ({_opponent?.CornerPosition.X:F1},{_opponent?.CornerPosition.Y:F1})");















            Console.WriteLine($"GF  Position: ({_girlfriend?.Position.X:F1},{_girlfriend?.Position.Y:F1})  Corner: ({_girlfriend?.CornerPosition.X:F1},{_girlfriend?.CornerPosition.Y:F1})");















            Console.WriteLine($"ABot Base: ({abotPos.X:F1},{abotPos.Y:F1})  Offsets: ({_abotBodyOffsetX:F1},{_abotBodyOffsetY:F1})");















            Console.WriteLine($"Nudge BF=({_posDebugNudge[0].X:F1},{_posDebugNudge[0].Y:F1}) Dad=({_posDebugNudge[1].X:F1},{_posDebugNudge[1].Y:F1}) GF=({_posDebugNudge[2].X:F1},{_posDebugNudge[2].Y:F1}) ABot=({_posDebugNudge[3].X:F1},{_posDebugNudge[3].Y:F1})");







            if (_propDebugNudges.Count > 0)







            {







                Console.WriteLine("--- Prop Nudges ---");







                foreach (var kvp in _propDebugNudges)







                {







                    int idx = kvp.Key;







                    var nudge = kvp.Value;







                    if (idx >= 0 && idx < _staticProps.Count)







                    {







                        var p = _staticProps[idx];







                        Console.WriteLine($"  [{idx}] {p.Name}: pos=({p.X + nudge.X:F1},{p.Y + nudge.Y:F1}) nudge=({nudge.X:F1},{nudge.Y:F1})");







                    }







                }







            }







            Console.WriteLine("=======================================");















        }































        // Animation playback on selected character







        if (Input.IsPressed(Keys.I))







        {







            var ch = _posDebugSelected == 0 ? _boyfriend : (_posDebugSelected == 1 ? _opponent : _girlfriend);







            ch?.PlayAnimation("idle", force: true);







            Console.WriteLine($"[POS-DEBUG] Played 'idle' on {_posDebugSelected}");







        }







        if (Input.IsPressed(Keys.L))







        {







            var ch = _posDebugSelected == 0 ? _boyfriend : (_posDebugSelected == 1 ? _opponent : _girlfriend);







            ch?.PlayAnimation("singLEFT", force: true);







            Console.WriteLine($"[POS-DEBUG] Played 'singLEFT' on {_posDebugSelected}");







        }







        if (Input.IsPressed(Keys.D))







        {







            var ch = _posDebugSelected == 0 ? _boyfriend : (_posDebugSelected == 1 ? _opponent : _girlfriend);







            ch?.PlayAnimation("singDOWN", force: true);







            Console.WriteLine($"[POS-DEBUG] Played 'singDOWN' on {_posDebugSelected}");







        }







        if (Input.IsPressed(Keys.U))







        {







            var ch = _posDebugSelected == 0 ? _boyfriend : (_posDebugSelected == 1 ? _opponent : _girlfriend);







            ch?.PlayAnimation("singUP", force: true);







            Console.WriteLine($"[POS-DEBUG] Played 'singUP' on {_posDebugSelected}");







        }







        if (Input.ResetPressed && !FNF_MonoGame.Engine.PsychEngine.ClientPrefs.Data.NoReset)   // R by default (Options > Controls > Reset); Psych 'Disable Reset Button'







        {







            var ch = _posDebugSelected == 0 ? _boyfriend : (_posDebugSelected == 1 ? _opponent : _girlfriend);







            ch?.PlayAnimation("singRIGHT", force: true);







            Console.WriteLine($"[POS-DEBUG] Played 'singRIGHT' on {_posDebugSelected}");







        }







        if (Input.IsPressed(Keys.S))







        {







            // S = shoot animations (for Otis/GF speaker characters)







            var gf = _girlfriend;







            if (gf != null)







            {







                gf.PlayAnimation("shoot1", force: true);







                Console.WriteLine("[POS-DEBUG] Played 'shoot1' on GF");







            }







        }















        // F7 = reset selected entity to original (skip if prop debug is active)















        if (!_propDebugMode && Input.IsPressed(Keys.F7))















        {















            if (_posDebugSelected == 3)















            {















                _abotBodyOffsetX = _posDebugOriginalAbotOffX;















                _abotBodyOffsetY = _posDebugOriginalAbotOffY;















                _posDebugNudge[3] = Vector2.Zero;















                Console.WriteLine($"[POS-DEBUG] ABot RESET offsets to ({_abotBodyOffsetX:F1},{_abotBodyOffsetY:F1})");















            }















            else















            {















                var ch = _posDebugSelected == 0 ? _boyfriend : (_posDebugSelected == 1 ? _opponent : _girlfriend);















                var orig = _posDebugSelected == 0 ? _posDebugOriginalBf : (_posDebugSelected == 1 ? _posDebugOriginalDad : _posDebugOriginalGf);















                if (ch != null)















                {















                    ch.Position = orig;















                    _posDebugNudge[_posDebugSelected] = Vector2.Zero;















                    string name = _posDebugSelected == 0 ? "BF" : (_posDebugSelected == 1 ? "Dad" : "GF");















                    Console.WriteLine($"[POS-DEBUG] {name} RESET to ({orig.X:F1},{orig.Y:F1})");















                }















            }















        }































        // F8 = reset ALL (skip if prop debug is active)















        if (!_propDebugMode && Input.IsPressed(Keys.F8))















        {















            if (_boyfriend != null) { _boyfriend.Position = _posDebugOriginalBf; _posDebugNudge[0] = Vector2.Zero; }















            if (_opponent != null) { _opponent.Position = _posDebugOriginalDad; _posDebugNudge[1] = Vector2.Zero; }















            if (_girlfriend != null) { _girlfriend.Position = _posDebugOriginalGf; _posDebugNudge[2] = Vector2.Zero; }















            _abotBodyOffsetX = _posDebugOriginalAbotOffX;















            _abotBodyOffsetY = _posDebugOriginalAbotOffY;















            _posDebugNudge[3] = Vector2.Zero;















            Console.WriteLine("[POS-DEBUG] ALL RESET");















        }















    }















    private void HandlePropDebugInput()







    {







        if (Input.IsPressed(Keys.F9))







        {







            _propDebugMode = !_propDebugMode;







            if (_propDebugMode) _posDebugMode = false; // only one debug mode at a time







            Console.WriteLine($"[PROP-DEBUG] mode={(_propDebugMode ? "ON" : "OFF")}");







        }







        if (!_propDebugMode) return;















        // PageUp/PageDown cycle through props







        if (Input.IsPressed(Keys.PageUp))







        {







            _propDebugIndex = Math.Max(0, _propDebugIndex - 1);







            var p = _staticProps[_propDebugIndex];







            Console.WriteLine($"[PROP-DEBUG] Selected [{_propDebugIndex}] {p.Name} pos=({p.X:F1},{p.Y:F1})");







        }







        if (Input.IsPressed(Keys.PageDown))







        {







            _propDebugIndex = Math.Min(_staticProps.Count - 1, _propDebugIndex + 1);







            var p = _staticProps[_propDebugIndex];







            Console.WriteLine($"[PROP-DEBUG] Selected [{_propDebugIndex}] {p.Name} pos=({p.X:F1},{p.Y:F1})");







        }















        float step = _posDebugStep;







        if (Input.IsHeld(Keys.LeftShift)) step = 1f;







        if (Input.IsHeld(Keys.LeftControl)) step *= 5f;















        float dx = 0, dy = 0;







        if (Input.IsPressed(Keys.Left)) dx = -step;







        if (Input.IsPressed(Keys.Right)) dx = step;







        if (Input.IsPressed(Keys.Up)) dy = -step;







        if (Input.IsPressed(Keys.Down)) dy = step;















        if (dx != 0 || dy != 0)







        {







            if (!_propDebugNudges.ContainsKey(_propDebugIndex))







                _propDebugNudges[_propDebugIndex] = Vector2.Zero;







            _propDebugNudges[_propDebugIndex] += new Vector2(dx, dy);







            var p = _staticProps[_propDebugIndex];







            var nudge = _propDebugNudges[_propDebugIndex];







            Console.WriteLine($"[PROP-DEBUG] {p.Name} nudge=({nudge.X:F1},{nudge.Y:F1}) pos=({p.X + nudge.X:F1},{p.Y + nudge.Y:F1})");







        }















        // F7 = reset selected prop







        if (Input.IsPressed(Keys.F7))







        {







            _propDebugNudges.Remove(_propDebugIndex);







            var p = _staticProps[_propDebugIndex];







            Console.WriteLine($"[PROP-DEBUG] {p.Name} RESET to ({p.X:F1},{p.Y:F1})");







        }















        // Shift+F8 = reset ALL props







        if (Input.IsHeld(Keys.LeftShift) && Input.IsPressed(Keys.F8))







        {







            _propDebugNudges.Clear();







            Console.WriteLine("[PROP-DEBUG] ALL props RESET");







        }















        // F10 = save prop positions to stage JSON







        if (Input.IsPressed(Keys.F10))







        {







            SavePropDebugPositions();







        }







    }















    private void SavePropDebugPositions()







    {







        try







        {







            if (string.IsNullOrEmpty(_stageJsonFilePath) || !global::FNF_MonoGame.Engine.FsCI.FileExists(_stageJsonFilePath)) return;







            var json = global::FNF_MonoGame.Engine.FsCI.ReadAllText(_stageJsonFilePath);







            var root = JObject.Parse(json);







            var propsArr = root["props"] as JArray;







            if (propsArr == null) return;







            foreach (var kvp in _propDebugNudges)







            {







                int idx = kvp.Key;







                var nudge = kvp.Value;







                if (idx < 0 || idx >= _staticProps.Count || idx >= propsArr.Count) continue;







                var p = _staticProps[idx];







                propsArr[idx]["position"] = new JArray(Math.Round(p.X + nudge.X, 1), Math.Round(p.Y + nudge.Y, 1));







            }







            try { System.IO.File.WriteAllText(_stageJsonFilePath, root.ToString(Newtonsoft.Json.Formatting.Indented)); } catch { }







            Console.WriteLine($"[PROP-DEBUG] Saved prop positions to {_stageJsonFilePath}");







        }







        catch (Exception ex)







        {







            Console.WriteLine($"[PROP-DEBUG] Save failed: {ex.Message}");







        }







    }















    private void UpdatePhillyBlazinLightning(float delta)















    {















        if (!_isPhillyBlazinStage)















            return;































        _phillyBlazinLightningTimer -= delta;















        _phillyBlazinLightningFadeTimer = Math.Max(0f, _phillyBlazinLightningFadeTimer - delta);















        _phillyBlazinLightningShortFadeTimer = Math.Max(0f, _phillyBlazinLightningShortFadeTimer - delta);































        if (_phillyBlazinLightningTimer <= 0f)















        {















            _phillyBlazinLightningTimer = 7f + (float)_random.NextDouble() * 8f;















            _phillyBlazinLightningFadeTimer = 1.5f;















            _phillyBlazinLightningShortFadeTimer = 0.3f;































            if (_phillyBlazinLightningIndex >= 0)















            {















                var lightning = _animatedProps[_phillyBlazinLightningIndex];















                lightning.Alpha = 1f;















                if (lightning.Sprite?.Sheet != null)















                {















                    if (lightning.Sprite.Sheet.Animations.ContainsKey("strike"))















                        lightning.Sprite.PlayAnimation("strike", force: true, loop: false);















                    else















                    {















                        string anim = lightning.Sprite.Sheet.Animations.Keys.FirstOrDefault();















                        if (!string.IsNullOrEmpty(anim))















                            lightning.Sprite.PlayAnimation(anim, force: true, loop: false);















                    }















                }















                _animatedProps[_phillyBlazinLightningIndex] = lightning;















            }































            if (_phillyBlazinSkyAdditiveIndex >= 0)















            {















                var sky = _staticProps[_phillyBlazinSkyAdditiveIndex];















                sky.Alpha = 0.7f;















                _staticProps[_phillyBlazinSkyAdditiveIndex] = sky;















            }































            if (_phillyBlazinForegroundMultiplyIndex >= 0)















            {















                var fg = _staticProps[_phillyBlazinForegroundMultiplyIndex];















                fg.Alpha = 0.64f;















                _staticProps[_phillyBlazinForegroundMultiplyIndex] = fg;















            }































            if (_phillyBlazinAdditionalLightenIndex >= 0)















            {















                var add = _staticProps[_phillyBlazinAdditionalLightenIndex];















                add.Alpha = 0.3f;















                _staticProps[_phillyBlazinAdditionalLightenIndex] = add;















            }















        }































        if (_phillyBlazinSkyAdditiveIndex >= 0)















        {















            var sky = _staticProps[_phillyBlazinSkyAdditiveIndex];















            if (_phillyBlazinLightningFadeTimer <= 0f)















                sky.Alpha = 0f;















            _staticProps[_phillyBlazinSkyAdditiveIndex] = sky;















        }































        if (_phillyBlazinForegroundMultiplyIndex >= 0)















        {















            var fg = _staticProps[_phillyBlazinForegroundMultiplyIndex];















            if (_phillyBlazinLightningFadeTimer <= 0f)















                fg.Alpha = 0f;















            _staticProps[_phillyBlazinForegroundMultiplyIndex] = fg;















        }































        if (_phillyBlazinAdditionalLightenIndex >= 0)















        {















            var add = _staticProps[_phillyBlazinAdditionalLightenIndex];















            if (_phillyBlazinLightningShortFadeTimer <= 0f)















                add.Alpha = 0f;















            _staticProps[_phillyBlazinAdditionalLightenIndex] = add;















        }































        if (_phillyBlazinLightningIndex >= 0)















        {















            var lightning = _animatedProps[_phillyBlazinLightningIndex];















            if (_phillyBlazinLightningFadeTimer <= 0f)















                lightning.Alpha = 0f;















            _animatedProps[_phillyBlazinLightningIndex] = lightning;















        }















    }















    















    private void UpdateTankmanStage(float delta)















    {















        if (!_isTankmanStage)















            return;















        















        // Scroll clouds (original: FlxTiledSprite with velocity.x = 8)















        if (_tankCloudsIndex >= 0)















        {















            var clouds = _staticProps[_tankCloudsIndex];















            TankCloudsUpdate(delta); // tankmanBattlefield.hxc: the tiled tankClouds strip moves right 8 px/s; clouds2 is static















            _staticProps[_tankCloudsIndex] = clouds;















        }















        















        // Move tank in circular path (original: tankmanBattlefield.hxc moveTank)















        if (_tankRollingIndex >= 0)















        {















            _tankAngle += delta * _tankSpeed;















            var tankRolling = _animatedProps[_tankRollingIndex];















            float angleRad = (_tankAngle + 180f) * MathF.PI / 180f;















            float x = _tankX + MathF.Cos(angleRad) * 1500f;















            float y = 1300f + MathF.Sin(angleRad) * 1100f;















            tankRolling.Sprite.Position = new Vector2(x, y);















            tankRolling.Sprite.Rotation = (_tankAngle - 75f) * MathF.PI / 180f;















        }















    }















    















    private void InitStressTankmen()







    {







        _stressTankmen.Clear(); _tmSlotCount = 0; _tmMarker = 0; for (int q = 0; q < 4; q++) _tmSlots[q] = -1;







        if (_chart?.Notes == null) return;















        // Get picospeaker notes from the chart's extra difficulties







        // In the original, notes come from 'picospeaker' difficulty







        List<Note> picospeakerNotes = new();







        // Strip difficulty suffixes to find base chart (e.g., stress_erect -> stress)







        // Build possible chart folder names from _songName (e.g., "Stress (Pico Mix)" -> "stress_pico")







        var possibleFolderNames = new List<string>();







        if (!string.IsNullOrEmpty(_songName))







        {







            string raw = _songName.Trim();







            possibleFolderNames.Add(raw);







            possibleFolderNames.Add(raw.ToLowerInvariant());







            // "Stress (Pico Mix)" -> "stress_pico"







            string noSpaces = raw.ToLowerInvariant().Replace(" ", "").Replace("(", "").Replace(")", "");







            possibleFolderNames.Add(noSpaces);







            // "Stress (Pico Mix)" -> "stress_pico" by replacing "(" with "_" and removing ") mix"







            string normalized = raw.ToLowerInvariant()







                .Replace(" (", "_").Replace(")", "")







                .Replace(" ", "_");







            if (!possibleFolderNames.Contains(normalized))







                possibleFolderNames.Add(normalized);







            // Strip difficulty suffixes







            foreach (var sfx in new[] { "_erect", "_pico", "_bf", "_hard", "_normal", "_easy" })







            {







                if (normalized.EndsWith(sfx))







                {







                    string stripped = normalized[..^sfx.Length];







                    if (!possibleFolderNames.Contains(stripped))







                        possibleFolderNames.Add(stripped);







                    break;







                }







            }







        }







        try







        {







            string foundPath = null;







            foreach (var folder in possibleFolderNames)







            {







                // Use the engine asset resolver (absolute content path). The process working







                // directory is the bin folder, so a relative "Content/..." path never matches.







                string resolved = Assets.ResolvePath($"songs/{folder}/charts/chart.json");







                if (resolved != null && global::FNF_MonoGame.Engine.FsCI.FileExists(resolved))







                {







                    foundPath = resolved;







                    Console.WriteLine($"[STRESS-INIT] Found picospeaker chart at {resolved}");







                    break;







                }







            }







            if (foundPath != null)







            {







                var json = Newtonsoft.Json.Linq.JObject.Parse(global::FNF_MonoGame.Engine.FsCI.ReadAllText(foundPath));







                var notesToken = json["notes"]?["picospeaker"];







                if (notesToken != null)







                {







                    foreach (var n in notesToken)







                    {







                        double t = n["t"]?.ToObject<double>() ?? 0;







                        int d = n["d"]?.ToObject<int>() ?? 0;







                        picospeakerNotes.Add(new Note { Time = t / 1000.0, Lane = d });







                    }







                }







            }







            else







            {







                Console.WriteLine($"[STREET-DEBUG] Picospeaker chart not found. Tried: {string.Join(", ", possibleFolderNames.Select(f => $"Content/songs/{f}/charts/chart.json"))}");







            }







        }







        catch (Exception ex)







        {







            Console.WriteLine($"[STREET-DEBUG] Failed to parse picospeaker notes: {ex.Message}");







            try { File.AppendAllText("tankman_debug.log", $"[{DateTime.Now:HH:mm:ss}] Failed to parse picospeaker notes: {ex.Message}\n"); } catch { }







        }















        Console.WriteLine($"[STREET-DEBUG] picospeaker notes: {picospeakerNotes.Count}");







        try { File.AppendAllText("tankman_debug.log", $"[{DateTime.Now:HH:mm:ss}] picospeaker notes: {picospeakerNotes.Count} for song={_songName}\n"); } catch { }















        // Speaker GF (otis-speaker/pico-speaker) shoots on EVERY picospeaker note.







        // NOTE: the GF is created AFTER this runs, so detection happens lazily in UpdateSpeakerShoot.







        _speakerShootQueue.Clear();







        _speakerShootIndex = 0;







        _speakerGfChecked = false;







        _hasSpeakerGf = false;







        foreach (var note in picospeakerNotes)







            _speakerShootQueue.Add((note.Time, note.Lane));







        _speakerShootQueue.Sort((a, b) => a.Time.CompareTo(b.Time));







        Console.WriteLine($"[STREET-DEBUG] Speaker shoot queue: {_speakerShootQueue.Count}");















        StressTankmenBuild(picospeakerNotes); // TankmanSpriteGroup.initTimemap (PlayScene.Tank.cs)















        Console.WriteLine($"[STRESS-INIT] Stress tankmen initialized: {_stressTankmen.Count} (picospeaker notes={picospeakerNotes.Count})");







        try { File.AppendAllText("tankman_debug.log", $"[{DateTime.Now:HH:mm:ss}] Stress tankmen initialized: {_stressTankmen.Count}\n"); } catch { }







    }















    // Speaker GF (otis-speaker/pico-speaker) plays shoot1-4 on each picospeaker note.







    // Original: otis-speaker.hxc shifts shootTimes when songPosition passes them. dir->anim:







    // 0=shoot1, 1=shoot2, 2=shoot3, 3=shoot4.







    private AnimatedSprite _speakerMuzzleFlash;







    private void UpdateSpeakerShoot(float delta, bool preloadOnly = false)







    {







        if ((_speakerShootQueue.Count == 0 && !preloadOnly) || _girlfriend == null) return;







        if (!_speakerGfChecked)







        {







            _speakerGfChecked = true;







            string gfName = _girlfriend.OriginalName?.ToLower() ?? "";







            _hasSpeakerGf = gfName.Contains("speaker");







            if (_hasSpeakerGf)







            {







                // Load muzzle flash spritesheet (original: Paths.getSparrowAtlas("characters/otis/muzzle-flashes/otis_flashes","shared"))







                var muzzleSheet = SpriteSheet.Load(Game, "images/characters/otis/muzzle-flashes/otis_flashes")







                    ?? SpriteSheet.Load(Game, "game/characters/otis/muzzle-flashes/otis_flashes");







                if (muzzleSheet != null)







                {







                    _speakerMuzzleFlash = new AnimatedSprite { Sheet = muzzleSheet };







                    _speakerMuzzleFlash.Scale = new Vector2(_girlfriend.Scale, _girlfriend.Scale);







                    _speakerMuzzleFlash.Tint = new Color(255, 255, 255, 0); // hidden until shoot







                    _animatedProps.Add(new AnimatedStageProp







                    {







                        Sprite = _speakerMuzzleFlash,







                        ZIndex = _gfZIndex - 1,







                        Alpha = 0f,







                        ScrollX = 1f,







                        ScrollY = 1f,







                        DanceEvery = 0,







                        LastDanceBeat = -1,







                        Name = "speakerMuzzleFlash"







                    });







                    Console.WriteLine($"[STREET-DEBUG] Loaded muzzle flash for speaker GF");







                }







            }







            Console.WriteLine($"[STREET-DEBUG] Speaker GF check: '{gfName}' hasSpeaker={_hasSpeakerGf}");







        }







        if (!_hasSpeakerGf || preloadOnly) return;







        double songPos = _conductor.SongPosition;







        while (_speakerShootIndex < _speakerShootQueue.Count &&







               _speakerShootQueue[_speakerShootIndex].Time <= songPos)







        {







            int dir = _speakerShootQueue[_speakerShootIndex].Dir; if (_girlfriend?.Name != null && _girlfriend.Name.StartsWith("pico-speaker")) dir = dir == 3 ? dir - _speakerRng.Next(0, 2) : dir + _speakerRng.Next(0, 2); // pico-speaker.hxc onUpdate: FlxG.random.int(0, 1)







            _speakerShootIndex++;







            string anim = dir switch







            {







                0 => "shoot1",







                1 => "shoot2",







                2 => "shoot3",







                3 => "shoot4",







                _ => "shoot1"







            };







            _girlfriend.PlayAnimation(anim, force: true);







            Console.WriteLine($"[SPEAKER-SHOOT] Playing anim='{anim}' on gf='{_girlfriend?.Name}' currentAnim='{_girlfriend?.CurrentAnimation}'");







            // Position and show muzzle flash (original otis-speaker.hxc playPicoAnimation)







            if (_speakerMuzzleFlash?.Sheet != null)







            {







                // Original prefix mappings: shoot1->"shoot back0", shoot2->"shoot back low0", shoot3->"shoot forward0", shoot4->"shoot forward low0"







                string muzzlePrefix = dir switch







                {







                    0 => "shoot back0",







                    1 => "shoot back low0",







                    2 => "shoot forward0",







                    3 => "shoot forward low0",







                    _ => "shoot back0"







                };







                var muzzleFrames = _speakerMuzzleFlash.Sheet.GetAnimationFuzzy(muzzlePrefix);







                if (muzzleFrames != null && muzzleFrames.Count > 0)







                {







                    // Use the actual animation key from the sheet







                    string muzzleKey = _speakerMuzzleFlash.Sheet.Animations.FirstOrDefault(k => k.Value == muzzleFrames).Key ?? muzzlePrefix;







                    _speakerMuzzleFlash.PlayAnimation(muzzleKey, force: true, loop: false);







                    _speakerMuzzleFlash.Tint = Color.White;







                    // HaxeFlixel this.x/this.y = CornerPosition (includes globalOffsets)







                    float gfX = _girlfriend.CornerPosition.X;







                    float gfY = _girlfriend.CornerPosition.Y;







                    Vector2 muzzlePos = dir switch







                    {







                        0 => new Vector2(gfX + 950f * _girlfriend.Scale, gfY),







                        1 => new Vector2(gfX + 950f * _girlfriend.Scale, gfY - 50f * _girlfriend.Scale),







                        2 => new Vector2(gfX - 350f * _girlfriend.Scale, gfY - 50f * _girlfriend.Scale),







                        3 => new Vector2(gfX - 350f * _girlfriend.Scale, gfY - 100f * _girlfriend.Scale),







                        _ => new Vector2(gfX + 950f * _girlfriend.Scale, gfY)







                    };







                    _speakerMuzzleFlash.Position = muzzlePos;







                    Console.WriteLine($"[STREET-DEBUG] Muzzle flash {muzzleKey} at ({muzzlePos.X:0},{muzzlePos.Y:0}) dir={dir}");







                }







            }







        }







        // Hide muzzle flash when animation finishes (original updateMuzzle: visible = !finished)







        if (_speakerMuzzleFlash != null && _speakerMuzzleFlash.Finished && _speakerMuzzleFlash.Tint.A > 0)







            _speakerMuzzleFlash.Tint = new Color(255, 255, 255, 0);







    }















    private void UpdateStressTankmen(float delta)







    {







        if (!_isStressSong || _tankmanStressSheet == null) return;















        float songPosMs = (float)(_tmPosOverrideMs ?? _conductor.SongPosition * 1000.0); _tmNowMs = songPosMs; // countdown: V-Slice songPosition runs from -5 beats







        float cutoff = songPosMs + 3000f; // create tankmen 3 seconds in advance















        for (int i = 0; i < _stressTankmen.Count; i++)







        {







            var tm = _stressTankmen[i];







            if (tm.IsDead) continue;















            // Create sprite if not yet created and within cutoff







            if (tm.Sprite == null && tm.StrumTime <= cutoff)







            {







                tm.Sprite = new AnimatedSprite { Sheet = _tankmanStressSheet, UseTimelineAnchoring = true }; // flixel-animate timeline box (1254x856)
                StressTankmanSpawn(ref tm, i); // FlxTypedSpriteGroup maxSize 4 recycle + tankmanDirs.shift() + per-object Shot 1/2







                // Original TankmanSpriteGroup.createTankman: scale.set(scale) where







                // scale = isErect ? 1.10 : 1.0 (this OVERRIDES the constructor's setGraphicSize(0.4)).







                float armyScale = _isTankmanErect ? 1.10f : 1.0f;







                tm.Sprite.Scale = new Vector2(armyScale, armyScale);







                tm.YPos = _isTankmanErect ? 350f : 200f + _random.Next(50, 101); // FlxG.random.int(50,100) is inclusive







                // Original TankmanSprite: flipX = !goingRight (sprite faces left by default;







                // flip when running leftward). MonoGame had this inverted -> ran backwards.







                tm.Sprite.Effects = tm.GoingRight ? SpriteEffects.None : SpriteEffects.FlipHorizontally;















                // Start run animation from random frame







                if (_tankmanStressSheet.Animations.ContainsKey("Running"))







                {







                    var runFrames = _tankmanStressSheet.Animations["Running"];







                    int startFrame = _random.Next(runFrames.Count);







                    tm.Sprite.PlayAnimationFromFrame("Running", startFrame, loop: true, loopFrame: 0);







                }







                else if (_tankmanStressSheet.Animations.Count > 0)







                {







                    tm.Sprite.PlayAnimation(_tankmanStressSheet.Animations.Keys.First(), loop: true);







                }















                Console.WriteLine($"[STREET-DEBUG] Spawned tankman strumTime={tm.StrumTime} goingRight={tm.GoingRight}");







                try { File.AppendAllText("tankman_debug.log", $"[{DateTime.Now:HH:mm:ss}] Spawned tankman strumTime={tm.StrumTime} goingRight={tm.GoingRight}\n"); } catch { }







            }















            if (tm.Sprite == null) continue;















            // Update position while running







            string currentAnim = tm.Sprite.CurrentAnimation ?? "";







            bool isRunning = currentAnim.Contains("Running", StringComparison.OrdinalIgnoreCase);















            if (isRunning)







            {







                // Position the tankman at target position, then offset based on time until strum







                // Original: runFactor = ((songPosition - strumTime) * runSpeed) [negative before strum]







                // !goingRight: x = target + runFactor (comes from left, runFactor < 0)







                // goingRight: x = target - runFactor (comes from right, runFactor < 0 -> -runFactor > 0)







                float runFactor = (songPosMs - tm.StrumTime) * tm.RunSpeed;







                float targetX = tm.GoingRight







                    ? (1280f * 0.74f + tm.EndingOffset)







                    : (1280f * 0.02f - tm.EndingOffset);







                if (!tm.GoingRight)







                    tm.Sprite.Position = new Vector2(targetX + runFactor, tm.YPos);







                else







                    tm.Sprite.Position = new Vector2(targetX - runFactor, tm.YPos);















                // Switch to shot animation at strum time







                if (songPosMs >= tm.StrumTime)







                {







                    if (_tankmanStressSheet.Animations.ContainsKey(tm.ShotAnim))







                        tm.Sprite.PlayAnimation(tm.ShotAnim, force: true, loop: false);







                    else







                        tm.Sprite.PlayAnimation(tm.ShotAnim, force: true, loop: false);







                    Console.WriteLine($"[STREET-DEBUG] Tankman shot at t={songPosMs} anim={tm.ShotAnim}");







                }







            }







            else







            {







                // Shot animation: two-phase death flicker at frame 10 (original TankmanSprite)







                if (tm.Sprite.FrameIndex >= 10 && tm.DeathFlickerPhase == 0)







                {







                    tm.DeathTimer = 0f; // elapsed time in seconds







                    tm.DeathFlickerPhase = 1;







                    Console.WriteLine($"[STREET-DEBUG] Tankman death flicker phase 1 started");







                }















                if (tm.DeathFlickerPhase > 0)







                {







                    tm.DeathTimer += delta; // count up elapsed seconds







                    int loops = (tm.DeathFlickerPhase == 1) ? 2 : 5; // FlxFlicker: FlxTimer loops = Std.int(0.3 / interval) = Std.int(2.9999..) = 2, Std.int(5.9999..) = 5







                    float interval = (tm.DeathFlickerPhase == 1) ? 0.1f : 0.05f;







                    bool endVisible = (tm.DeathFlickerPhase == 1); // phase1 ends visible, phase2 ends invisible















                    int ticks = (int)(tm.DeathTimer / interval + 1e-4f); if (ticks < loops)







                    {







                        // FlxFlicker keeps the current visibility (visible) for the first interval, then toggles on every tick







                        int toggleCount = ticks;







                        bool visible = (toggleCount % 2) == 0;







                        tm.Sprite.Tint = visible ? Color.White : new Color(255, 255, 255, 0);







                    }







                    else if (tm.DeathFlickerPhase == 1)







                    {







                        // Phase 1 complete -> visible at end, then start phase 2







                        tm.Sprite.Tint = Color.White;







                        tm.DeathTimer = 0f;







                        tm.DeathFlickerPhase = 2;







                        Console.WriteLine($"[STREET-DEBUG] Tankman death flicker phase 2 started");







                    }







                    else







                    {







                        // Phase 2 complete -> invisible at end, then kill







                        tm.Sprite.Tint = new Color(255, 255, 255, 0);







                        tm.IsDead = true;







                    }







                }







            }















            tm.Sprite.Update(delta); if (s_tmLog && !tm.IsDead && (tm.Sprite.CurrentAnimation ?? "").StartsWith("Shot")) Console.WriteLine($"[TANKSHOT] t={songPosMs:0} st={tm.StrumTime:0} f={tm.Sprite.FrameIndex} vis={tm.Sprite.Tint.A != 0} {tm.ShotAnim}");







            _stressTankmen[i] = tm;







        }







    }















    private float _tankmanDebugLogTimer;







    private bool _loggedStressAnchor;







    private void DrawStressTankmen(SpriteBatch spriteBatch)







    {







        if (!_isStressSong) return;







        int drawn = 0;







        Vector2 firstWorld = Vector2.Zero, firstScreen = Vector2.Zero;







        string firstAnim = "";







        foreach (var tm in _stressTankmen)







        {







            if (tm.IsDead || tm.Sprite == null || tm.Sprite.Tint.A == 0) continue;







            var flxPos = TankmanFlxDrawPos(tm.Sprite);
            var screenPos = WorldToScreen(flxPos.X, flxPos.Y, 1f, 1f);







            if (drawn == 0)







            {







                firstWorld = tm.Sprite.Position; firstScreen = screenPos; firstAnim = tm.Sprite.CurrentAnimation ?? "";







                if (!_loggedStressAnchor)







                {







                    _loggedStressAnchor = true;







                    var co = tm.Sprite.GetCompositeOrigin();







                    Console.WriteLine($"[STRESS-ANCHOR] anim='{firstAnim}' compOrigin={(co.HasValue ? $"({co.Value.X:0},{co.Value.Y:0})" : "null")} frameW={tm.Sprite.GetFrameWidth()} frameH={tm.Sprite.GetFrameHeight()} scale={tm.Sprite.Scale.X:0.00} x={tm.Sprite.Position.X:F2},{tm.Sprite.Position.Y:F2} box={flxPos.X:F2},{flxPos.Y:F2} tb={_tankmanStressSheet.GetTimelineBounds(tm.Sprite.ResolvedAnimName ?? "Running")}");







                }







            }







            var origPos = tm.Sprite.Position;







            tm.Sprite.Position = screenPos;







            bool tmRim = _isTankmanErect && BeginSpriteRim(spriteBatch, TankmenRim, tm.Sprite); // TankmanSprite.addRimlight (erect)
            tm.Sprite.Draw(spriteBatch);
            EndSpriteRim(spriteBatch, tm.Sprite, tmRim);







            tm.Sprite.Position = origPos;







            drawn++;







        }







        _tankmanDebugLogTimer += 1f / 60f;







        if (_tankmanDebugLogTimer >= 2f)







        {







            _tankmanDebugLogTimer = 0f;







            int totalAlive = _stressTankmen.Count(t => !t.IsDead);







            Console.WriteLine($"[STRESS-DRAW] drawn={drawn} alive={totalAlive} total={_stressTankmen.Count} firstAnim='{firstAnim}' world=({firstWorld.X:0},{firstWorld.Y:0}) screen=({firstScreen.X:0},{firstScreen.Y:0}) camW=({_camWorldX:0},{_camWorldY:0}) zoom={_defaultCamZoom * _cameraBopMultiplier:0.00}");







        }







    }















    















    /// <summary>















    /// Convert a world-space position to screen-space using HaxeFlixel camera model.















    /// In HaxeFlixel: camera.scroll = top-left of view in world space.















    /// Object screen pos = worldPos - camera.scroll * scrollFactor.















    /// Camera.scroll = cameraTarget - screenSize / (2 * zoom).















    /// </summary>















    public Vector2 WorldToScreen(float worldX, float worldY, float scrollX = 1f, float scrollY = 1f)















    {















        float zoom = _defaultCamZoom * _cameraBopMultiplier;















        // Camera center in world space, scroll = top-left offset by zoom















        float camScrollX = _camWorldX - 1280 / (2f * zoom);















        float camScrollY = _camWorldY - 720 / (2f * zoom);















        // World position offset by camera scroll * parallax, zoom applied by SpriteBatch matrix















        // FlxCamera (tile render): screen = (world - scroll*sf - W/2)*zoom + W/2 with scroll = center - W/2.
        // Pre-zoom (this matrix scales from the origin): world - scroll*sf - W/2 + W/(2*zoom).
        // Identical to the old formula for sf = 1; parallax props (sf != 1) were off by (1-zoom)(1-sf)*W/2.
        float sx = worldX - (_camWorldX - 640f) * scrollX - 640f + 640f / zoom;















        float sy = worldY - (_camWorldY - 360f) * scrollY - 360f + 360f / zoom;















        return new Vector2(sx, sy);















    }















    















    private void DrawCountdown(SpriteBatch spriteBatch)















    { if (NsCountdownDraw(spriteBatch, Math.Clamp(_w5HudAlpha, 0f, 1f))) return;















        if (_countdownDisplayTimer <= 0) return;















        















        float beatDuration = (float)_conductor.Crochet;















        // Original: alpha tweens from 1 to 0 over one beat















        float alpha = Math.Clamp(_countdownDisplayTimer / beatDuration, 0f, 1f) * Math.Clamp(_w5HudAlpha, 0f, 1f); // countdownSprite.cameras = [camHUD] (Countdown.hx:240): camHUD.alpha applies















        















        Texture2D tex = _countdownText switch















        {















            "READY" => _readyTex,















            "SET" => _setTex,















            "GO!" => _goTex,















            _ => null















        };















        















        if (tex != null && tex != Assets.Pixel)















        {















            // Original: setGraphicSize(Std.int(width * 0.65)), screenCenter















            int w = (int)(tex.Width * 0.65f);















            int h = (int)(tex.Height * 0.65f);















            spriteBatch.Draw(tex, 















                new Rectangle(1280 / 2 - w / 2, 720 / 2 - h / 2, w, h), 















                Color.White * alpha);















        }















        else















        {















            // Fallback: use AlphabetFont bitmap letters (like original)















            var alphabetFont = AlphabetFont.Bold;















            if (alphabetFont != null)















            {















                float abScale = 1.0f;















                float w = alphabetFont.MeasureWidth(_countdownText, abScale);















                alphabetFont.DrawString(spriteBatch, _countdownText,















                    new Vector2(1280 / 2 - w / 2, 720 / 2 - alphabetFont.MaxHeight * abScale / 2),















                    Color.White * alpha, abScale);















            }















            else















            {















                var font = Assets.GetFont(48);















                if (font != null)















                {















                    var size = font.MeasureString(_countdownText);















                    font.DrawText(spriteBatch, _countdownText,















                        new Vector2(1280 / 2 - size.X / 2, 720 / 2 - size.Y / 2),















                        Color.White * alpha);















                }















            }















        }















    }















    















    private void DrawNoteField(SpriteBatch spriteBatch)















    { if (VsStrumActive) return; /* V-Slice strumlines: PlayScene.VSliceStrumline.cs (drawn after the HUD) */ if (PsychNotes && !_psychStartedCountdown) return; // Psych: strums are created in startCountdown (generateStaticArrows)















        int strumY = _downscroll ? (FNFGame.SCREEN_HEIGHT - STRUMLINE_Y_OFFSET - STRUMLINE_SIZE) : STRUMLINE_Y_OFFSET;















        int noteSize = STRUMLINE_SIZE;















        int laneSpacing = NOTE_SPACING;















        















        int playerStartX, opponentStartX;















        if (_middlescroll)















        {















            // Middlescroll: player strumline centered, opponent hidden















            playerStartX = FNFGame.SCREEN_WIDTH / 2 - (4 * laneSpacing) / 2;















            opponentStartX = -9999; // offscreen















        }















        else















        {















            playerStartX = FNFGame.SCREEN_WIDTH / 2 + StrumXOffset;















            opponentStartX = StrumXOffset;















        }















        















        DrawNoteUnderlay(spriteBatch, playerStartX, laneSpacing); // Draw opponent strumline (left side) � hidden in middlescroll















        if (!_middlescroll)















        {















            for (int i = 0; i < 4; i++)















            {















                var oppMod = StrumMods[i];
                if (!oppMod.Visible || oppMod.Alpha <= 0.01f) continue;
                int x = opponentStartX + i * laneSpacing + (int)oppMod.OffsetX;
                int oppY = strumY + (int)oppMod.OffsetY;















                DrawReceptor(spriteBatch, x, oppY, noteSize, i, false);















            }















        }















        















        // Draw player strumline (right side, or center in middlescroll)















        for (int i = 0; i < 4; i++)















        {















            var plrMod = StrumMods[i + 4];
            if (!plrMod.Visible || plrMod.Alpha <= 0.01f) continue;
            int x = playerStartX + i * laneSpacing + (int)plrMod.OffsetX;
            int plrY = strumY + (int)plrMod.OffsetY;















            DrawReceptor(spriteBatch, x, plrY, noteSize, i, true);















        }































        if (_countdownActive) return; // Don't draw notes during countdown















        















        // Pre-compute scroll factor (avoids 4 multiplications per note)















        // Downscroll: notes come from top, scroll down to strumline at bottom (negate offset)















        float scrollFactor = PIXELS_PER_MS * 1000 * SCROLL_SPEED * _chart.Speed;















        if (_downscroll) scrollFactor = -scrollFactor;















        double songPos = _conductor.SongPosition;















        















        // Draw falling notes















        var visibleNotes = _noteField.GetVisibleNotes(songPos);















        for (int ni = 0; ni < visibleNotes.Count; ni++)















        {















            var note = visibleNotes[ni];
            float noteAlpha = (note?.Alpha * note?.MultAlpha ?? 1f) * PsychStrumAlphaFor(note); // Psych copyAlpha: strum.alpha * multAlpha















            float timeDiff = (float)(note.Time - songPos);















            float yOffset = timeDiff * scrollFactor;















            















            bool isPlayerNote = note.IsPlayerNote;















            















            // In middlescroll, skip drawing opponent notes















            if (_middlescroll && !isPlayerNote) continue;















            















            int startX = isPlayerNote ? playerStartX : opponentStartX;















            int lane = note.Lane % 4;















            















            var laneMod = StrumMods[lane + (isPlayerNote ? 4 : 0)];
            int x = startX + lane * laneSpacing + (int)laneMod.OffsetX;















            int y = strumY + (int)yOffset + (int)laneMod.OffsetY;

            note.Position = new Vector2(x, y);















            















            // For hit hold notes: note head stays at strumline, sustain shrinks from top















            bool headConsumed = note.IsHit && note.SustainLength > 0;
            // Original Strumline: a hit hold is clipped at the strumline only once songPosition > strumTime;
            // before that (early hit) the trail keeps rendering at its normal scrolled position.
            bool isActiveHold = headConsumed && songPos > note.Time;















            if (isActiveHold)















            {















                y = strumY; // Pin note head to strumline















            }















            















            // Draw sustain/hold tail first (behind note head)















            if (note.SustainLength > 0)















            {















                float sustainPixels = (float)(note.SustainLength * Math.Abs(scrollFactor));















                int sustainWidth = noteSize / 4;















                int sustainEndHeight = noteSize / 4;















                int sustainTop, sustainBottom;















                















                if (_downscroll)















                {















                    // Downscroll: sustain extends UPWARD from note















                    sustainBottom = y + noteSize / 2;















                    sustainTop = y + noteSize / 2 - (int)sustainPixels;















                    















                    if (isActiveHold)















                    {















                        sustainBottom = strumY + noteSize / 2;















                        float remainingSustain = (float)((note.Time + note.SustainLength) - songPos);















                        remainingSustain = Math.Max(0, remainingSustain);















                        sustainTop = sustainBottom - (int)(remainingSustain * Math.Abs(scrollFactor));















                    }















                    else















                    {















                        if (!note.Missed && sustainBottom > strumY + noteSize / 2)















                            sustainBottom = strumY + noteSize / 2;















                    }















                }















                else















                {















                    // Upscroll: sustain extends DOWNWARD from note















                    sustainTop = y + noteSize / 2;















                    sustainBottom = y + noteSize / 2 + (int)sustainPixels; // trail starts at the note centre (STRUMLINE_SIZE/2) and is sustainHeight long















                















                    if (isActiveHold)















                    {















                        sustainTop = strumY + noteSize / 2;















                        float remainingSustain = (float)((note.Time + note.SustainLength) - songPos);















                        remainingSustain = Math.Max(0, remainingSustain);















                        sustainBottom = sustainTop + (int)(remainingSustain * Math.Abs(scrollFactor));















                    }















                    else















                    {















                        if (!note.Missed && sustainTop < strumY + noteSize / 2)















                            sustainTop = strumY + noteSize / 2;















                    }















                }















                















                sustainTop += (int)note.OffsetY;
                sustainBottom += (int)note.OffsetY;

                if (sustainBottom > sustainTop && sustainBottom > 0 && sustainTop < FNFGame.SCREEN_HEIGHT)















                {















                    int sustainCenterX = x + noteSize / 2 - sustainWidth / 2 + (int)note.OffsetX;















                    















                    // Compute end cap position first so body range is correct















                    // In downscroll, end cap goes at top (far end); in upscroll at bottom















                    int endY;















                    SpriteEffects endFlip;















                    if (_downscroll)















                    {















                        endY = sustainTop;















                        sustainTop += sustainEndHeight; // body starts below end cap















                        endFlip = SpriteEffects.FlipVertically;















                    }















                    else















                    {















                        endY = sustainBottom - sustainEndHeight;















                        endFlip = SpriteEffects.None;















                    }















                    















                    // Draw sustain body using cached frame















                    int bodyBottom = _downscroll ? sustainBottom : endY;















                    if (bodyBottom > sustainTop)















                    {















                        // Controller mode: draw solid colored rectangles (tinting colored arrow sprites doesn't change hue)















                        if (ButtonsFor(isPlayerNote) && lane >= 0 && lane < 4 && (PsychNotes ? PsychButtonNote(note) : true))















                        {















                            spriteBatch.Draw(Assets.Pixel, 















                                new Rectangle(sustainCenterX, sustainTop, sustainWidth, bodyBottom - sustainTop), 















                                GetControllerLaneColor(lane) * 0.85f * (noteAlpha * HoldTrailMul));















                        }















                        else















                        {















                            var sFrame = _sustainFrames[lane];















                            if (PsychDrawSustain(spriteBatch, note, lane, x + (int)note.OffsetX, sustainTop, bodyBottom, false, _downscroll ? SpriteEffects.FlipVertically : SpriteEffects.None, noteAlpha * HoldTrailMul)) { } else if (sFrame != null && _notesSheet?.Texture != null)















                            {















                                spriteBatch.Draw(_notesSheet.Texture, 















                                    new Rectangle(sustainCenterX, sustainTop, sustainWidth, bodyBottom - sustainTop), 















                                    sFrame.SourceRect, Color.White * (noteAlpha * HoldTrailMul));















                            }















                            else















                            {















                                Color laneColor = lane switch















                                {















                                    0 => Color.Purple,















                                    1 => Color.Cyan,















                                    2 => Color.LimeGreen,















                                    3 => Color.Red,















                                    _ => Color.Magenta















                                };















                                spriteBatch.Draw(Assets.Pixel, 















                                    new Rectangle(sustainCenterX, sustainTop, sustainWidth, bodyBottom - sustainTop), 















                                    laneColor * 0.6f * (noteAlpha * HoldTrailMul));















                            }















                        }















                    }































                    // Draw sustain end cap















                    if (endY >= 0 && endY < FNFGame.SCREEN_HEIGHT)















                    {















                        // Controller mode: solid colored end cap (same color as body)















                        if (ButtonsFor(isPlayerNote) && lane >= 0 && lane < 4 && (PsychNotes ? PsychButtonNote(note) : true))















                        {















                            spriteBatch.Draw(Assets.Pixel,















                                new Rectangle(sustainCenterX, endY, sustainWidth, sustainEndHeight),















                                GetControllerLaneColor(lane) * 0.85f * (noteAlpha * HoldTrailMul));















                        }















                        else















                        {















                            var eFrame = _sustainEndFrames[lane];















                            if (PsychDrawSustain(spriteBatch, note, lane, x + (int)note.OffsetX, endY, endY + sustainEndHeight, true, endFlip, noteAlpha * HoldTrailMul)) { } else if (eFrame != null && _notesSheet?.Texture != null)















                            {















                                spriteBatch.Draw(_notesSheet.Texture,















                                    new Rectangle(sustainCenterX, endY, sustainWidth, sustainEndHeight),















                                    eFrame.SourceRect, Color.White * (noteAlpha * HoldTrailMul), 0f, Vector2.Zero, endFlip, 0f);















                            }















                        }















                    }















                }















            }















            















            // Draw note head � skip if hold note already hit (head consumed, only sustain shows)















            if (!headConsumed && y > -noteSize && y < FNFGame.SCREEN_HEIGHT)















            {















                DrawNote(spriteBatch, x, y, noteSize, lane, note);















            }















        }















    }















    















    private void DrawReceptor(SpriteBatch spriteBatch, int x, int y, int size, int lane, bool isPlayer)















    {















        bool keyHeld = isPlayer && Input.NoteHeld[lane];















        // Show confirm animation if key is held OR confirm timer is active (note just hit)















        bool showConfirm = keyHeld 















            || (isPlayer && _playerConfirmTimer[lane] > 0)















            || (!isPlayer && _opponentConfirmTimer[lane] > 0);































        // Controller mode: draw Xbox button sprite centered in receptor area (medium size)















        if (ButtonsFor(isPlayer) && !PsychNotes)















        {















            var btn = Input.NoteFaceButtons[lane];















            int btnSize = (int)(size * 0.75f); // medium size � smaller than arrow but not tiny















            int bx = x + (size - btnSize) / 2;















            int by = y + (size - btnSize) / 2;















            if (ControllerNoteSkin.DrawReceptor(spriteBatch, Assets, lane, btn, new Vector2(x + size / 2f, y + size / 2f), btnSize, keyHeld && !showConfirm, showConfirm, 1f, -1f, HudArtScale)) return;
            Assets.DrawButtonReceptor(spriteBatch, btn, bx, by, btnSize,















                pressed: keyHeld, confirm: showConfirm && !keyHeld);















            return;















        }































        if (PsychDrawStrum(spriteBatch, x, y, lane, isPlayer, keyHeld, isPlayer ? _playerConfirmTimer[lane] > 0 : _opponentConfirmTimer[lane] > 0, (int)(((isPlayer ? RECEPTOR_CONFIRM_DURATION : 0.15f) - (isPlayer ? _playerConfirmTimer[lane] : _opponentConfirmTimer[lane])) * 24f))) return; // Psych default skin (PlayScene.PsychDefaultSkin.cs)
        if (_receptorsSheet?.Texture != null)















        {















            var frames = showConfirm ? _receptorConfirmFrames[lane] : _receptorStaticFrames[lane];















            if (frames != null && frames.Count > 0)















            {















                int frameIdx = showConfirm ? (_animFrame % frames.Count) : 0;















                var frame = frames[frameIdx];















                if (showConfirm)















                {















                    // Confirm frames are larger � scale to fill but center on receptor















                    // Original: confirm glow extends beyond the 112px receptor area















                    float confirmScale = (float)size / Math.Min(frame.SourceRect.Width, frame.SourceRect.Height);















                    int cw = (int)(frame.SourceRect.Width * confirmScale);















                    int ch = (int)(frame.SourceRect.Height * confirmScale);















                    int cx = x + size / 2 - cw / 2;















                    int cy = y + size / 2 - ch / 2;















                    spriteBatch.Draw(_receptorsSheet.Texture, new Rectangle(cx, cy, cw, ch), frame.SourceRect, Color.White);















                }















                else















                {















                    spriteBatch.Draw(_receptorsSheet.Texture, new Rectangle(x, y, size, size), frame.SourceRect, Color.White);















                }















                return;















            }















            // Fallback to press frames















            if (showConfirm)















            {















                var pressFrames = _receptorPressFrames[lane];















                if (pressFrames != null && pressFrames.Count > 0)















                {















                    spriteBatch.Draw(_receptorsSheet.Texture, new Rectangle(x, y, size, size), pressFrames[0].SourceRect, Color.White);















                    return;















                }















            }















        }































        // Fallback colored rectangles















        Color laneColor = lane switch















        {















            0 => Color.Purple,















            1 => Color.Cyan,















            2 => Color.LimeGreen,















            3 => Color.Red,















            _ => Color.Gray















        };















        float baseAlpha = isPlayer ? 0.6f : 0.3f;















        if (showConfirm) baseAlpha = isPlayer ? 1.0f : 0.7f;















        spriteBatch.Draw(Assets.Pixel, new Rectangle(x, y, size, size), laneColor * baseAlpha);















    }































    private void DrawNote(SpriteBatch spriteBatch, int x, int y, int size, int lane, FNF_MonoGame.Engine.PsychEngine.Note note = null)















    {















        float noteAlpha = 1f;
        float noteAngle = 0f;
        float noteScale = 1f;
        if (note != null)
        {
            x += (int)note.OffsetX;
            y += (int)note.OffsetY;
            noteAlpha = note.Alpha * note.MultAlpha;
            noteAngle = MathHelper.ToRadians(note.Angle + note.OffsetAngle);
            noteScale = note.Scale;
        } if (PsychButtonNote(note) && PsychDrawButtonNote(spriteBatch, x, y, lane, note, noteAlpha, noteAngle, noteScale)) return; if (PsychDrawNoteHead(spriteBatch, x, y, size, lane, note, noteAlpha, noteAngle, noteScale)) return; // Psych note.texture / rgbShader (PlayScene.PsychNoteSkins.cs)

        // Controller mode: draw Xbox button sprites instead of arrow notes















        if (ButtonsFor(note == null || note.IsPlayerNote) && lane >= 0 && lane < 4)















        {















            var btn = Input.NoteFaceButtons[lane];















            if (ControllerNoteSkin.DrawNote(spriteBatch, Assets, lane, btn, new Vector2(x + size / 2f, y + size / 2f), (int)(size * 0.75f) * noteScale, noteAlpha, noteAngle, HudArtScale)) return;
            var btnTex = Assets.GetButtonSprite(btn);















            if (btnTex != null)















            {















                int btnSize = (int)(size * 0.75f); // match receptor medium size















                int bx = x + (size - btnSize) / 2;















                int by = y + (size - btnSize) / 2;















                float btnScale = (btnSize / (float)btnTex.Width) * noteScale;
                spriteBatch.Draw(btnTex, new Vector2(bx + btnSize / 2f, by + btnSize / 2f), null, Color.White * noteAlpha, noteAngle, new Vector2(btnTex.Width / 2f, btnTex.Height / 2f), btnScale, SpriteEffects.None, 0f);















                return;















            }















            // Fallback: colored circle















            var (btnColor, _) = AssetManager.GetButtonInfo(btn);















            float circleScale = size * noteScale;
            spriteBatch.Draw(Assets.Pixel, new Vector2(x, y), null, btnColor * noteAlpha, noteAngle, Vector2.Zero, circleScale, SpriteEffects.None, 0f);















            return;















        }































        var frame = _noteFrames[lane];















        if (frame != null && _notesSheet?.Texture != null)















        {















            float frameScale = (size / (float)frame.SourceRect.Width) * noteScale;
            spriteBatch.Draw(_notesSheet.Texture, new Vector2(x + size / 2f, y + size / 2f), frame.SourceRect, Color.White * noteAlpha, noteAngle, new Vector2(frame.SourceRect.Width / 2f, frame.SourceRect.Height / 2f), frameScale, SpriteEffects.None, 0f);















        }















        else















        {















            Color laneColor = lane switch















            {















                0 => Color.Purple,















                1 => Color.Cyan,















                2 => Color.LimeGreen,















                3 => Color.Red,















                _ => Color.Magenta















            };















            float laneColorScale = size * noteScale;
            spriteBatch.Draw(Assets.Pixel, new Vector2(x, y), null, laneColor * noteAlpha, noteAngle, Vector2.Zero, laneColorScale, SpriteEffects.None, 0f);















        }















    }















    















    private void DrawHUD(SpriteBatch spriteBatch)















    { if (FNF_MonoGame.Engine.PsychEngine.ClientPrefs.Data.HideHud && !UsePsychHud) return; if (UsePsychHud) { DrawHudPsych(spriteBatch); return; } if (UseVSliceHud) { DrawHudVSlice(spriteBatch); return; }















        // Original: health bar at bottom in upscroll, top area in downscroll















        int healthBarY = _downscroll 















            ? (int)(FNFGame.SCREEN_HEIGHT * 0.1f) 















            : (int)(FNFGame.SCREEN_HEIGHT * 0.9f);















        















        if (_healthBarBG != null && _healthBarBG != Assets.Pixel)















        {















            int bgWidth = _healthBarBG.Width;















            int bgHeight = _healthBarBG.Height;















            int bgX = (FNFGame.SCREEN_WIDTH - bgWidth) / 2;















            spriteBatch.Draw(_healthBarBG, new Rectangle(bgX, healthBarY, bgWidth, bgHeight), Color.White * PsychHealthBarOpacity);















            















            int barWidth = bgWidth - 8;















            int barHeight = bgHeight - 8;















            int barX = bgX + 4;















            int barY = healthBarY + 4;















            















            // Character-specific colors (original FNF: opponent color on left, player on right)















            Color opponentColor = _opponent?.HealthBarColor ?? Color.Red;















            Color playerColor = _boyfriend?.HealthBarColor ?? new Color(0x31, 0xB0, 0xD1);















            















            // Opponent side (full bar)















            spriteBatch.Draw(Assets.Pixel, new Rectangle(barX, barY, barWidth, barHeight), opponentColor * PsychHealthBarOpacity);















            















            // Player side (fills from right based on health)















            float healthNorm = _healthLerp / HEALTH_MAX;















            int healthWidth = (int)(barWidth * healthNorm);















            spriteBatch.Draw(Assets.Pixel, 















                new Rectangle(barX + barWidth - healthWidth, barY, healthWidth, barHeight), 















                playerColor * PsychHealthBarOpacity);















        }















        else















        {















            int barWidth = 600;















            int barHeight = 18;















            int barX = (FNFGame.SCREEN_WIDTH - barWidth) / 2;















            















            Color opponentColor2 = _opponent?.HealthBarColor ?? Color.Red;















            Color playerColor2 = _boyfriend?.HealthBarColor ?? new Color(0x31, 0xB0, 0xD1);















            















            spriteBatch.Draw(Assets.Pixel, new Rectangle(barX - 4, healthBarY - 4, barWidth + 8, barHeight + 8), Color.Black * PsychHealthBarOpacity);















            spriteBatch.Draw(Assets.Pixel, new Rectangle(barX, healthBarY, barWidth, barHeight), opponentColor2 * PsychHealthBarOpacity);















            float healthNorm2 = _healthLerp / HEALTH_MAX;















            int healthWidth = (int)(barWidth * healthNorm2);















            spriteBatch.Draw(Assets.Pixel, new Rectangle(barX + barWidth - healthWidth, healthBarY, healthWidth, barHeight), playerColor2 * PsychHealthBarOpacity);















        }















        















        // Character icons (use cached textures)















        var bfIcon = _playerIcon;















        var opponentIcon = _opponentIcon;















        















        // Icon bounce on beat (scale from center)















        int iconBaseSize = 150;















        int iconSize = (int)(iconBaseSize * _iconBounceScale);















        int iconAreaWidth = 550;















        int iconBaseX = (FNFGame.SCREEN_WIDTH - iconAreaWidth) / 2;















        int iconSizeOffset = (iconSize - iconBaseSize) / 2;















        int iconY = healthBarY - iconSize / 2 - 5;















        float healthDisp = _healthLerp / HEALTH_MAX;















        int dividerPos = (int)(iconAreaWidth * (1 - healthDisp));















        















        // Opponent icon (original: square icon frames, width = height per frame)















        if (opponentIcon != null && opponentIcon != Assets.Pixel)















        {















            int frameW = opponentIcon.Height; // Icons are square: frame width = texture height















            int numFrames = opponentIcon.Width / Math.Max(1, frameW);















            int iconFrame;















            if (numFrames >= 3)















                iconFrame = _health > 1.6f ? 1 : (_health < 0.4f ? 2 : 0); // opponent losing/winning/normal















            else if (numFrames >= 2)















                iconFrame = _health > 1.6f ? 1 : 0; // losing/normal















            else















                iconFrame = 0;















            int oppIconX = iconBaseX + dividerPos - iconSize - 26;















            















            if (numFrames >= 2)















            {















                var srcRect = new Rectangle(iconFrame * frameW, 0, frameW, frameW);















                spriteBatch.Draw(opponentIcon, new Rectangle(oppIconX, iconY, iconSize, iconSize), srcRect, Color.White * PsychIconOpacity(2));















            }















            else















            {















                spriteBatch.Draw(opponentIcon, new Rectangle(oppIconX, iconY, iconSize, iconSize), Color.White * PsychIconOpacity(2));















            }















        }















        















        // BF icon (flipped, original: square icon frames)















        if (bfIcon != null && bfIcon != Assets.Pixel)















        {















            int frameW = bfIcon.Height; // Icons are square: frame width = texture height















            int numFrames = bfIcon.Width / Math.Max(1, frameW);















            int iconFrame;















            if (numFrames >= 3)















                iconFrame = _health < 0.4f ? 1 : (_health > 1.6f ? 2 : 0); // BF losing/winning/normal















            else if (numFrames >= 2)















                iconFrame = _health < 0.4f ? 1 : 0; // losing/normal















            else















                iconFrame = 0;















            int bfIconX = iconBaseX + dividerPos + 26;















            















            if (numFrames >= 2)















            {















                var srcRect = new Rectangle(iconFrame * frameW, 0, frameW, frameW);















                spriteBatch.Draw(bfIcon, new Rectangle(bfIconX, iconY, iconSize, iconSize), srcRect, Color.White * PsychIconOpacity(1), 0, Vector2.Zero, SpriteEffects.FlipHorizontally, 0);















            }















            else















            {















                spriteBatch.Draw(bfIcon, new Rectangle(bfIconX, iconY, iconSize, iconSize), null, Color.White, 0, Vector2.Zero, SpriteEffects.FlipHorizontally, 0);















            }















        }















        















        // Score text (matches original: centered below health bar, shows score + misses + accuracy + grade)















        float accuracy = _totalNotes > 0 ? (_totalNotesHit / (float)_totalNotes) * 100f : 0f;















        string grade = accuracy >= 100f ? "S+" : accuracy >= 95f ? "S" : accuracy >= 90f ? "A" :















                       accuracy >= 80f ? "B" : accuracy >= 70f ? "C" : accuracy >= 60f ? "D" : "F";















        string scoreText = $"Score: {_score:N0}  |  Misses: {_misses}  |  Accuracy: {accuracy:F2}% [{grade}]  |  NPS: {_nps}";















        var font = Assets.GetFont(16);















        if (font != null)















        {















            var scoreSize = font.MeasureString(scoreText);















            float scoreX = (FNFGame.SCREEN_WIDTH - scoreSize.X) / 2f;















            float scoreY = healthBarY + 30;















            // Drop shadow for readability over health bar















            font.DrawText(spriteBatch, scoreText, 















                new Vector2(scoreX + 1, scoreY + 1), Color.Black * 0.5f);















            font.DrawText(spriteBatch, scoreText, 















                new Vector2(scoreX, scoreY), Color.White);















        }















        















        // Song progress time bar (original: TimeBar at top/bottom depending on scroll)















        {















            // Use audio duration if available, fallback to chart song length















            double audioLen = Audio.MusicLength;















            float songLen = audioLen > 1 ? (float)audioLen : (float)(_chart?.SongLength ?? 180);















            if (songLen > 0)















            {















                float progress = Math.Clamp((float)_conductor.SongPosition / songLen, 0f, 1f);















                int tbW = 400;















                int tbH = 10;















                int tbX = (FNFGame.SCREEN_WIDTH - tbW) / 2;















                // Position: in downscroll at bottom, in upscroll above the score text area















                int tbY = _downscroll ? FNFGame.SCREEN_HEIGHT - 22 : 6;















                // Background















                spriteBatch.Draw(Assets.Pixel, new Rectangle(tbX - 1, tbY - 1, tbW + 2, tbH + 2), Color.Black * 0.5f);















                spriteBatch.Draw(Assets.Pixel, new Rectangle(tbX, tbY, tbW, tbH), new Color(30, 30, 30) * 0.8f);















                // Fill















                spriteBatch.Draw(Assets.Pixel, new Rectangle(tbX, tbY, (int)(tbW * progress), tbH), Color.White * 0.8f);















                // Time text centered below/above bar















                var tbFont = Assets.GetFont(12);















                if (tbFont != null)















                {















                    int elapsedSec = Math.Max(0, (int)_conductor.SongPosition);















                    int totalSec = Math.Max(0, (int)songLen);















                    string timeStr = $"{elapsedSec / 60}:{elapsedSec % 60:D2} / {totalSec / 60}:{totalSec % 60:D2}";















                    var tsz = tbFont.MeasureString(timeStr);















                    int timeTextY = _downscroll ? tbY - (int)tsz.Y - 2 : tbY + tbH + 2;















                    tbFont.DrawText(spriteBatch, timeStr,















                        new Vector2(tbX + (tbW - tsz.X) / 2, timeTextY), Color.White * 0.6f);















                }















            }















        }















        















        // Botplay indicator (original: centered, below/above strumline)















        if (_botplay)















        {















            var botFont = Assets.GetFont(32);















            if (botFont != null)















            {















                var botSize = botFont.MeasureString("BOTPLAY");















                // Place between strumline and health bar















                int botY = _downscroll ? FNFGame.SCREEN_HEIGHT - 100 : 70;















                botFont.DrawText(spriteBatch, "BOTPLAY",















                    new Vector2((FNFGame.SCREEN_WIDTH - botSize.X) / 2f, botY),















                    Color.White * 0.6f);















            }















        }































        // A-Bot debug overlay disabled







        // if (_abotDebugMode)







        // {







        //     var dbgFont = Assets.GetFont(12);







        //     if (dbgFont != null)







        //     {







        //         string text = $"ABOT DEBUG ...";







        //         dbgFont.DrawText(spriteBatch, text, new Vector2(8, 8), Color.Yellow);







        //     }







        // }















    }















    















    private void DrawRating(SpriteBatch spriteBatch)















    {















        float alpha = _ratingAlpha;















        















        // Rating position (original: FlxG.width * 0.474, ratingY has physics)















        float ratingX = FNFGame.SCREEN_WIDTH * 0.474f + _popUpOffsets.X;















        float ratingY = _ratingY + _popUpOffsets.Y;















        















        // Scale: original setGraphicSize(Std.int(width * 0.7))















        float ratingScale = 0.7f;















        















        // Draw rating image using cached textures















        Texture2D ratingTex = _lastRating switch















        {















            "SICK!!" => _ratingSickTex,















            "GOOD!" => _ratingGoodTex,















            "BAD" => _ratingBadTex,















            "SHIT" => _ratingShitTex,















            _ => null















        };















        















        bool drewImage = false;















        if (PopupShowRating && ratingTex != null && ratingTex != Assets.Pixel)















        {















            int width = (int)(ratingTex.Width * ratingScale);















            int height = (int)(ratingTex.Height * ratingScale);















            spriteBatch.Draw(ratingTex, 















                new Rectangle((int)(ratingX - width / 2), (int)ratingY, width, height), 















                PopupRatingTint(_lastRating) * alpha);















            drewImage = true;















        }















        















        if (!drewImage && PopupShowRating)















        {















            Color ratingColor = _lastRating switch















            {















                "SICK!!" => Color.Cyan,















                "GOOD!" => Color.LimeGreen,















                "BAD" => Color.Orange,















                "SHIT" => Color.Red,















                "MISS" => Color.DarkRed,















                _ => Color.White















            };















            DrawText(spriteBatch, _lastRating, 















                new Vector2(ratingX - 50, ratingY), ratingColor * alpha);















        }















        















        // Draw combo number below rating when combo >= 10 (original: if (combo >= 10) displayCombo)















        if (_lastComboDisplay >= 10 && _lastRating != "MISS" && PopupShowCombo)















        {















            DrawComboDigits(spriteBatch, _lastComboDisplay, ratingX, _comboY + _popUpOffsets.Y, _comboAlpha);















        }















    }















    















    // Reusable digit buffer to avoid per-frame List allocation















    private readonly int[] _digitBuffer = new int[10];















    















    /// <summary>















    /// Draw combo digits as individual number sprites (matches original PopUpStuff.displayCombo).















    /// Original separates the combo into individual digits and displays them.















    /// </summary>















    private void DrawComboDigits(SpriteBatch spriteBatch, int combo, float baseX, float y, float alpha)















    {















        // Separate into individual digits using reusable buffer















        int digitCount = 0;















        int temp = combo;















        while (temp > 0 && digitCount < _digitBuffer.Length)















        {















            _digitBuffer[digitCount++] = temp % 10;















            temp /= 10;















        }















        while (digitCount < 3) _digitBuffer[digitCount++] = 0;































        for (int di = 0; di < digitCount; di++)















        {















            int digit = _digitBuffer[di];















            // Guard against invalid digit value















            if (digit < 0 || digit >= 10)















                continue;































            int daLoop = di + 1;















            var numTex = _comboDigitTex[digit];















            float digitX = (FNFGame.SCREEN_WIDTH * 0.507f) - (36 * daLoop) - 65 + _popUpOffsets.X; // PopUpStuff offsets















            float digitY = y; // Use physics-driven Y from caller (original: each digit falls with gravity)































            if (numTex != null && numTex != Assets.Pixel)















            {















                float scale = 0.5f;















                int w = (int)(numTex.Width * scale);















                int h = (int)(numTex.Height * scale);















                spriteBatch.Draw(numTex, new Rectangle((int)digitX, (int)digitY, w, h), PopupComboTint() * alpha);















            }















            else if (_comboStripTex != null && _comboStripRects != null && digit >= 0 && digit < _comboStripRects.Length)















            {















                // Fallback: draw from combo.png strip (with bounds check)















                float scale = 0.5f;















                var srcRect = _comboStripRects[digit];















                int w = (int)(srcRect.Width * scale);















                int h = (int)(srcRect.Height * scale);















                spriteBatch.Draw(_comboStripTex, new Rectangle((int)digitX, (int)digitY, w, h), srcRect, PopupComboTint() * alpha);















            }















            else















            {















                // Fallback: text















                var font = Assets.GetFont(32);















                if (font != null)















                    font.DrawText(spriteBatch, digit.ToString(), new Vector2(digitX, digitY), Color.White * alpha);















            }















        }















    }















    















    /// <summary>















    /// Draw note splash effects on sick hits (original: playerStrumline.playNoteSplash)















    /// </summary>















    private void DrawNoteSplashes(SpriteBatch spriteBatch)















    { if (VsStrumActive) { DrawVsStrumlines(spriteBatch); return; }















        int playerStartX = FNFGame.SCREEN_WIDTH / 2 + StrumXOffset;















        int strumY = STRUMLINE_Y_OFFSET;















        if (_downscroll) strumY = FNFGame.SCREEN_HEIGHT - STRUMLINE_Y_OFFSET - STRUMLINE_SIZE;















        if (_middlescroll) playerStartX = FNFGame.SCREEN_WIDTH / 2 - (4 * NOTE_SPACING) / 2;















        int noteSize = STRUMLINE_SIZE; if (PsychNotes) { PsychDrawSplashes(spriteBatch, playerStartX, strumY); return; } // Psych NoteSplash (PlayScene.PsychDefaultSkin.cs)















        















        for (int i = 0; i < 4; i++)















        {















            if (_noteSplashTimer[i] > 0)















            {















                int x = playerStartX + i * NOTE_SPACING;















                float splashAlpha = _noteSplashTimer[i] / 0.3f * _psychSplashAlpha[i]; // Psych noteSplashData.a















                float splashScale = 1.5f + (1f - splashAlpha) * 0.5f;















                int splashSize = (int)(noteSize * splashScale);















                int offset = (splashSize - noteSize) / 2;















                















                // Controller mode: use button colors for splash tint















                Color splashTint = Color.White;















                if (UseControllerDisplay && i >= 0 && i < 4)















                    splashTint = GetControllerLaneColor(i);































                // Try spritesheet splash frames















                if (_splashesSheet != null)















                {















                    string laneName = _laneNames[i];















                    var frames = _splashesSheet.GetAnimation($"{laneName} splash")















                              ?? _splashesSheet.GetAnimationFuzzy($"note splash {laneName}")















                              ?? _splashesSheet.GetAnimationFuzzy($"splash {laneName}");















                    if (frames != null && frames.Count > 0)















                    {















                        int frameIdx = (int)((1f - splashAlpha) * (frames.Count - 1));















                        frameIdx = Math.Clamp(frameIdx, 0, frames.Count - 1);















                        var frame = frames[frameIdx];















                        spriteBatch.Draw(_splashesSheet.Texture,















                            new Rectangle(x - offset, strumY - offset, splashSize, splashSize),















                            frame.SourceRect, splashTint * (splashAlpha * NoteSplashMul));















                        continue;















                    }















                }































                // Fallback: colored rectangle















                Color splashColor;















                if (UseControllerDisplay && i >= 0 && i < 4)















                    splashColor = GetControllerLaneColor(i);















                else















                    splashColor = i switch















                    {















                        0 => Color.Purple,















                        1 => Color.Cyan,















                        2 => Color.LimeGreen,















                        3 => Color.Red,















                        _ => Color.White















                    };































                spriteBatch.Draw(Assets.Pixel,















                    new Rectangle(x - offset, strumY - offset, splashSize, splashSize),















                    splashColor * splashAlpha * 0.4f * NoteSplashMul);















            }















        }















    }















    















    /// <summary>















    /// Draw hold note cover glow effect while sustain notes are being held.















    /// Original: holdNoteCover sprite with start/hold/end animations per lane.















    /// </summary>















    private void DrawHoldNoteCovers(SpriteBatch spriteBatch)















    { if (VsStrumActive) return;















        int playerStartX = FNFGame.SCREEN_WIDTH / 2 + StrumXOffset;















        int strumY = STRUMLINE_Y_OFFSET;















        if (_downscroll) strumY = FNFGame.SCREEN_HEIGHT - STRUMLINE_Y_OFFSET - STRUMLINE_SIZE;















        if (_middlescroll) playerStartX = FNFGame.SCREEN_WIDTH / 2 - (4 * NOTE_SPACING) / 2;















        int noteSize = STRUMLINE_SIZE;















        















        for (int i = 0; i < 4; i++)















        {















            if (_holdingNote[i] && Input.NoteHeld[i])















            {















                _holdCoverTimer[i] += _lastDelta;















                int x = playerStartX + i * NOTE_SPACING;















                float coverAlpha = Math.Min(1f, _holdCoverTimer[i] / 0.1f);















                float coverScale = 1.3f;















                int coverSize = (int)(noteSize * coverScale);















                int offset = (coverSize - noteSize) / 2;















                















                if (_holdCoverSheet != null)















                {















                    string laneName = _laneNames[i];















                    var frames = _holdCoverSheet.GetAnimationFuzzy($"{laneName} hold")















                              ?? _holdCoverSheet.GetAnimationFuzzy($"hold {laneName}")















                              ?? _holdCoverSheet.GetAnimationFuzzy("loop");















                    if (frames != null && frames.Count > 0)















                    {















                        int frameIdx = ((int)(_holdCoverTimer[i] * 24)) % frames.Count;















                        var frame = frames[frameIdx];















                        spriteBatch.Draw(_holdCoverSheet.Texture,















                            new Rectangle(x - offset, strumY - offset, coverSize, coverSize),















                            frame.SourceRect, Color.White * (coverAlpha * HoldSplashMul));















                        continue;















                    }















                }















                















                // Fallback: colored glow rectangle (use controller button colors when active)















                Color glowColor;















                if (UseControllerDisplay && i >= 0 && i < 4)















                    glowColor = GetControllerLaneColor(i);















                else















                    glowColor = i switch















                    {















                        0 => Color.Purple,















                        1 => Color.Cyan,















                        2 => Color.LimeGreen,















                        3 => Color.Red,















                        _ => Color.White















                    };















                spriteBatch.Draw(Assets.Pixel,















                    new Rectangle(x - offset, strumY - offset, coverSize, coverSize),















                    glowColor * coverAlpha * 0.25f * HoldSplashMul);















            }















            else















            {















                _holdCoverTimer[i] = 0;















            }















        }















    }















    















    /// <summary>















    /// Build pause menu items dynamically based on current state.















    /// Matches original PAUSE_MENU_ENTRIES_STANDARD / PAUSE_MENU_ENTRIES_DIFFICULTY.















    /// </summary>















    private void BuildPauseMenuItems()
    {
        if (_pauseDifficultyMode)
        {
            // PAUSE_MENU_ENTRIES_DIFFICULTY: currentSong.listDifficulties(currentChart.variation) + Back
            var items = new List<string>();
            var diffs = _chart?.Difficulties;
            if (diffs != null && diffs.Count > 0)
                foreach (var d in diffs) items.Add(TitleCaseV(d));
            else
                items.AddRange(new[] { "Easy", "Normal", "Hard" });
            items.Add("Back");
            _pauseItems = items.ToArray();
        }
        else
        {
            var videoItems = VideoPauseItems(); // PAUSE_MENU_ENTRIES_VIDEO_CUTSCENE
            if (videoItems != null) { _pauseItems = videoItems; OnPauseItemsRebuilt(); return; }
            // PAUSE_MENU_ENTRIES_STANDARD
            var items = new List<string> { "Resume", "Restart Song", "Change Difficulty" };
            if (!_practiceMode)
                items.Add("Enable Practice Mode"); else if (!_mpActive && _replay == null) items.AddRange(PracticeItems); // practice tools (PlayScene.Practice.cs)
            if (!_mpActive) items.Add("Toggle Botplay"); // Psych PauseSubState entry (user request)
            items.Add("Exit to Menu");
            _pauseItems = items.ToArray();
        }
        OnPauseItemsRebuilt();
    }

    /// Execute the selected pause menu item by name.















    /// </summary>















    private void ExecutePauseMenuItem(string item)















    {
        if (VideoExecutePauseItem(item)) return; if (PracticeExecute(item)) return; // video cutscene entries















        switch (item)















        {















            case "Resume":















                _paused = false;
                CallOnLuas("onResume");















                Input.GameplayMode = true;















                bool isStoryModeMenu = _weekSongs != null;















                string weekNameMenu = isStoryModeMenu ? _weekId : null;















                Game.Discord?.SetResumed(_songName, _currentDifficulty, isStoryModeMenu, weekNameMenu, _practiceMode, _botplay);















                if (!_countdownActive)















                {















                    Audio.ResumeMusic();















                    _conductor.Resume();















                }















                break;















            case "Restart Song":







                Audio.StopMusic();







                Game.Scenes.ChangeScene(new PlayScene(BuildParams()));







                break;















            case "Change Difficulty":















                _pauseDifficultyMode = true;















                _pauseSelection = 0;















                BuildPauseMenuItems();















                Audio.PlaySound("scrollMenu");















                break;















            case "Back":















                // Return to standard pause menu from difficulty sub-menu















                _pauseDifficultyMode = false;















                _pauseSelection = 0;















                BuildPauseMenuItems();















                Audio.PlaySound("scrollMenu");















                break;















            case "Easy":















            case "Normal":















            case "Hard":















            case "Erect":















            case "Nightmare":















                // Change difficulty = restart song with new difficulty







                // (original: changeDifficulty ? restartPlayState with new diff)







                Audio.StopMusic();







                var diffParams = BuildParams();







                diffParams.TargetDifficulty = item.ToLowerInvariant();







                Game.Scenes.ChangeScene(new PlayScene(diffParams));















                break;















            case "Enable Practice Mode":















                _practiceMode = true;















                BuildPauseMenuItems(); // Rebuild to remove this option















                _pauseSelection = Math.Min(_pauseSelection, _pauseItems.Length - 1);















                Audio.PlaySound("confirmMenu");















                break;















            case "Toggle Botplay":
                // Psych PauseSubState: cpuControlled = !cpuControlled; changedDifficulty = true; botplayTxt.visible = cpuControlled (menu stays open)
                _botplay = !_botplay;
                if (_noteField != null) _noteField.BotPlay = _botplay;
                _botplayToggledV = true;
                Console.WriteLine($"[PAUSE] botplay -> {_botplay}");
                break;
            case "Enable Botplay":















            case "Disable Botplay":















                _botplay = !_botplay;















                BuildPauseMenuItems();















                _pauseSelection = Math.Min(_pauseSelection, _pauseItems.Length - 1);















                Audio.PlaySound("confirmMenu");















                break;















            case "Exit to Menu":
                // PauseSubState.quitToMenu: StickerSubState over the pause menu, then StoryMenuState / FreeplayState(stickers)
                if (StickerTransition.Active) break;
                Audio.StopMusic();
                {
                    bool toStory = _weekId != null;
                    string pack = StickerTransition.ResolvePackId(Assets, _songName, _chart?.PlayerCharacter);
                    StickerTransition.Start(Game.Scenes, Assets, n => Audio.PlaySound(n), pack,
                        () => toStory ? new StoryModeScene() : new FreeplayScene { ForceSkipIntro = true });
                }















                break;















        }















    }















    















    private void DrawPauseOverlay(SpriteBatch spriteBatch)















    {
        DrawPauseOverlayV(spriteBatch); // PauseSubState port: Scenes/PlayScene.Pause.cs
        if (spriteBatch != null) return;
















        // === Semi-transparent black background (original: alpha 0->0.6, 0.8s quartOut) ===















        spriteBatch.Draw(Assets.Pixel, 















            new Rectangle(0, 0, FNFGame.SCREEN_WIDTH, FNFGame.SCREEN_HEIGHT), 















            Color.Black * _pauseBgAlpha);















        















        // === Metadata in top-right (original: vcr.ttf, 32px, right-aligned, staggered fade-in) ===















        var metaFont = Assets.GetFont(32);















        if (metaFont != null)















        {















            int metaX = FNFGame.SCREEN_WIDTH - 20;















            int metaY = 15;















            int lineH = 32;















            int lineIdx = 0;















            















            // Line 0: Song name (original: just the song name, no prefix)















            string songDisplay = (_chart?.SongName ?? _songName ?? "").Replace("-", " ").Replace("_", " ");















            songDisplay = System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(songDisplay);















            float a0 = GetMetadataLineAlpha(lineIdx * 0.1f);















            DrawRightAligned(spriteBatch, metaFont, songDisplay, metaX, metaY + lineH * lineIdx, Color.White * a0);















            lineIdx++;















            















            // Line 1: Artist (original: "Artist: Kawai Sprite", cycles to Charter after 15s)















            string artistText = $"Artist: {_chart?.Artist ?? "Unknown"}";















            float a1 = GetMetadataLineAlpha(lineIdx * 0.1f);















            DrawRightAligned(spriteBatch, metaFont, artistText, metaX, metaY + lineH * lineIdx, Color.White * a1);















            lineIdx++;















            















            // Line 2: Difficulty (original: "Difficulty: Easy/Normal/Hard")















            string diffDisplay = System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(















                _chart?.Difficulty ?? _currentDifficulty ?? "normal");















            string diffText = $"Difficulty: {diffDisplay}";















            float a2 = GetMetadataLineAlpha(lineIdx * 0.1f);















            DrawRightAligned(spriteBatch, metaFont, diffText, metaX, metaY + lineH * lineIdx, Color.White * a2);















            lineIdx++;















            















            // Line 3: Blue Balls (original: "{deathCounter} Blue Balls")















            string deathText = $"{_deathCounter} Blue Balls";















            float a3 = GetMetadataLineAlpha(lineIdx * 0.1f);















            DrawRightAligned(spriteBatch, metaFont, deathText, metaX, metaY + lineH * lineIdx, Color.White * a3);















            lineIdx++;















            















            // Line 4: PRACTICE MODE (only when enabled)















            if (_practiceMode)















            {















                float a4 = GetMetadataLineAlpha(lineIdx * 0.1f);















                DrawRightAligned(spriteBatch, metaFont, "PRACTICE MODE", metaX, metaY + lineH * lineIdx, Color.White * a4);















            }















        }















        















        // === Offset text bottom-right (original: vcr.ttf, 16px, right-aligned) ===















        var offsetFont = Assets.GetFont(16);















        if (offsetFont != null)















        {















            int offsetX = FNFGame.SCREEN_WIDTH - 20;















            float offsetAlpha = GetMetadataLineAlpha(0.5f);















            















            string offsetStr = $"Global Offset: {_globalOffset}ms";















            int offsetY = FNFGame.SCREEN_HEIGHT - 56;















            DrawRightAligned(spriteBatch, offsetFont, offsetStr, offsetX, offsetY, Color.White * offsetAlpha);















            DrawRightAligned(spriteBatch, offsetFont, "Hold SHIFT-UP/DOWN,", offsetX, offsetY + 16, Color.White * offsetAlpha);















            DrawRightAligned(spriteBatch, offsetFont, "to change the offset.", offsetX, offsetY + 32, Color.White * offsetAlpha);















        }















        















        // === Song time progress bar (P2) ===















        float timeAlpha = GetMetadataLineAlpha(0.3f);















        if (timeAlpha > 0.01f)















        {















            int barW = 320;















            int barH = 8;















            int barX = FNFGame.SCREEN_WIDTH - barW - 20;















            int barY = 155;















            double audioLen = Audio.MusicLength;















            float songLen = audioLen > 1 ? (float)audioLen : (float)(_chart?.SongLength ?? 180);















            if (songLen <= 0) songLen = 1;















            float progress = Math.Clamp((float)_conductor.SongPosition / songLen, 0f, 1f);















            















            // Background bar















            spriteBatch.Draw(Assets.Pixel,















                new Rectangle(barX, barY, barW, barH),















                Color.White * 0.2f * timeAlpha);















            // Fill bar















            spriteBatch.Draw(Assets.Pixel,















                new Rectangle(barX, barY, (int)(barW * progress), barH),















                Color.White * 0.8f * timeAlpha);















            















            // Time text















            var timeFont = Assets.GetFont(14);















            if (timeFont != null)















            {















                int elapsedSec = Math.Max(0, (int)_conductor.SongPosition);















                int totalSec = Math.Max(0, (int)songLen);















                string timeStr = $"{elapsedSec / 60}:{elapsedSec % 60:D2} / {totalSec / 60}:{totalSec % 60:D2}";















                DrawRightAligned(spriteBatch, timeFont, timeStr, FNFGame.SCREEN_WIDTH - 20, barY + barH + 4, Color.White * 0.6f * timeAlpha);















            }















        }















        















        // === Menu items (original: AtlasText BOLD, letter.width*=2, letter.height*=2) ===















        // Original: y = 70*i + 30, x starts at 0















        // AtlasFont.BOLD base size is ~42px, doubled = ~84px visual















        int menuItemSpacing = 120;















        int menuStartY = 180;















        // Keep the selected item anchored near menuStartY by shifting all rows by the smoothed selection offset.















        float scrollOffsetY = -menuItemSpacing * _pauseScrollLerp;















        var alphabetFont = AlphabetFont.Bold;















        if (alphabetFont != null)















        {















            for (int i = 0; i < _pauseItems.Length; i++)















            {















                bool selected = i == _pauseSelection;















                float alpha = (selected ? 1.0f : 0.6f) * _pauseMenuAlpha;















                float yPos = menuStartY + menuItemSpacing * i + scrollOffsetY;















                if (yPos < -menuItemSpacing || yPos > FNFGame.SCREEN_HEIGHT) continue;















                float abScale = 0.85f;















                alphabetFont.DrawString(spriteBatch, _pauseItems[i].ToUpper(),















                    new Vector2(20, yPos), Color.White * alpha, abScale);















            }















        }















        else















        {















            var menuFont = Assets.GetFont(82);















            if (menuFont != null)















            {















                for (int i = 0; i < _pauseItems.Length; i++)















                {















                    bool selected = i == _pauseSelection;















                    float alpha = (selected ? 1.0f : 0.6f) * _pauseMenuAlpha;















                    float yPos = menuStartY + menuItemSpacing * i + scrollOffsetY;















                    if (yPos < -menuItemSpacing || yPos > FNFGame.SCREEN_HEIGHT) continue;















                    menuFont.DrawText(spriteBatch, _pauseItems[i].ToUpper(),















                        new Vector2(20, yPos), Color.White * alpha);















                }















            }















        }















    }















    















    /// <summary>















    /// Get fade-in alpha for a metadata line with staggered delay (original: 1.8s quartOut per line).















    /// </summary>















    private float GetMetadataLineAlpha(float delay)















    {















        float t = Math.Clamp((_pauseTimer - delay) / 1.8f, 0f, 1f);















        return 1f - MathF.Pow(1f - t, 4f); // quartOut easing















    }















    















    /// <summary>















    /// Draw text right-aligned at the given X position.















    /// </summary>















    private void DrawRightAligned(SpriteBatch spriteBatch, FontStashSharp.SpriteFontBase font, 















        string text, int rightX, int y, Color color)















    {















        var size = font.MeasureString(text);















        font.DrawText(spriteBatch, text, new Vector2(rightX - size.X, y), color);















    }















    















    private void DrawGameOverOverlay(SpriteBatch spriteBatch)















    {















        // Original GameOverSubState: black BG (opaque), BF death animation visible on top















        // The stage is NOT visible � it's a solid black background with BF's death sprite















        float bgAlpha = Math.Clamp(_gameOverTimer * 2f, 0f, 1f);















        spriteBatch.Draw(Assets.Pixel, 















            new Rectangle(0, 0, FNFGame.SCREEN_WIDTH, FNFGame.SCREEN_HEIGHT), 















            Color.Black * bgAlpha);















        















        // Draw BF death animation (original: plays firstDeath -> deathLoop -> deathConfirm)















        if (bgAlpha > 0.5f && _boyfriend != null)















        {















            // Play firstDeath on first frame if not already set















            if (_gameOverDeathAnim == "firstDeath" && _gameOverTimer < 0.1f)















            {















                _boyfriend.PlayAnimation("firstDeath");















            }















            















            // Center BF on screen for game over















            float goX = FNFGame.SCREEN_WIDTH / 2f;















            float goY = FNFGame.SCREEN_HEIGHT / 2f;















            _boyfriend.Draw(spriteBatch, Assets, goX, goY);















        }















        















        // "RETRY" / "BACK" hint text (original: appears after 1s)















        if (_gameOverTimer >= 1.0f && !_gameOverConfirmed)















        {















            var hintFont = Assets.GetFont(16);















            if (hintFont != null)















            {















                string hint = "ENTER: Retry   ESC: Exit";















                var hSize = hintFont.MeasureString(hint);















                hintFont.DrawText(spriteBatch, hint,















                    new Vector2((FNFGame.SCREEN_WIDTH - hSize.X) / 2, FNFGame.SCREEN_HEIGHT - 40),















                    Color.White * 0.5f);















            }















        }















        















        // Fade to black on confirm (original: camera.fade(BLACK, 1, true) -> needsReset)















        if (_gameOverConfirmed)















        {















            float fadeAlpha = Math.Clamp(_gameOverFadeTimer / 1.0f, 0f, 1f);















            spriteBatch.Draw(Assets.Pixel, 















                new Rectangle(0, 0, FNFGame.SCREEN_WIDTH, FNFGame.SCREEN_HEIGHT), 















                Color.Black * fadeAlpha);















        }















    }















    















    private void DrawText(SpriteBatch spriteBatch, string text, Vector2 pos, Color color, int fontSize = 24)















    {















        var font = Assets.GetFont(fontSize);















        if (font != null)















        {















            font.DrawText(spriteBatch, text, pos, color);















        }















    }















}































